window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-ortopedia-ort-unico"]={"block":"medcurso:medcurso-ortopedia-ort-unico","label":"Medcurso · ORT UNICO","count":393,"questions":[{"id":"medcurso-ortopedia-ort-unico-343787","number":"343787","sourceNumber":"343787","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As infecções osteoarticulares são mais comuns nas crianças abaixo de 5 anos, do sexo\nmasculino e em geral atingem pacientes hígidos. A respeito das infecções osteoarticulares em\npediatria, marque a opção correta.","options":{"A":"Nas artrites sépticas, as articulações mais frequentemente envolvidas são as do joelho e\nquadril.","B":"O agente etiológico mais frequentemente envolvido é o Streptococcus pyogenes.","C":"As osteomielites crônicas são as que possuem duração entre 2 semanas e 3 meses.","D":"A leucocitose no hemograma está sempre presente."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-343790","number":"343790","sourceNumber":"343790","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Escolar de 6 anos de idade, comparece ao ambulatório de pediatria com relato de dor\nbilateral em região de coxas e panturrilhas. Nega febre e outras queixas associadas. Refere que a\ndor ocorre em períodos noturnos, em especial nos dias em que a criança corre muito e joga futebol.\nA mãe nega edema, calor e rubor no membro. Diante do exposto, o caso trata-se qual das\ncondições clínicas abaixo?","options":{"A":"Doença de Legg-Perthes-Calvé.","B":"Doença de Osgood-Schlatter.","C":"Dor do crescimento.","D":"Considerando o período noturno deve ser considerado a leucemia linfóide aguda."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-283296","number":"283296","sourceNumber":"283296","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A dor do crescimento é a causa mais comum de dor musculoesquelética na criança, em\ngeral ocorre entre 4 a 12 anos de idade, sendo característica da mesma, todas as abaixo,\nEXCETO:","options":{"A":"Associação com sintomas como febre, anorexia e fraqueza muscular.","B":"Apesar de comumente acordar a criança à noite, pela manhã ela é assintomática.","C":"A dor ocorre nos membros inferiores e bilateralmente.","D":"A frequência varia podendo a criança permanece sem sintomas por meses."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-251951","number":"251951","sourceNumber":"251951","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente, 22 anos refere dor no tornozelo após entorse durante jogo de basquete. Ao\nexame físico, apresenta incapacidade\nfuncional, edema +++/4 na parte lateral do tornozelo e dor à\npalpação do maléolo lateral. Qual a conduta?","options":{"A":"Medicações sintomáticas, bolsa de gelo e muletas enquanto dor. Retornar para reavaliação se\npersistência da dor após 7 dias.","B":"Radiografias de tornozelo - série trauma.","C":"Tomografia Computadorizada de tornozelo.","D":"Ressonância Magnética Nuclear de tornozelo."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-217698","number":"217698","sourceNumber":"217698","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O quadro conhecido como \"epicondilite lateral\" é uma entesite (inflamação tendínea no\nponto de inserção óssea) que se caracteriza por:","options":{"A":"Dor na face lateral do ombro, com piora à elevação do braço.","B":"Dor face lateral do joelho com piora à deambulação ou corrida.","C":"Dor na face lateral do cotovelo, com piora à extensão do punho e dedos contra resistência.","D":"Dor na face lateral do cotovelo, com piora à flexão do punho e dedos contra resistência."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183181","number":"183181","sourceNumber":"183181","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Assinale a alternativa INCORRETA.","options":{"A":"O diagnóstico de fibromialgia (FM) é puramente clínico, não havendo exame complementar que\nfavoreça a sua realização.","B":"Dor generalizada associada à rigidez articular, fadiga e distúrbios do sono são alterações\ncomuns na FM.","C":"O tendão do músculo supra-espinhal é o principal tendão envolvido na síndrome do impacto dos\nombros.","D":"A epicondilite lateral, ou cotovelo de tenista, é causada pela lesão do tendão do flexor comum\nem sua inserção no cotovelo.","E":"A tendinite de Dequervain corresponde à lesão dos tendões do extensor curto e do abdutor\nlongo do polegar."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-29344","number":"29344","sourceNumber":"29344","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As osteocondroses são frequentes na idade escolar e na adolescência, sendo causas\nde dores nos membros inferiores. A que\nacomete a tuberosidade anterior da tíbia é conhecida\ncomo:","options":{"A":"Doença de Legg-Calvé-Perthes","B":"Doença de Sever","C":"Doença de Osgood-Schlatter","D":"Doença de Scheuermann","E":"Doença de Kohler"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-249400","number":"249400","sourceNumber":"249400","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente do sexo masculino, 14 anos, refere dor nas costas há 5 semanas tanto ao\njogar voleibol (pratica todos os dias por 3 horas) como em repouso, às vezes piorando em repouso.\nJá procurou atendimento e o médico disse ser ?dor do crescimento? e que as dores vão passar\ncom o tempo. Com bases nessas informações, qual a hipótese diagnóstica?","options":{"A":"Doença de Sever.","B":"Espondilólise.","C":"Tumor de vértebras.","D":"Artrite reumatoide juvenil."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-215222","number":"215222","sourceNumber":"215222","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Das alternativas citadas abaixo, qual apresenta sinais de fratura de base de crânio?","options":{"A":"Equimose periorbitária e de mastoide e otorragia.","B":"Hematoma em região zigomática, saída de liquor pelo nariz e hematoma parietal.","C":"Sangramento nasal, afundamento de órbita e hemotímpano.","D":"Hematoma occipital, otorragia e hematoma de mastoide."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-215226","number":"215226","sourceNumber":"215226","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual alternativa apresenta o tipo de fratura que compreende 75% das fraturas de crânio\nem crianças?","options":{"A":"Aberto.","B":"Diastático.","C":"De afundamento.","D":"Linear."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-216231","number":"216231","sourceNumber":"216231","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"São consideradas lesões benignas da parede torácica, EXCETO","options":{"A":"Fibroma.","B":"Osteocondroma.","C":"Sarcoma de Ewing.","D":"Tumor desmoide."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-212192","number":"212192","sourceNumber":"212192","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Até o ano de 2015, os patógenos mais frequentemente relacionados às infecções\nintrauterinas eram a bactéria Treponema\npallidum, o protozoário Toxoplasma gondii, o vírus da\nrubéola, Citomegalovirus e Herpes simplex. Com a introdução do vírus Zika no Brasil, houve uma\nepidemia de malformações congênitas, levando à necessidade de seu monitoramento integrado.\nQue ação(ões) devem ser executada(s) diante de um recém-nascido com pés tortos congênitos?","options":{"A":"Realizar interconsulta com o geneticista e solicitar um cariótipo antes da alta hospitalar.","B":"Encaminhar para correção cirúrgica o mais breve possível, pela impossibilidade de intervenção\nnuma fase posterior.","C":"Relacionar o achado com a Sífilis materna e levar em consideração os exames realizados antes\nda gravidez e durante o pré-natal.","D":"Atentar para o diâmetro da circunferência craniana menor que ? 3 desvios ? padrão para idade\ngestacional e sexo, de acordo com a curva InterGrowth, devido a possibilidade de microcefalia.","E":"Notificar o caso no Registro de Eventos em Saúde Pública (RESP) e investigar infecção materna\npelo vírus Zika durante a gestação, realizar\nos cuidados clínicos e os encaminhamentos\nnecessários."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-161367","number":"161367","sourceNumber":"161367","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A fratura é considerada exposta quando se comunica com o meio externo. Gustilo e\nAnderson elaboraram classificações mais comumente citadas das fraturas com lesão de partes\nmoles. Essa classificação proporcionou informações úteis em relação ao prognóstico e tratamento\nda extremidade lesada. Indique a alternativa que associa CORRETAMENTE a lesão, segundo esta\nclassificação, a seu respectivo antibiótico de escolha.","options":{"A":"II ? lesão de pele aberta < 1 cm, limpa, mais provavelmente uma lesão de dentro para fora,\nmínima contusão muscular, fratura oblíqua ou transversa simples. Antibióticos de escolha são\ncefalosporinas de primeira geração.","B":"IIIA ? laceração > 1 cm, com extenso dano de partes moles, retalhos ou avulsão, esmagamento\nmoderado, fratura oblíqua curta ou transversa\nsimples com mínima cominução. Antibiótico de\nescolha é cefalosporina de primeira geração associado a aminoglicosídeo.","C":"IIIB ? laceração extensa, com cobertura adequada do osso, fratura segmentar, lesões por arma\nde fogo. Antibiótico de escolha é\ncefalosporina de primeira geração associado a aminoglicosídeo.","D":"IIIC ? extenso dano de partes moles, incluindo músculo, pele, estruturas neurovasculares,\nfrequentemente uma lesão de alta velocidade com\num severo componente de esmagamento, inclui\nqualquer lesão aberta com lesão vascular necessitando de reparo. Antibiótico de escolha é\ncefalosporina de primeira geração, associado a aminoglicosídeo e penicilina G."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-110029","number":"110029","sourceNumber":"110029","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O agente etiológico que MAIS comumente causa osteomielite em crianças de 2 anos de\nidade é","options":{"A":"Estreptococos do grupo A.","B":"Stafilococcus aureus.","C":"Streptococcus pneumoniae.","D":"Pseudômonas aeruginosa."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-110543","number":"110543","sourceNumber":"110543","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Trauma vascular de artéria umeral em criança, qual a principal fratura envolvida?","options":{"A":"Clavícula.","B":"Fratura de colo de úmero.","C":"Fratura supra-condiliana de úmero.","D":"Fratura de rádio.","E":"Fratura de ulna."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-86632","number":"86632","sourceNumber":"86632","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A lombalgia é responsável por uma grande parte das faltas ao trabalho e suas\nrepercussões econômicas. Alguns estudos de demanda estimam que esteja entre os 5 a 10\ndiagnósticos mais frequentes. Sobre a lombalgia é CORRETO afirmar:","options":{"A":"A radiografia é o exame complementar de escolha na abordagem inicial, devido à alta correlação\nentre alterações anatômicas e a causa das dores.","B":"Manobra de Lasègue é positiva quando o paciente referir dor irradiada quando a perna é\nelevada até 30°.","C":"O repouso e afastamento prolongado do trabalho está como uma das medidas terapêuticas mais\neficazes no arsenal das não medicamentosas.","D":"Explicar o tempo esperado para alívio da dor, reforçar que tem grandes chances de remissão ou\nmelhora significativa ajudam na recuperação.","E":"Podem ser considerados sinais de cronicidade o uso de medicamentos por mais de 4 semanas."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-327240","number":"327240","sourceNumber":"327240","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher, 54 anos, com ombro doloroso à direita e suspeita clínica de lesão do manguito\nrotador. Ao exame, ombro direito com dor e\nimportante limitação para rotação interna. O músculo\nmais provavelmente comprometido é:","options":{"A":"Redondo menor.","B":"Supraespinhal.","C":"Infraespinhal.","D":"Subescapular."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-298251","number":"298251","sourceNumber":"298251","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Recém-nascido de parto vaginal a fórceps apresenta reflexo de Moro assimétrico no\nprimeiro dia de vida, com pouco movimento do braço esquerdo, que fica mantido em rotação\ninterna ao lado do corpo com o antebraço estendido e em pronação. O restante do exame físico é\nnormal, inclusive a preensão palmar da mão esquerda. O provável diagnóstico é:","options":{"A":"Fratura de clavícula","B":"Paralisia do nervo frênico","C":"Paralisia de Erb-Duchenne","D":"Paralisia de Klumpke"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-252247","number":"252247","sourceNumber":"252247","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Nos pacientes politraumatizados, podemos identificar fraturas e luxações dos membros.\nA luxação do ombro é uma delas e identificamos\no sinal:","options":{"A":"Hirtz","B":"Fothergill","C":"Shatsky","D":"Dragona"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-208348","number":"208348","sourceNumber":"208348","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sinal de Terry Thomas está presente:","options":{"A":"Fratura distal do Rádio","B":"Fratura distal da Ulna","C":"Deslocamento Escafosemilunar","D":"Fratura do Escafóide"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-176104","number":"176104","sourceNumber":"176104","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na osteomielite, a lesão causada pela pressão intraóssea aumentada, somada à\nisquemia determinada pelo descolamento do periósteo, é conhecida como:","options":{"A":"Abscesso de Brodie.","B":"Invólucro.","C":"Sequestro.","D":"Triângulo de Codman."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-103802","number":"103802","sourceNumber":"103802","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança de 14 meses é trazida à consulta por claudicação desde que começou a andar.\nO exame físico revela que, além da alteração\nda marcha, a perna direita é menor que a esquerda e\na abdução da articulação coxofemural direita é limitada. O provável diagnóstico é:","options":{"A":"Doença de Legg - Perthes","B":"Displasia do desenvolvimento do quadril","C":"Sinovite transitória do quadril","D":"Paralisia cerebral, forma motora"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-60905","number":"60905","sourceNumber":"60905","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O trauma crônico e repetitivo que leva a rupturas microscópicas quando o osso sofre\numa carga superior ao seu ponto de colapso, é conhecida como:","options":{"A":"Fratura crônica","B":"Fratura espirais","C":"Fratura em \"torus\"","D":"Fratura de estresse","E":"Fratura em galho verde"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-49815","number":"49815","sourceNumber":"49815","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É correto afirmar com relação as fraturas expostas:","options":{"A":"As lesões de pele associadas devem sempre ser fechadas no primeiro atendimento;","B":"Se tratadas após 8 horas de evolução desenvolvem infecção com maior frequência;","C":"A gravidade das lesões de partes moles não influenciam no prognóstico;","D":"São sempre associadas à lesão arterial;","E":"A medida terapêutica de maior eficácia é a antibioticoterapia."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-34182","number":"34182","sourceNumber":"34182","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual o agente etiológico encontrado na infecção por osteomielite em faixa etária de 0 a\n28 dias de vida?","options":{"A":"Pseudomonas.","B":"Klebisiella.","C":"Staphylococcus aureus.","D":"Adenovírus.","E":"Candida."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-26666","number":"26666","sourceNumber":"26666","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na fratura supracondiliana de cotovelo em crianças, tipo I de Gartland sem desvio, o\ntratamento inicial na urgência é:","options":{"A":"Tala gessada axilopalmar com cotovelo em flexão de 90°","B":"Tala gessada axilopalmar com cotovelo em extensão","C":"Gesso circular axilopalmar com cotovelo em flexão de 90°","D":"Gesso axilopalmar com cotovelo em flexão de 80°","E":"Tala gessada axilopalmar com cotovelo em flexão de 80°"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-13278","number":"13278","sourceNumber":"13278","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente tem diagnóstico de lúpus eritematoso sistêmico há 4 anos, com acometimento\nrenal hematológico, neurológico e cutâneo,\ndependente de corticoide. Nos últimos 6 meses usou 10\ngramas de corticoide e 6 gramas de ciclofosfamida. Há dois meses vem queixando-se de dor na\nregião do quadril direito, principalmente no final do dia após longas caminhadas. A provável causa\nda dor é:","options":{"A":"Artrite pelo LES.","B":"Artrite séptica.","C":"Necrose avascular de colo do fêmur.","D":"Bursite hansênica.","E":"Lombociatalgia."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-13285","number":"13285","sourceNumber":"13285","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente com lombalgia, sem história de trauma, atendido no pronto-socorro, com\nexame neurológico normal e contratura da\nmusculatura paravertebral. A suspeita diagnóstica mais\nprovável se o paciente tiver, respectivamente, 10, 30 e 60 anos de idade, é:","options":{"A":"espondilolise - lombalgia postural - tumor metastático.","B":"escoliose - espondilolise - lombalgia postural.","C":"tumor metastático - mieloma - artrite reumatoide.","D":"tumor metastático - mieloma - artrite.","E":"tumor de Wilms - escoliose - osteoporose."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-9972","number":"9972","sourceNumber":"9972","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre as síndromes dolorosas da coluna tóraco-lombar, podemos afirmar que:","options":{"A":"A estenose do canal lombar é frequente e atinge qualquer faixa etária, mas que atinge\npreferencialmente a população entre 20 a 30 anos.","B":"A hérnia discal lombar é a forma mais frequente de hérnia de disco em toda a coluna vertebral e\npodemos dizer que a cirurgia de urgência está indicada na síndrome da cauda equina.","C":"Na hérnia discal lombar os níveis de L1- L2 e L2- L3 são os mais frequentes, e na hérnia discal\ntorácica são os níveis de T7- T8 e T8- T9.","D":"O tratamento da hérnia discal lombar é eminentemente cirúrgico, sendo o tratamento\nconservador utilizado apenas em casos mais leves\ne por uma ou duas semanas. Se não melhorar,\na cirurgia está indicada.","E":"Na síndrome da cauda equina a forma aguda é que menos preocupa e sua etiologia é mais\nfrequentemente associada aos tumores."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-7484","number":"7484","sourceNumber":"7484","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre as fraturas de membro inferior em crianças assinale a afirmativa INCORRETA:","options":{"A":"A mais comum é a do fêmur e está relacionada significativamente à colisão de automóveis.","B":"As fraturas da tíbia são as mais frequentes e causadas, na maioria das vezes, por quedas pouco\nimportantes.","C":"A localização da fratura, sua gravidade e a idade da criança influenciam no tratamento.","D":"Muitas dessas fraturas acontecem em crianças ainda aprendendo a andar ou são fraturas de\nbaixa energia e sem deslocamento.","E":"Colisões de automóveis e lesões de alta energia são mais comuns em crianças mais maduras,\nresultando em fraturas da tíbia e da fíbula."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-139794","number":"139794","sourceNumber":"139794","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No sinal de Galeazzi, observa-se uma diferença de nível dos joelhos com a criança\ndeitada e com os membros fletidos. Aponte a\nalternativa que representa a patologia em que esse\nsinal clínico é encontrado.","options":{"A":"Luxação do quadril.","B":"Artrite séptica do joelho.","C":"Osteocondrite de calcâneo.","D":"Cifose do adolescente."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-321294","number":"321294","sourceNumber":"321294","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Trabalhador da construção civil sofre acidente com queda de andaime posicionado no\n3º andar da obra. Qual das seguintes lesões\napresenta maior probabilidade de ocorrência?","options":{"A":"Fratura de metatarso.","B":"Fratura de antebraço.","C":"Fratura de quadril.","D":"Trauma de crânio."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-199765","number":"199765","sourceNumber":"199765","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma senhora de 82 anos, hipertensa e diabética, foi admitida em uma UPA com dor no\nquadril à direita, após uma queda de própria altura. No exame ela apresentava estabilidade\nhemodinâmica, incapacidade de deambulação e dor forte à tentativa de mobilização do quadril à\ndireita especialmente à tentativa de rotação do membro. Foi realizado RX simples da bacia em AP\nalém de estudo detalhado da articulação coxo-femoral acometida em AP e Perfil evidenciando uma\nfratura de colo de fêmur sem desvio. Qual o tratamento mais adequado a essa paciente?","options":{"A":"Cirúrgico eletivo devido ao baixo risco de complicações.","B":"Conservador referindo a serviço ambulatorial de ortopedia.","C":"Conservador transferindo para internação em enfermaria de ortopedia.","D":"Cirúrgico de urgência pelo risco de necrose avascular da cabeça do fêmur."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-199758","number":"199758","sourceNumber":"199758","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente com 45 anos apresenta dor na região do ombro esquerdo, progressiva nos\núltimos 6 meses. Está relacionada com\ncertos movimentos do membro superior, principalmente à\nabdução acima da linha da escápula durante prática esportiva e na sua atividade laboral, a qual\nexerce com um pouco de dificuldade por causa da dor. Nota também que às vezes, à noite, mesmo\nem repouso, tem episódios dolorosos que o incomodam durante o sono ao se deitar sobre o ombro.\nÉ praticante de basquetebol, desde a adolescência. Acerca da situação descrita pode se afirmar\nque:","options":{"A":"O paciente tem um diagnóstico de síndrome da ruptura de manguito rotador.","B":"A progressão dos sintomas foi decorrente de ruptura total de tendão na região do ombro.","C":"O impacto em qualidade de vida deve ser fator determinante na escolha do tipo de tratamento.","D":"Deve-se realizar uma tomografia computadorizada para decidir a indicação do tratamento\ncirúrgico."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-102085","number":"102085","sourceNumber":"102085","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 45 anos, sexo masculino, vítima de acidente automobilístico apresentando\nfratura exposta de fêmur à direita, classificada\ncomo Gustilo tipo I. Com relação ao caso descrito,\nassinale a alternativa CORRETA:","options":{"A":"Deve-se fazer a limpeza exaustiva da ferida, seguida de fixação externa da fratura.","B":"Nesse tipo de fratura, os índices de infecção variam de 10% a 20%, daí a importância do uso de\nantibioticoterapia concomitante.","C":"Trata-se de uma fratura de fêmur com estabilidade moderada, com laceração cutânea maior que\n1 cm, sem sinais de contusão e apresentando\nmusculatura viável.","D":"Prevenir a ocorrência de infecção, promover a restauração das partes moles e fixar a fratura\ncom alinhamento adequado são os objetivos iniciais\npara o tratamento."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-91279","number":"91279","sourceNumber":"91279","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 27 anos, após colisão de veículos apresentou uma fratura do tálus\ncom traço na sua porção central ( fechada/ tipo Hawkins III ), qual a incidência de necrose\navascular?","options":{"A":"0%-10%.","B":"20%-50%.","C":"50%-70%.","D":"80%-100%."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-81253","number":"81253","sourceNumber":"81253","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um jovem de 25 anos levou uma queda durante a prática esportiva e foi atendido em\numa emergência cirúrgica. Feito o exame clínico\ne propedêutica radiológica, foi constatada fratura\ndistal do rádio. Qual das afirmativas abaixo contempla o tratamento por meio de redução incruenta\nmais imobilização?","options":{"A":"Fratura cominutiva metafisária.","B":"Fratura extra-articular estável.","C":"Fratura intra-articular cominutiva.","D":"Fratura articular marginal com subluxação radiocárpica."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-91347","number":"91347","sourceNumber":"91347","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A pseudoartrose congenital da tíbia apresenta as seguintes características, exceto:","options":{"A":"angulação antero-lateral.","B":"consolidação espontânea não ocorre.","C":"no seu foco encontramos um neurofibroma.","D":"mais de 50% dos pacientes apresentam neurofibromatose tipo I."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-91349","number":"91349","sourceNumber":"91349","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A coalisão talocalcânea é uma conexão anormal entre o tálus e o calcâneo que resulta\nem um pé plano rígido. Sobre essa entidade\npodemos afirmar que:","options":{"A":"a faceta mais comprometida é a média.","B":"os sintomas álgicos aparecem entre 4 e 7 anos.","C":"a grande maioria apresenta sintomatologia álgica.","D":"o objetivo principal do tratamento é a restauração da mobilidade."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-91352","number":"91352","sourceNumber":"91352","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A lesão que menos se encontra associada à luxação traumática do quadril:","options":{"A":"fratura da diáfise do fêmur.","B":"fratura do colo femoral.","C":"fratura do anel pélvico.","D":"fratura da tíbia."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-91356","number":"91356","sourceNumber":"91356","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual a lesão mais frequentemente associada à fratura do planalto tibial?","options":{"A":"Lesão do ligamento patelofemoral medial.","B":"Lesão do ligamento cruzado anterior.","C":"Lesão meniscal.","D":"Lesão vascular."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-91361","number":"91361","sourceNumber":"91361","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Nas fraturas do tálus o sinal de Hawkins, não podemos afirmar que:","options":{"A":"aparece entre a sexta e oitava semana pós-trauma.","B":"é menos preditivo que a ressonância magnética.","C":"é indicativo de bom prognóstico de necrose.","D":"é indicativo de pseudoartrose."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-71801","number":"71801","sourceNumber":"71801","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 16 anos, atleta arremesador de peso, apresenta dor lombar. A\nimagem de SPECT demonstra uma fratura unilateral da pars de L2 à esquerda. Qual a melhor\nconduta para este atleta?","options":{"A":"Colete de Boston.","B":"Rizotomia.","C":"Artrodese.","D":"Bloqueio seletivo da raiz nervosa.","E":"Uma dose de corticoide de depósito."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-65749","number":"65749","sourceNumber":"65749","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Homem de 25 anos procura assistência médica com dor e edema na região do punho,\napós queda de skate. Refere ter caído com a\nmão estendida para trás. Foi solicitada a radiografia\nreproduzida na figura abaixo. Qual o osso lesionado? (VER IMAGEM)","options":{"A":"Capitato.","B":"Navicular.","C":"Escafoide.","D":"Semilunar.","E":"Fusiforme."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/65749.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-54806","number":"54806","sourceNumber":"54806","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Segundo Levine, na redução da luxação posterior de quadril, quando detectamos\ninstabilidade associada a encarceramento de cartilagem, de labrum ou de osso, tal luxação\ncorresponde ao tipo:","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-30862","number":"30862","sourceNumber":"30862","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Como é executado o teste de Tinel na investigação clínica da síndrome do túnel do\ncarpo?","options":{"A":"Digitopercussão sobre o nervo mediano ao nível do punho.","B":"Flexão do punho em 90 graus durante 1 minuto.","C":"Preensão firme dos dedos sobre polegar e flexão da mão.","D":"Levantamento de peso com punho reto por 3 minutos.","E":"Flexão-extensão repetitiva do punho por 1 minuto."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-37643","number":"37643","sourceNumber":"37643","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Tainará, 12 anos, sofreu lesão na articulação do cotovelo, após cair de um lugar cuja\naltura era equivalente a sua. A menina\nqueixava-se de dor na articulação. Ao examiná-la, Dr. Emílio\ndetectou sinovite traumática leve e limitação da mobilidade sem impotência funcional. Qual a\nconduta mais adequada?","options":{"A":"Repouso, calor local, imobilização junto ao tronco para reduzir movimentos e dor e paracetamol.","B":"Fisioterapia motora, aplicação de gelo, contensão elástica com acolchoamento de algodão para\nreduzir movimentos e dor, elevação do membro e paracetamol.","C":"Repouso, aplicação de gelo, contensão elástica com acolchoamento de algodão para reduzir\nmovimentos e dor, elevação do membro e anti-inflamatórios não esteroides.","D":"Fisioterapia motora, calor local, contensão\n\nelástica com acolchoamento de algodão para reduzir movimentos e dor, elevação do membro e\nanti-inflamatórios não esteroides."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-25473","number":"25473","sourceNumber":"25473","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma mulher de 40 anos chega à emergência do HUWC depois de uma queda\nenquanto saía do ônibus sentindo forte dor\nno braço direito. O exame físico sugere fratura do\número, confirmada após exame radiológico. Ela consegue estender o antebraço no cotovelo, mas\nseu movimento de supinação parece enfraquecido e seu aperto de mão é muito fraco comparado\nao da mão esquerda. Percebe-se que ela está incapaz de estender o punho, permanecendo a mão\ncaída.Sabendo que a extensão no cotovelo parece normal, mas que a supinação do antebraço está\nenfraquecida, qual a opção que indica o local do nervo lesionado?","options":{"A":"Nervo radial no terço distal do úmero","B":"Nervo radial no médio antebraço","C":"Nervo ulnar nas proximidades da cabeça da ulna","D":"Nervo radial nas proximidades da cabeça da ulna","E":"Divisões posteriores do plexo braquial"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-25474","number":"25474","sourceNumber":"25474","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma mulher de 40 anos chega à emergência do HUWC depois de uma queda\nenquanto saía do ônibus sentindo forte dor\nno braço direito. O exame físico sugere fratura do\número, confirmada após exame radiológico. Ela consegue estender o antebraço no cotovelo, mas\nseu movimento de supinação parece enfraquecido e seu aperto de mão é muito fraco comparado\nao da mão esquerda. Percebe-se que ela está incapaz de estender o punho, permanecendo a mão\ncaída. A paciente apresenta enfraquecimento considerável na supinação quando a articulação do\ncotovelo está completamente estendida, no entanto, pequeno enfraquecimento evidente no\nmovimento de supinação quando o cotovelo é fletido parcialmente. Qual a opção que dá o motivo\ndesta observação?","options":{"A":"O músculo supinador não está paralisado","B":"O músculo bíceps do braço está realizando esse movimento","C":"O músculo braquial está funcionando","D":"O pronador redondo está funcionando","E":"O músculo tríceps do braço é um potente supinador"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-25381","number":"25381","sourceNumber":"25381","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma criança, após queda no parquinho do clube, fraturou o colo da fíbula, qual dos\nnervos, dentre as opções abaixo, corre o risco de ser cortado?","options":{"A":"Nervo safeno","B":"Nervo lateral da sura","C":"Nervo fibular comum","D":"Nervo tibial","E":"Nervo isquiático"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-29453","number":"29453","sourceNumber":"29453","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança de dois anos veio ao CSF com história de febre alta há 48 horas, dor de\ngarganta e tosse rouca. Ao exame do\norofaringe, havia uma hiperemia intensa das amígdalas. Esse\nquadro é mais sugestivo de:","options":{"A":"Amigdalite bacteriana;","B":"Amigdalite viral;","C":"Laringite bacteriana;","D":"Traqueíte viral."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-25391","number":"25391","sourceNumber":"25391","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 28 anos, jogador profissional de futebol, após trauma há 4 horas,\napresenta dor e grande edema e equimose na mão. O Rx da mão em oblíqua encontra-se ao lado.\nEscolha respectivamente o diagnóstico e o tratamento atual. (VER IMAGEM)","options":{"A":"fraturas múltiplas dos metacarpianos, síntese com placas e parafusos","B":"fratura de Bennet + luxação metacarpos, redução e fixação com fios de Kirschner","C":"fratura ? luxação do punho, redução incruenta + luva de gesso","D":"fratura de Rolando+ fratura de metacarpo, luva de gesso","E":"fratura do escafoide + fratura de metatarsianos, síntese com fios de Kirschner"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-25397","number":"25397","sourceNumber":"25397","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente feminino, 1 ano e 2 meses, apresenta marcha claudicante, limitação da\nabdução no quadril esquerdo. O exame físico\nilustrado foi positivo e o Rx da bacia em AP\nencontra-se ao lado. Correlacione o achado no exame físico, o diagnóstico e o (s) achado (s)\nradiológico (s) observado (s) a seguir: VER IMAGEM","options":{"A":"sinal de Galeazzi, coxa vara do desenvolvimento, aumento do índice acetabular","B":"sinal da telescopagem, luxação congênita quadril, arco de Shenton interrompido","C":"manobra de Ortolani, luxação glenofemural, diminuição do ângulo beta de Graf","D":"teste de Barlow, coxa vara congênita, diminuição índice acetabular","E":"grande trocanter esquerdo abaixo da linha Nélaton, displasia do desenvolvimento do\nquadril , aumento do ângulo alfa de Graf e diminuição do beta"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/25397.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-25351","number":"25351","sourceNumber":"25351","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um homem com 60 anos de idade vai ao posto de saúde queixando-se de dores no\nombro. Após o exame clínico, o médico suspeita que possa tratar-se de uma bursite no ombro.\nQual das opções é a que se associa de forma mais frequente à bursite no ombro?","options":{"A":"Bolsa subdeltoidea","B":"Cápsula da articulação glenoumeral","C":"Bolsa do músculo gastrocnêmio","D":"Cápsula da articulação acromioclavicular","E":"Bolsa subacromial"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-322129","number":"322129","sourceNumber":"322129","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente, 20 anos, teve uma fratura exposta de tíbia grau I de Gustillo-Anderson.\nQual seria a forma mais correta de realizar o\nprimeiro atendimento hospitalar desse paciente?","options":{"A":"Profilaxia com ceftriaxona e vacina antitetânica seguida de lavagem e desbridamento cirúrgico.","B":"Iniciar antibiótico de forma terapêutica com ciprofloxacino, realizar vacina antirrábica e seguir\ncom lavagem e redução local da fratura.","C":"Redução da fratura após analgesia, lavagem e antibioticoterapia profilática com vancomicina\ndurante a indução anestésica.","D":"Profilaxia com cefalotina e vacina antitetânica seguida de lavagem e desbridamento\ncirúrgico/redução da fratura.","E":"Analgesia, profilaxia com vacina antitetânica e ciprofloxacino e redução imediata da fratura\nseguidas de lavagem e desbridamento cirúrgico."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-305274","number":"305274","sourceNumber":"305274","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente de 10 anos teve uma fratura no antebraço esquerdo. Quanto ao tipo de\nfratura que pode ter ocorrido nesse caso e suas características, assinale a alternativa CORRETA.","options":{"A":"Fratura em galho verde ? desvio da cortical óssea sem uma linha visível de fratura.","B":"Fratura metafisária ? fratura através da placa cartilaginosa de crescimento.","C":"Fratura em galho verde ? ruptura incompleta da cortical óssea.","D":"Fratura em fivela ? fratura através da placa cartilaginosa de crescimento.","E":"Fratura em fivela ? fratura de uma área enfraquecida devido a uma doença preexistente."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-305288","number":"305288","sourceNumber":"305288","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Referente à osteomielite, é CORRETO afirmar que:","options":{"A":"A forma não hematogênica é mais comum em adultos jovens, vítimas de trauma com solução de\ncontinuidade na pele.","B":"A radiografia simples pode auxiliar no diagnóstico, principalmente na fase inicial da doença.","C":"A maioria dos antimicrobianos possui boa distribuição na medula óssea.","D":"Os marcadores inflamatórios mais comuns (velocidade de hemossedimentação e proteína C\nreativa) geralmente são normais nas primeiras 2 semanas de doença.","E":"O uso de Anti-inflamatórios Não Esteroidais (AINEs) é considerado tratamento de primeira\nescolha."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-261225","number":"261225","sourceNumber":"261225","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Esse paciente apresenta\nfator de risco para desenvolvimento de embolia gordurosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-261227","number":"261227","sourceNumber":"261227","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Profilaxia antimicrobiana é\nessencial nesse caso e deve ser feita de forma precoce para minimizar o risco de infecções ósseas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-250105","number":"250105","sourceNumber":"250105","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um exame físico completo deve ser realizado na primeira consulta de puericultura.\nConsiderando essa informação, julgue o item a\nseguir. Identificam-se três fatores de risco para\nluxação congênita do quadril: gênero masculino; história familiar de displasia congênita do\nquadril; e\nparto prematuro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-255771","number":"255771","sourceNumber":"255771","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 28 anos de idade comparece à unidade de saúde da família com história\nde trauma do joelho esquerdo após queda de\nmoto, quando estava se dirigindo ao respectivo local\nde trabalho. Ao exame físico, o joelho referido apresentava aumento de volume e calor local. PA =\n120 mmHg x 80 mmHg; FC = 96 bpm; FR = 16 irpm; SpO2 = 98%. Considerando esse caso clínico\ne os conhecimentos médicos correlatos, julgue o item a seguir. O teste de McMurray será útil para\naveriguar lesão meniscal, e o teste da gaveta anterior para verificar lesão do ligamento cruzado\nanterior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-196662","number":"196662","sourceNumber":"196662","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma mulher de 70 anos de idade, eutrófica, caiu da própria altura. Após a queda,\napresentou intensa dor e foi encaminhada para a\nemergência, onde foram solicitados raios X de\nfêmur esquerdo, representados na imagem. Acerca desse caso clínico, julgue o item a seguir.\nTrata-se de fratura subtrocantérica de cabeça de fêmur, e o tratamento é cirúrgico com\npossibilidade de colocação de prótese.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/196662.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-214494","number":"214494","sourceNumber":"214494","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"H. C. S., primeiro filho de C. C. S., realizou acompanhamento de puericultura em posto\nde saúde desde a primeira consulta pós-natal\naté atualmente, quando tem 8 anos de idade. Ao\nlongo desse acompanhamento, as variações antropométricas foram registradas nas curvas de\ncrescimento (peso para idade, estatura/altura para a idade, IMC para a idade), e o desenvolvimento\npsiconeuromotor foi avaliado. Na primeira consulta, foi verificada história de parto vaginal\nlaborioso,\nmas não havia histórico de outras complicações gestacionais ou periparto. Atualmente, nas curvas\nantropométricas, observam-se z-score de +3,34 no IMC para a idade e z-score de -1,75 na altura\npara a idade. Considerando as várias consultas realizadas nesse período, os raciocínios\ndiagnósticos e as condutas a serem tomadas frente ao crescimento e desenvolvimento normal e\npatológico, julgue o item a seguir. Na primeira consulta de puericultura, estaria recomendada a\nrealização dos testes de Ortolani e Barlow para avaliação de fratura de clavícula intraparto e de\ndestacamento do plexo braquial, respectivamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-177561","number":"177561","sourceNumber":"177561","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"R.D.S, de 32 anos de idade, operadora de caixa, previamente hígida, queixa-se de dor\nno ombro direito há cerca de 1 mês,\nrelacionada com suas atividades trabalhistas. Ao exame físico,\nnota-se desconforto à palpação da topografia de supra-espinhal, testes de Hawkins e Yokum\npositivos, assim como contração contrarresistida dolorosa na abdução e na rotação externa. Os\ntestes neurodinâmicos são negativos. Considerando a hipótese diagnóstica de síndrome do\nimpacto do ombro associada à disfunção de manguito rotador, julgue o item a seguir. O exame de\nimagem é necessário para orientação da terapêutica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-177565","number":"177565","sourceNumber":"177565","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"R.D.S, de 32 anos de idade, operadora de caixa, previamente hígida, queixa-se de dor\nno ombro direito há cerca de 1 mês,\nrelacionada com suas atividades trabalhistas. Ao exame físico,\nnota-se desconforto à palpação da topografia de supra-espinhal, testes de Hawkins e Yokum\npositivos, assim como contração contrarresistida dolorosa na abdução e na rotação externa. Os\ntestes neurodinâmicos são negativos. Considerando a hipótese diagnóstica de síndrome do\nimpacto do ombro associada à disfunção de manguito rotador, julgue o item a seguir. A principal\nbase do tratamento consiste no exercício físico, especialmente com foco na fase excêntrica da\ncontração muscular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-64671","number":"64671","sourceNumber":"64671","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Assinale a alternativa que apresenta os critérios de exclusão entre os critérios\nutilizados\npara identificar as Dores de Crescimento (DCs).","options":{"A":"Dor intermitente.","B":"Dor não articular.","C":"Edema, calor, rubor, limitação de movimentos e claudicação.","D":"Dor bilateral nos membros inferiores.","E":"Ocorrência de dor geralmente no fim do dia ou à noite."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-274600","number":"274600","sourceNumber":"274600","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A medicina física e reabilitação, também chamada de fisiatria, é um ramo da medicina\nque busca o diagnóstico e a terapia de\ndoenças agudas e crônicas, particularmente relacionadas\nao sistema nervoso, muscular e osteoarticular, prevenindo ou reduzindo as múltiplas\nconsequências clínicas delas decorrentes. Possibilita melhorar o ajustamento dos doentes com\nincapacidades às realidades e reintegrá-los profissional e socialmente. Os meios físicos e os\nprocedimentos de reabilitação incluem várias técnicas, EXCETO:","options":{"A":"Hidroterapia.","B":"Musculoterapia.","C":"Termoterapia.","D":"Massoterapia."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-291481","number":"291481","sourceNumber":"291481","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher de 40 anos, relata queda da própria altura, após tropeçar na calçada, e cair para\nfrente com as mãos espalmadas, com hiperextensão do punho. No momento se queixa de dor em\nregião dorsal e radial do punho. Ao exame, presença de leve edema próximo ao processo estiloide\ndo rádio, sem deformidade evidente do punho. Refere dor a palpação do punho, pouco abaixo da\nprega palmar, na direção do eixo longo do polegar, e na tabaqueira anatômica. Dentre as\nalternativas abaixo, qual é a hipótese diagnóstica?","options":{"A":"Fratura de escafoide.","B":"Fratura de Colles.","C":"Fratura de Barton.","D":"Fratura de Smith."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183887","number":"183887","sourceNumber":"183887","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação aos pacientes politraumatizados, julgue o item a seguir. Em idosos, as\nfraturas de ossos longos são mais graves por causa da maior dificuldade de consolidação\ndecorrente da desmineralização óssea.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183897","number":"183897","sourceNumber":"183897","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação aos pacientes politraumatizados, julgue o item a seguir. O controle e a\nestabilização de fraturas expostas de ossos longos, tais como fêmur, tíbia e úmero, devem ser\nfeitos somente após a verificação da patência da via aérea e da respiração.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-177228","number":"177228","sourceNumber":"177228","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 15 anos de idade, do sexo masculino, realiza uma consulta com\nespecialista, por apresentar quadro de dores\nde repetição na face anterior da tíbia direita, próximo\nao joelho, além de dificuldade de se movimentar na prática de futebol. Ao exame físico, apresenta\nedema e dor à palpação. Ao sair da consulta, o pediatra recomendou repouso e restrição das\natividades físicas, sem a prescrição de qualquer medicamento. Considerando-se o mencionado\nquadro clínico e os conhecimentos médicos relativos a ele, é correto afirmar que o diagnóstico mais\nprovável para o caso é","options":{"A":"doença de Legg-Calvé-Perthes.","B":"artrite séptica.","C":"ruptura parcial do menisco lateral.","D":"cisto de Baker.","E":"doença de Osgood-Schlatter."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-157979","number":"157979","sourceNumber":"157979","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 6 anos de idade queixa-se de dor intensa recidivante difusa e nos\nmembros inferiores. Sabendo-se que as dores do\ncrescimento possuem critérios de inclusão e de\nexclusão, para afastar essa hipótese, a dor do paciente deveria ser:","options":{"A":"Crônica.","B":"Em ambos os membros inferiores.","C":"Articular.","D":"Não articular.","E":"Geralmente no fim do dia ou à noite."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-168460","number":"168460","sourceNumber":"168460","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma mulher com 75 anos de idade, previamente hígida e ativa, ao ser atendida em\numa Unidade Básica de Saúde, refere que há 2\ndias está com dor intensa na região coxo-femoral\ndireita, que irradia para a região medial da coxa e joelho, o que lhe causa grande dificuldade para\ndeambular. Quando questionada sobre queda, a paciente nega a ocorrência, assim como os\nfamiliares que a acompanham. Ela refere, ainda, tontura esporádica ao levantar-se da cama e nega\noutros sintomas, outras comorbidades ou uso contínuo de medicação. Tem joelhos valgos. Ao\nexame físico, apresenta pressão arterial = 150 x 100 mmHg e tanto a ausculta cardiorrespiratória\nquanto a restante do exame físico são normais. Os exames de imagem mostram uma fratura de\ncolo de fêmur estágio II da Classificação de Garden (fraturas sem desvio). Qual deve ser a conduta\nterapêutica adequada nesse caso?","options":{"A":"Redução aberta com realização de osteossíntese.","B":"Redução fechada com realização de osteossíntese.","C":"Artroplastia total do quadril devido à boa saúde prévia da paciente.","D":"Tratamento não operatório devido à boa evolução e consolidação da fratura."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-97747","number":"97747","sourceNumber":"97747","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um homem com 22 anos de idade, previamente saudável, deu entrada no\n\nPronto-Socorro, vítima de acidente de moto, com fratura fechada de colo de fêmur e pneumotórax.\nApós drenagem percutânea do tórax (dreno fechado)\ne fixação externa da fratura de colo de fêmur,\nencontra-se estável e será mantido na enfermaria para aguardar a correção cirúrgica da fratura do\ncolo do fêmur. Qual deve ser a seleção correta de antibioticoprofilaxia para esse paciente?","options":{"A":"Cefazolina.","B":"Cefuroxima.","C":"Gentamicina.","D":"Ciprofloxacina."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-321157","number":"321157","sourceNumber":"321157","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma paciente do sexo feminino, 27 anos, corredora recreacional, tem treinado para\nmeia maratona e queixa-se de dor na região\nplantar bilateral, que piora após as primeiras pisadas.\nAo exame físico, apresenta pontos de dor na palpação plantar próxima ao calcâneo, que piora com\ndorsiflexão do hálux. Considerando o caso clínico, é CORRETO afirmar que o diagnóstico provável\ndessa paciente é de:","options":{"A":"Fascite plantar.","B":"Fratura de estresse.","C":"Tendinopatia do calcâneo.","D":"Tendinopatia dos fibulares."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-304997","number":"304997","sourceNumber":"304997","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Considere que um paciente do sexo masculino, 41 anos de idade, advogado, procura\natendimento ambulatorial com dor em cotovelo esquerdo e formigamento em mãos. Refere que,\ndesde que começou a praticar golfe, três vezes por semana, passou a sentir dor no cotovelo\nassociada à parestesia do quarto e quinto dedos. Nesse caso, o diagnóstico provável e a\ncomplicação associada, são, respectivamente:","options":{"A":"Artrite de cotovelo e compressão de nervo mediano por síndrome do túnel cubital.","B":"Epicondilite medial e compressão de nervo ulnar por síndrome do túnel cubital.","C":"Epicondilite lateral e compressão de nervo ulnar por síndrome do túnel cubital.","D":"Bursite olecraniana e compressão de nervo radial por síndrome do túnel cubital."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-291647","number":"291647","sourceNumber":"291647","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No tratamento da neoplasia de mama, a abordagem axilar por vezes tem um importante\npapel no estadiamento e tratamento. Um dos\nimportantes elementos de atenção do cirurgião nessa\ncirurgia é a identificação do nervo torácico longo. Qual alteração clínico-anatômica está associado\nà\nlesão do nervo torácico longo?","options":{"A":"Escápula alada.","B":"Dificuldade respiratória por paralisia do diafragma.","C":"Síndrome de Claude Bernard Horner.","D":"Atrofia de peitoral devido paralisia de peitoral maior.","E":"Parestesia de face medial de braço."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-187996","number":"187996","sourceNumber":"187996","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Homem, 58 anos, obeso, com queixa lombociatalgia de intensidade leve a moderada\nhá 4 semanas Exame físico sem sinais de\ndéficit neurológico e com força muscular grau V nos\nmembros inferiores. Levando em consideração a principal hipótese diagnóstica qual é a conduta a\nser tomada?","options":{"A":"Perda de peso, fisioterapia, analgésicos e relaxantes musculares com reavaliação em 4\nsemanas.","B":"Solicitar ressonância magnética.","C":"Indicar cirurgia de fusão com aloenxerto ósseo e placa de titânio e parafusos.","D":"Indicar cirurgia de laminotomia.","E":"Indicar cirurgia de hemilaminectomia."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-187508","number":"187508","sourceNumber":"187508","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre o geno valgo na infância é correto afirmar que:","options":{"A":"O geno valgo é considerado patológico em qualquer idade.","B":"O valgo normal é obtido por volta dos 4 anos de idade.","C":"A persistência do geno valgo após os 2 anos de idade é considerada patológica.","D":"O valgo aumentado no joelho é sempre assintomático.","E":"Uma variação de até 15 graus de valgo é possível até os 8 anos de idade."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-174387","number":"174387","sourceNumber":"174387","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Escolar de seis anos, sexo masculino, é levado ao pediatra por estar ?mancando? há\ndois dias. Mãe relata quadro viral há uma semana e nega trauma direto. Exame físico: sinais vitais\nnormais. Boa mobilidade do joelho direito com rotação interna limitada por dor no quadril no mesmo\nlado. Exames laboratoriais: leucócitos normais, discreta elevação da VHS. Radiografias de perna e\nquadril direitos: normais. A hipótese diagnóstica é:","options":{"A":"Escorregamento epifisário femural proximal.","B":"Doença de Osgood-Schlatter.","C":"Displasia do desenvolvimento do quadril.","D":"Sinovite transitória.","E":"Doença de Leg-Calves-Pether."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-187495","number":"187495","sourceNumber":"187495","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual a indicação absoluta para o tratamento cirúrgico da fratura da clavícula?","options":{"A":"Fratura exposta.","B":"Encurtamento de 0,5 cm.","C":"Alteração neurológica.","D":"Epilepsia.","E":"Ombro flutuante."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-127169","number":"127169","sourceNumber":"127169","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na fratura da diáfise umeral, qual das artérias listadas abaixo pode ser lesada,\nindicando o reparo operatório do úmero?","options":{"A":"Artéria aorta.","B":"Artéria subclávia.","C":"Artéria braquial.","D":"Artéria radial.","E":"Artéria ulnar."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-102755","number":"102755","sourceNumber":"102755","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No exame osteoarticular da criança, existem achados que podem ser considerados\nfisiológicos em crianças pequenas. Em relação ao exame osteoarticular da criança, assinale a\nalternativa INCORRETA.","options":{"A":"Os pés planos flexíveis em ortostatismo desaparecem logo após o início da marcha.","B":"No sexo feminino, há sempre certo grau de valgismo.","C":"O Genu Varo postural geralmente corrige espontaneamente com a idade.","D":"A partir dos 12 anos, a criança começa a apresentar o realinhamento dos membros inferiores."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-111583","number":"111583","sourceNumber":"111583","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quando um paciente apresenta uma fratura com desvio e perfusão inadequada,\ndeve-se realizar a redução e o alinhamento da\nfratura. Isto é importante porque:Assinale a opção\nincorreta:","options":{"A":"Diminui a dor","B":"Pode melhorar a perfusão sanguínea","C":"Aumenta a possibilidade de tamponamento do foco de fratura","D":"Restabele o fluxo sanguíneo se a artéria estiver seccionada","E":"Diminui o edema e,consequentemente, a chance de ocorrer síndrome de compartimento"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-88872","number":"88872","sourceNumber":"88872","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Homem de 29 anos, vítima de acidente automobilístico sofreu fratura fechada de diáfise\nde fêmur direito. Internado com tração\nesquelética há 2 dias, começou a apresentar desconforto\nrespiratório, confusão mental, taquicardia, petéquias e febre. Gasometria revela PO2 de 55 mmHg,\n\nP.A . 110 x 70 mmHg. A hipótese diagnóstica provável é:","options":{"A":"Septicemia.","B":"Pneumonia aspirativa.","C":"Síndrome compartimental.","D":"Embolia gordurosa.","E":"TVP evoluindo com embolia pulmonar."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-59106","number":"59106","sourceNumber":"59106","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Pré-escoIar de quatro anos, sexo masculino, natural e procedente de Vitória (ES),\niniciou quadro de claudicação dolorosa, que\ndificulta a deambulação, embora consiga ficar em pé.\nDuas semanas antes do início desse quadro, apresentou três dias de sintomas sugestivos de\nresfriado, semelhante a outros quadros de resfriado anteriores. Nega viagens nos últimos 12\nmeses. No momento, apresenta-se: afebril; bom estado geral; consegue deambular, mas apresenta\ndor e limitação de movimentos do quadril direito. Radiografia de quadril em AP normal.\n\nUltrassonografia dos quadris evidencia discreto derrame articular. O hemograma evidencia\nleucometria normal, ausência de anemia e discreta elevação da Velocidade de\nHemossedimentação (VHS). A hipótese diagnóstica mais provável é:","options":{"A":"Artrite idiopática juvenil.","B":"Doença de Legg-Calvé-Perthes.","C":"Epifisiólise do quadril.","D":"Sinovite transitória.","E":"Artrite séptica."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-43941","number":"43941","sourceNumber":"43941","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente feminina, 43 anos, diagnóstico recente de hipotireoidismo ainda\ndescompensado, apresenta dor tipo neuropática em\nhálux e indicador e diminuição da força de\npinça. Ao exame físico, apresenta Manobra de Phalen positivo. Qual o diagnóstico?","options":{"A":"Contratura de Dupuytren.","B":"Síndrome do túnel do carpo.","C":"Tenossinovite De Quervain.","D":"Síndrome do impacto.","E":"Síndrome da compressão no nervo radial."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-354798","number":"354798","sourceNumber":"354798","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A procura por consulta na atenção primária à saúde de pacientes com queixas de\ntraumas em pés e tornozelo é algo\nrelativamente comum. Uma estratégia útil na condução destes\ncasos é a aplicação das regras de predição clínica de Ottawa para o tornozelo que","options":{"A":"definem a necessidade de imobilização total ou parcial de tornozelo.","B":"auxiliam na decisão de realizar radiografia para descartar fratura.","C":"avaliam a necessidade de realizar infiltração articular.","D":"estimam o tempo de afastamento para realização de atividades física ou atividade laboral."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-353791","number":"353791","sourceNumber":"353791","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um adolescente de 17 anos chega ao consultório queixando-se de dor intensa e\nprogressiva na região proximal da tíbia,\nacompanhada de inchaço local. O raio-X mostra uma lesão\nosteoblástica com limites imprecisos e reação periosteal do tipo \"raios de sol\". A biópsia confirma\no\ndiagnóstico de osteossarcoma. O tratamento mais adequado para este paciente é:","options":{"A":"Cirurgia seguida por radioterapia, sem necessidade de quimioterapia.","B":"Quimioterapia neoadjuvante, cirurgia para retirada do tumor e quimioterapia adjuvante, com\najuste de acordo com o nível de necrose tumoral na peça cirúrgica (critérios de Huvos).","C":"Curetagem da lesão e preenchimento com enxerto ósseo autólogo.","D":"Tratamento com agentes biológicos direcionados e cirurgia, sem quimioterapia ou cirúrgico, com\nressecção associada à adjuvância local (eletrocautério, álcool, nitrogênio líquido); apresenta alto\níndice de recidivas."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-334791","number":"334791","sourceNumber":"334791","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A rotura do ligamento cruzado anterior (LCA) do joelho:","options":{"A":"acomete principalmente indivíduos idosos sedentários.","B":"caracteriza-se pela estabilidade articular.","C":"a lesão é melhor evidenciada no exame de imagem de radiografia de joelho.","D":"na maioria das vezes é tratada cirurgicamente."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-321581","number":"321581","sourceNumber":"321581","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em um caso de osteomielite hematogênica ocorrendo no fêmur distal de uma criança\nde 3 anos, a infecção teria inicio mais\nprovável na","options":{"A":"fise","B":"epifise","C":"diáfise","D":"metáfise"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-316294","number":"316294","sourceNumber":"316294","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 29 anos de idade, vítima de acidente motociclístico, deu entrada com\nqueixa de dor e deformidade em perna esquerda. Ao exame: ferimento 2cm face anterior perna\nesquerda com sangramento local, dor e crepitação a palpação, baixa contaminação da ferida,\npequena lesão de partes moles, sem déficit neurovascular distal no membro acometido. Raio-X\ncom fratura diafisária de tíbia de traço multifragmentar (cominutiva). De acordo com Gustillo e\nAnderson, você classificaria como fratura exposta de tíbia grau:","options":{"A":"I","B":"II","C":"III a","D":"III b"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-295340","number":"295340","sourceNumber":"295340","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O diagnóstico clínico da luxação do quadril no recém-nascido é dado pelo teste de:","options":{"A":"Barlow.","B":"Ortolani.","C":"Hart.","D":"Shenton."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-317926","number":"317926","sourceNumber":"317926","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual o nervo mais lesado nas fraturas supracondilianas do úmero com desvio\npóstero-medial nas crianças?","options":{"A":"Nervo ulnar.","B":"Nervo radial.","C":"Nervo mediano.","D":"Nervo interósseo posterior."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-295341","number":"295341","sourceNumber":"295341","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 70 anos de idade, do sexo masculino, ativo com fratura do colo femoral\ndesviada (Garden 4). Nesse caso, a melhor opção de tratamento é:","options":{"A":"artroplastia total do quadril.","B":"tratamento conservador.","C":"osteossíntese (fixação) com parafusos.","D":"artroplastia parcial do quadril."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-317927","number":"317927","sourceNumber":"317927","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No exame físico do joelho, a presença do sinal da gaveta posterior positivo é sugestiva\nde lesão de qual estrutura do joelho?","options":{"A":"Ligamento cruzado anterior.","B":"Corno posterior do menisco medial.","C":"Corno anterior do menisco medial.","D":"Ligamento cruzado posterior."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-311904","number":"311904","sourceNumber":"311904","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual o tumor esquelético caracteriza-se por uma proliferação benigna da cartilagem\nhialina presente, geralmente em ossos longos e,\nfrequentemente, inicia-se na metáfise com\nextensão no inferior da diáfise?","options":{"A":"Osteossarcoma.","B":"Encondroma.","C":"Displasia fibrosa.","D":"Condrossarcoma."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-294279","number":"294279","sourceNumber":"294279","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher de 35 anos, exercendo a profissão de cozinheira, queixa-se de dor no punho\ndireito, de início há duas semanas. Ao exame físico osteoarticular, apresenta dor intensa à\npalpação no nível da apófise estiloide do rádio direito, e dor à manobra de adução forçada com a\nmão fechada. Considerando-se a principal hipótese diagnóstica para o caso, a manobra descrita\ndenomina-se:","options":{"A":"Finkelstein.","B":"Trendelenburg.","C":"Cozen.","D":"Yocum."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-295368","number":"295368","sourceNumber":"295368","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O tendão da cabeça longa do bíceps, embora anatomicamente não faça parte do\ntendão do manguito rotador, desempenha ação\nsemelhante, ao abaixar e comprimir a cabeça\numeral de encontro à glenoide. Sua inflamação pode ser detectada posicionando o cotovelo a 90\ngraus, junto ao tronco, com o antebraço pronado. Pede-se ao paciente para tentar fazer a\nsupinação contra a resistência. A manifestação de dor no sulco intertubercular, durante este teste,\nindica a presença de tendinite. A manobra acima descrita é denominada:","options":{"A":"Phalen.","B":"Yergason.","C":"Jobe.","D":"Yocum."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313219","number":"313219","sourceNumber":"313219","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma recém-nascida, com 15 dias de vida, apresentou manobra de Ortolani positiva à\ndireita e suspeita à esquerda no exame físico ao nascimento. Os pais foram orientados a marcarem\nconsulta na Unidade Básica de Saúde para continuarem a avaliação. O exame complementar mais\nadequado para confirmar o diagnóstico é:","options":{"A":"ressonância magnética","B":"ultrassonografia de quadril","C":"cintilografia óssea","D":"radiografia simples de quadril"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-308276","number":"308276","sourceNumber":"308276","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Osteomielite, uma infecção do osso, é causada mais comumente por bactérias\npiogênicas e microbactérias. Uma abordagem útil\npara avaliação e planejamento do tratamento\ncasos são classificados baseados em agentes causais, via de acesso dos agentes, duração da\ninfecção, localização anatômica e fatores locais ou sistêmicos do hospedeiro que se relacionam\ncom a patogênese e desfechos. Considerando a temática da osteomielite e sua importância na\nprática clínica em oncologia, resposta as questões abaixo. Sobre a patogênese da osteomielite\npodemos afirmar que:","options":{"A":"Microorganismos tem como porta de entrada a via hematogênica, infecções de contiguidade e\nferida penetrante.","B":"Trauma, isquemia e corpo estranho aumentam a suscetibilidade óssea a invasão microbiana\nexpondo sítios e seus tecidos.","C":"Fagocitose, na tentativa de conter o processo libera enzimas que podem lesar as estruturas\nósseas.","D":"Todas afirmativas são verdadeiras."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-308277","number":"308277","sourceNumber":"308277","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Osteomielite, uma infecção do osso, é causada mais comumente por bactérias\npiogênicas e microbactérias. Uma abordagem\nútil para avaliação e planejamento do tratamento\ncasos são classificados baseados em agentes causais, via de acesso dos agentes, duração da\ninfecção, localização anatômica e fatores locais ou sistêmicos do hospedeiro que se relacionam\ncom a patogênese e desfechos. Considerando a temática da osteomielite e sua importância na\nprática clínica em oncologia, resposta as questões abaixo. Osteomielite hematogênica é uma\nimportante causa com desfechos imprevisíveis e potencialmente greves. Neste contexto é correto\nafirmar que:","options":{"A":"A osteomielite hematogênica aguda geralmente envolve único osso, preferencialmente longo na\njuventude e nas diáfises na vida adulta.","B":"Osteomielite vertebral é o sitio hematogênico mais comum na vida adulta e cujo sintoma clinico\nmais comum é dor nas costas ou pescoço.","C":"Achados laboratoriais nas fases iniciais da osteomielite são pouco expressivos como leve\naumento de série branca, anemia e elevação de VHS e PCR. Culturas positivas de 20 a 50%.","D":"Todas afirmativas são verdadeiras."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-308278","number":"308278","sourceNumber":"308278","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Osteomielite, uma infecção do osso, é causada mais comumente por bactérias\npiogênicas e microbactérias. Uma abordagem útil\npara avaliação e planejamento do tratamento\ncasos são classificados baseados em agentes causais, via de acesso dos agentes, duração da\ninfecção, localização anatômica e fatores locais ou sistêmicos do hospedeiro que se relacionam\ncom a patogênese e desfechos. Considerando a temática da osteomielite e sua importância na\nprática clínica em oncologia, resposta as questões abaixo. Sobre o diagnóstico de osteomielite\nconsidere a melhor resposta:","options":{"A":"O diagnóstico precoce de doença aguda é fundamental para prevenir necrose óssea.","B":"Abordagem diagnóstica inicial pode ser com Rx simples que, embora não detecte doença\nprecoce, é prático e acessível.","C":"Amostra para estudo microbiológico do sitio suspeito deve ser sempre buscada antes do inicio\nde antibioticoterapia.","D":"Todas afirmativas são verdadeiras."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-311961","number":"311961","sourceNumber":"311961","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"\"Com o paciente em posição supina e a perna a ser examinada ao lado do examinador,\ndeve-se flexionar o quadril a 45º e o joelho a\n90º, empurrando a tíbia proximal no sentido\nanteroposterior e observar se ocorre deslocamento excessivo da tíbia posteriormente.\" De acordo\ncom a descrição, assinale a alternativa correta com relação ao nome do exame e qual estrutura do\njoelho está sendo avaliada.","options":{"A":"Teste da gaveta anterior/ ligamento cruzado anterior.","B":"Teste de Pivot/ menisco medial.","C":"Teste da gaveta posterior/ ligamento cruzado posterior.","D":"Teste da gaveta posterior/ ligamento cruzado anterior."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-257707","number":"257707","sourceNumber":"257707","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A epifisiólise proximal do fêmur constitui alteração da relação anatômica normal entre a\ncabeça e o colo femoral em pacientes com a\nlinha de crescimento aberta. O escorregamento\nacontece na camada hipertrófica da placa epifisária femoral proximal. Essa afecção é mais comum:","options":{"A":"Na raça branca.","B":"Em pacientes maiores de 16 anos de idade.","C":"No quadril direito dos meninos.","D":"Em pacientes obesos."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-258157","number":"258157","sourceNumber":"258157","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As afecções do ombro são comuns, e muitas vezes provocam grande incapacidade\nfuncional. A história clínica, por vezes, é\ninsuficiente para o diagnóstico das lesões do manguito\nrotador. Dessa forma, lança-se mão do exame físico, com a realização de testes especiais. Para o\nauxílio diagnóstico da síndrome do impacto do ombro, pode-se usar o teste de","options":{"A":"Phalen.","B":"Allen.","C":"Neer.","D":"Yergason."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-257708","number":"257708","sourceNumber":"257708","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Cisto de Baker ou cisto poplíteo é a formação cística na região posteromedial do joelho.\nCorresponde a um aumento de volume da bursa do músculo semimembranáceo. Essa condição\nclínica","options":{"A":"apresenta-se na maioria dos casos de forma assintomática.","B":"acomete pacientes com idade entre 15 e 25 anos.","C":"está relacionada comumente com doença extra-articular.","D":"apresenta incidência na população geral de 5%."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-258158","number":"258158","sourceNumber":"258158","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O pé torto congênito é a deformidade ortopédica congênita mais frequente. Há relatos\nque vêm desde os tempos remotos. Dentre as\nopções de tratamento conservador, o método de\nPonseti é correntemente utilizado, notadamente nas duas últimas décadas. Faz parte desse tipo de\ntratamento a tenotomia do","options":{"A":"fibular curto.","B":"Aquiles.","C":"extensor longo do hálux.","D":"tibial anterior."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-274757","number":"274757","sourceNumber":"274757","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Ao tratar fraturas, deve-se levar em consideração alguns fatores que vão influenciar no\nmetabolismo ósseo. Marque a alternativa que evidencia um fator estimulante para a neoformação\nóssea e a consequente consolidação da fratura:","options":{"A":"estímulo térmico, em que a aplicação de baixa temperatura no membro fraturado, reduz a\nvasodilatação local e a liberação de interleucinas e prostraglandinas, aumentando o estímulo de\nrecrutamento de osteoblastos pelos macrófagos.","B":"estímulo neurológico, em que a ruptura da estrutura óssea e irritação do periósteo, enviam um\nsinal, através dos propioceptores locais, para a medula óssea vermelha, estimulando a liberação de\nmacrófagos e, posteriormente, osteoblastos.","C":"estímulo químico em que o uso de inibidores da COX (ciclooxigenase) interrompe o sinal\ninflamatório, acelerando o recrutamento de macrófagos e osteoblastos.","D":"estímulo mecânico, em que a solicitação física, como movimentar ou aplicar carga no membro\nfraturado, gera alterações na pressão em proteínas das membranas celulares estimulando a\ndiferenciação de células mesenquimais em osteoblastos."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-281268","number":"281268","sourceNumber":"281268","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A doença de Legg-Calvé-Perthes é caracterizada pela necrose avascular da cabeça do\nfêmur. Ela acomete, em geral, crianças com idade entre:","options":{"A":"2 e 5 anos.","B":"4 e 9 anos.","C":"7 e 12 anos.","D":"10 e 15 anos."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-277431","number":"277431","sourceNumber":"277431","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual a localização clássica do tumor de células gigantes do osso:","options":{"A":"Diáfise","B":"Metáfise","C":"Epífise de ossos longos","D":"Córtex da metáfise"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-265914","number":"265914","sourceNumber":"265914","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A fratura-luxação de Monteggia caracteriza-se por:","options":{"A":"luxação da ulna associada a fratura da mesma.","B":"luxação da cabeça do rádio associada a fratura da ulna.","C":"luxação da cabeça do rádio associada a lesão nervo ulnar.","D":"luxação da olécrano ulnar associada a lesão nervosa adjacente."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-265917","number":"265917","sourceNumber":"265917","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Luxação é MELHOR definida como:","options":{"A":"Perda da congruência articular, caracterizada por edema, dor, deformidade e resistência\nelástica.","B":"Fusão da articulação que acontece em osteoartrose.","C":"Perda da solução de continuidade óssea, geralmente após traumas.","D":"Lesão ligamentar devido à perda momentânea da congruência articular."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-231939","number":"231939","sourceNumber":"231939","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente de 38 anos apresenta dor crônica na face posterior do antebraço direito,\ndiminuição da força de extensão dos dedos, mas sem alteração de sensibilidade. Sendo indicado\ntratamento cirúrgico, qual dos procedimentos a seguir seria o mais compatível com o quadro\napresentado?","options":{"A":"liberação do túnel do carpo","B":"descompressão do túnel do supinador","C":"descompressão do nervo ulnar no cotovelo","D":"neurólise total do plexo braquial","E":"liberação do nervo mediano na inserção do bíceps"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-232212","number":"232212","sourceNumber":"232212","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Fratura exposta é uma expressão que se refere a um amplo espectro de lesões, desde\nperfuração na pele até esmagamento do membro. O tratamento adequado das fraturas expostas\ncontinua sendo um desafio para os cirurgiões ortopedistas que lidam com trauma. Nas fraturas\nexpostas tipo Gustilo III, o esquema de antibiótico definido como de primeira escolha é:","options":{"A":"Cefalosporina de primeira geração.","B":"Cefalosporina de terceira geração.","C":"Cefalosporina de primeira geração e penicilina.","D":"Cefalosporina de primeira geração e aminoglicosídeo."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-234312","number":"234312","sourceNumber":"234312","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Displasia do desenvolvimento do quadril é uma expressão genérica que descreve um\nespectro de anormalidades anatômicas do quadril, que podem ser congênitas ou de\ndesenvolvimento após o nascimento. Ao exame físico, nota-se o encurtamento femoral do lado\nacometido:","options":{"A":"Pelo sinal de Galeazzi.","B":"Pela assimetria das pregas inguinais.","C":"Pelo teste de Ortolani.","D":"Pelo teste de Barlow."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-234313","number":"234313","sourceNumber":"234313","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A sinovite transitória de quadril caracteriza-se por quadro agudo de dor, afetando, aos\npoucos, um lado dos quadris da criança sadia. O tratamento dessa afecção é:","options":{"A":"Cirúrgico, por artrotomia.","B":"Por tração esquelética.","C":"Estritamente sintomático.","D":"Conservador, com injeção intra-articular de corticosteroide."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-231943","number":"231943","sourceNumber":"231943","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Que tipo de fibra de colágeno e que sal mineral estão presentes em maior quantidade\nno tecido ósseo?","options":{"A":"colágeno tipo l e carbonato de cálcio","B":"colágeno tipo I e hidroxiapatita de cálcio","C":"colágeno tipo II e carbonato de cálcio","D":"colágeno tipo II e hidroxiapatita de cálcio"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-247402","number":"247402","sourceNumber":"247402","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre as fraturas do fêmur, assinale a alternativa correta.","options":{"A":"Pacientes com fratura do colo femoral tem como característica, em inspeção, o encurtamento e\nrotação interna do membro fraturado.","B":"A evolução para osteonecrose da cabeça femoral é mais comum em fraturas do colo femoral do\nque em fratura transtrocantérica, mesmo com\ntratamento ideal.","C":"Na classificação da fratura de Garden de colo femoral no tipo 4 o padrão trabecular não se\nalinha com o do acetábulo, diferente do tipo 2 que assume uma orientação paralela.","D":"Nas fraturas transtrocantéricas, o iliopsoas desloca lateral e proximalmente, o trocanter menor."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-249489","number":"249489","sourceNumber":"249489","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente do sexo masculino, 14 anos, refere dor nas costas há 5 semanas tanto ao\njogar voleibol (pratica todos os dias por 3 horas) como em repouso, às vezes piorando em repouso.\nJá procurou atendimento e o médico disse ser ?dor do crescimento? e que as dores vão passar\ncom o tempo. Com bases nessas informações, qual a hipótese diagnóstica?","options":{"A":"Espondilólise.","B":"Doença de Sever.","C":"Tumor de vértebras.","D":"Artrite reumatoide juvenil."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-232302","number":"232302","sourceNumber":"232302","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em uma radiografia da perna, foram observadas lesões na metáfise e na epífise distais\nda tíbia, com achados compatíveis com\nosteomielite aguda. Considerando a localização da lesão, a\nidade do paciente é, mais provavelmente, de:","options":{"A":"um mês.","B":"dez anos.","C":"quarenta anos.","D":"oitenta anos."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-247487","number":"247487","sourceNumber":"247487","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No exame ortopédico de um lactente com 3 meses, não é esperado o encontro de:","options":{"A":"Assimetria das pregas glúteas e dos membros inferiores.","B":"Genu varo.","C":"Pé plano.","D":"Manobra de Barlow negativa bilateralmente."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-201677","number":"201677","sourceNumber":"201677","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente do sexo masculino, de 20 anos, foi atendido no\npronto-socorro com história de trauma em ombro direito há duas horas. Ao exame físico,\napresentava dor e sinal da dragona. Refere dois episódios semelhantes nos últimos dois anos. A\nconduta imediata adequada, nesse caso, é:","options":{"A":"Radiografia de ombro para descartar fratura e redução da luxação glenoumeral.","B":"Imobilização com tipoia e encaminhamento ao especialista de maneira eletiva.","C":"Ressonância magnética de ombro para descartar lesão da musculatura do manguito rotador.","D":"Encaminhamento ao bloco cirúrgico para realizar a redução aberta da luxação articular."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-201679","number":"201679","sourceNumber":"201679","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente do sexo feminino, de 13 anos, pré-menarca, com\ndiagnóstico de escoliose idiopática do adolescente. Nas radiografias, apresentava curva de 30\ngraus e Risser II. O tratamento mais adequado é:","options":{"A":"Observação.","B":"RPG.","C":"Colete.","D":"Cirurgia."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-216530","number":"216530","sourceNumber":"216530","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação à doença de Legg-Calvè-Perthes, assinale a afirmativa INCORRETA:","options":{"A":"Acomete mais meninos que meninas.","B":"A dor no quadril ou joelho é o sintoma predominante.","C":"Apresenta marcha com padrão de Trendelenburg.","D":"É prevalente entre 03 a 09 anos."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-201722","number":"201722","sourceNumber":"201722","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O chamado sinal de HONDA está relacionado à fratura:","options":{"A":"Da escápula.","B":"Do fêmur.","C":"Da primeira costela.","D":"Do sacro."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-173557","number":"173557","sourceNumber":"173557","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente idoso, com história de queda da própria altura, apresenta, ao exame físico,\nmembro inferior esquerdo em rotação externa e encurtamento. Qual é a hipótese diagnóstica\ninicial?","options":{"A":"Fratura do colo do fêmur esquerdo.","B":"Fratura transtrocanteriana do fêmur esquerdo.","C":"Luxação posterior do quadril esquerdo.","D":"Luxação anterior do quadril esquerdo."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-185183","number":"185183","sourceNumber":"185183","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação à inervação sensitiva da mão, a sensibilidade do dedo anular é dada\npelo(s) nervo(s)","options":{"A":"mediano","B":"ulnar","C":"radial, mediano e ulnar","D":"radial e ulnar"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-185191","number":"185191","sourceNumber":"185191","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre embriogênese musculoesquelética, verifica-se que os tecidos ósseo e\ncartilaginoso, são formados pela placa","options":{"A":"medial do mesoderma.","B":"lateral do ectoderma.","C":"lateral do mesoderma.","D":"medial do ectoderma."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-175417","number":"175417","sourceNumber":"175417","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um neonato apresentando torcicolo congênito pode ter associação de outras\ndeformidades com a alteração da coluna\ncervical. Além dessa associação, deve-se pesquisar:","options":{"A":"rim único","B":"artrogripose","C":"cardiopatia congênita","D":"osteogênese imperfeita","E":"displasia congênita do quadril"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-174523","number":"174523","sourceNumber":"174523","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O diagnóstico precoce de lesões neurológicas secundárias à fratura-luxação é\nessencial para a recuperação funcional do membro. Assinale a alternativa que contempla a\nassociação CORRETA.","options":{"A":"Nervo Radial ? Extensão do Polegar ? Luxação Anterior do Ombro.","B":"Nervo Ciático ? Extensão Plantar ? Luxação Anterior de Quadril.","C":"Nervo Femoral ? Extensão do Joelho ? Fratura de Ramos Púbicos.","D":"Nervo Mediano Distal ? Contração com Oposição Tenar ? Luxação de Punho."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-157320","number":"157320","sourceNumber":"157320","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 7 anos inicia quadro insidioso com dificuldade para deambular há 3 meses,\nclaudicação na marcha e enrijecimento do quadril à esquerda com dor discreta em região anterior\nda coxa. Qual a principal hipótese diagnóstica?","options":{"A":"Doença de Legg-Calvé-Perthes.","B":"Artrite juvenil idiopática.","C":"Fratura de fêmur.","D":"Artrite séptica.","E":"Epifisite femoral aguda."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-160499","number":"160499","sourceNumber":"160499","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Lionel Messi, jogador de futebol argentino, não jogou defendendo a sua seleção pelas\neliminatórias para a Copa do Mundo, em outubro passado, devido a fortes dores na virilha, que\npioravam aos esforços. Feito diagnóstico clínico radiológico de osteíte púbica ou pubalgia, foi\ntratado e, após quase um mês, voltou às atividades. Um dos achados na imagem de ressonância\nmagnética é a tendinose do reto abdominal e do:","options":{"A":"Grácil.","B":"Adutor longo.","C":"Adutor curto.","D":"Adutor magno."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150206","number":"150206","sourceNumber":"150206","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No exame físico do recém-nascido para avaliação de displasia de desenvolvimento do\nquadril (DDQ), a manobra utilizada e sua respectiva função são:","options":{"A":"Manobra de Barlow - redução do quadril luxado.","B":"Manobra de Ortolani - redução do quadril luxado.","C":"Manobra de Hart - luxação do quadril reduzido.","D":"Manobra de Nelaton - luxação do quadril reduzido."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150232","number":"150232","sourceNumber":"150232","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A doença de Scheuermann ou dorso curvo juvenil caracteriza-se:","options":{"A":"Pelo aumento da cifose torácica, além do valor de 50°.","B":"Pela diminuição da cifose torácica, abaixo do valor de 20°.","C":"Pela presença de escoliose associada com malformações vertebrais.","D":"Pela presença de escoliose associada com doenças neuromusculares."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-157281","number":"157281","sourceNumber":"157281","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente vítima de agressão com trauma contuso em braço direito. Ao exame físico\napresenta \"mão caída\". Radiografia evidenciando fratura de úmero. Qual é o provável nervo\nlesado?","options":{"A":"Axilar.","B":"Radial.","C":"Ulnar.","D":"Mediano.","E":"Peitoral."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150274","number":"150274","sourceNumber":"150274","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A tendinite de Quervain é um reumatismo de partes moles, comum em mulheres na\nidade de 30 a 50 anos, caracterizada pelo\nacometimento dos tendões abdutor longo e extensor\ncurto do polegar. Nessa tendinite, o desvio forçado da mão fechada para o lado ulnar, utilizado para\nreproduzir a dor no processo estiloide do rádio, é denominado de teste de:","options":{"A":"Yergason.","B":"Thompson.","C":"Jobe.","D":"Finkelstein."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-156440","number":"156440","sourceNumber":"156440","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher, 50 anos, sofreu trauma no pé em inversão, apresentando edema e dor na base\n5º metatarsiano. O radiograma mostrou uma fratura\nem avulsão neste nível. Qual o tendão que\nocasionou esta fratura?","options":{"A":"Fibular superficial.","B":"Tibial posterior.","C":"Tibial anterior.","D":"Fibular curto."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150790","number":"150790","sourceNumber":"150790","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Leia o caso clínico a seguir: criança de dez anos apresenta dor em tornozelo esquerdo\nassociado à febre há seis dias. Apresenta dor importante à palpação de tíbia distal, com calor\nlocal,\nedema discreto de tornozelo esquerdo. VHS = 50mmHg, PCR = 26. Nesse caso, qual é a hipótese\ndiagnóstica?","options":{"A":"Osteomielite.","B":"Artrite reativa.","C":"Artrite idiopática juvenil.","D":"Febre reumática."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150765","number":"150765","sourceNumber":"150765","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mãe traz o filho de cinco anos por claudicação há 20 dias. Nega febre, edema ou dor,\nmas percebeu que o menino está andando diferente. Limitação discreta à abdução e rotação\nexterna do quadril esquerdo.\n\nNesse caso, qual é a hipótese diagnóstica?","options":{"A":"Epifisiólise.","B":"Legg-Perthes.","C":"Sinovite transitória do quadril.","D":"Osteossarcoma."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-140616","number":"140616","sourceNumber":"140616","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"João Pedro, após um forte chute na bola, durante uma partida de futebol, sentiu dores\nna coxa direita. Não conseguiu deambular na\nsequência. Procurou assistência médica, que\ndiagnosticou uma lesão muscular no quadríceps, tratada com repouso, gelo e analgesia. As lesões\nmusculares são mais comuns em músculos","options":{"A":"biarticulares e naqueles em que predominam fibras tipo II.","B":"monoarticulares e naqueles em que predominam fibras tipo I.","C":"monoarticulares e naqueles em que predominam fibras tipo II.","D":"biarticulares e naqueles em que predominam fibras tipo I."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-140618","number":"140618","sourceNumber":"140618","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"João Pedro, após um forte chute na bola, durante uma partida de futebol, sentiu dores\nna coxa direita. Não conseguiu deambular na\nsequência. Procurou assistência médica, que\ndiagnosticou uma lesão muscular no quadríceps, tratada com repouso, gelo e analgesia. A ruptura\ndo tendão do quadríceps pode estar associada a condições sistêmicas como:","options":{"A":"diabetes, hiperparatireoidismo e hipocalciúria.","B":"uremia, diabetes e hipocalciúria.","C":"uremia, diabetes e hiperparatireoidismo.","D":"uremia, hiperparatireoidismo, hipocalciúria."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-127640","number":"127640","sourceNumber":"127640","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O ligamento cruzado anterior é irrigado, pricipalmente, pela artéria:","options":{"A":"genicular média.","B":"genicular lateral.","C":"genicular inferior.","D":"genicular superior."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-129830","number":"129830","sourceNumber":"129830","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quais são os cromossomos em que o sarcoma de Ewing e os tumores\nneuroectodérmicos primitivos (PNET) apresentam a mesma translocação?","options":{"A":"Cromossomo 11 e 22.","B":"Cromossomo 17 e 22.","C":"Cromossomo 15 e 22.","D":"Cromossomo 18 e 22."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-138207","number":"138207","sourceNumber":"138207","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A epifisiólise proximal do fêmur caracteriza-se por","options":{"A":"ser mais comum entre os quatro e oito anos de idade.","B":"necessitar de punção articular para diagnóstico.","C":"ser mais frequente em mulheres com osteoporose.","D":"apresentar dor e limitação no quadril com irradiação da dor pela coxa e pelo joelho."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-136905","number":"136905","sourceNumber":"136905","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O uso inadequado e contínuo de muletas pode lesar o nervo axilar, comprometendo\ninclusive a função motora dos membros\nsuperiores. Excluindo-se a lesão iatrogênica, que pode\nocorrer em procedimentos ortopédicos no ombro, a lesão do nervo axilar não é comum nos\nesportes e existem duas principais causas em atletas: lesão por trauma direto e a síndrome do\nespaço quadrangular, por onde o nervo axilar atravessa. A estrutura citada que faz parte dos limites\ndesse espaço é:","options":{"A":"Músculo deltoide.","B":"Músculo peitoral maior.","C":"Tendão da cabeça longa do bíceps.","D":"Músculo redondo menor."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-136917","number":"136917","sourceNumber":"136917","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Define-se paralisia obstétrica como sendo uma lesão do plexo braquial ao nascimento.\nA lesão é provocada pelo estiramento dos\ntroncos nervosos ou avulsão radicular. A prevalência é\nvariável na literatura chegando a 4,6 casos por mil nascidos vivos. A taxa de recuperação\nneurológica espontânea pode chegar a 90% dos casos. Qual a classificação mais usada nesta\npatologia que é muito valiosa na prática clínica e que proporciona uma visão geral do prognóstico e\ntratamento?","options":{"A":"Erb-Duchene.","B":"Narakas.","C":"Klumpke.","D":"Sever-Lepiscopo."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-136945","number":"136945","sourceNumber":"136945","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A Síndrome do Túnel do Carpo é uma condição de compressão do nervo mediano ao\natravessar o punho, que causa um conjunto de sinais e sintomas, que incluem, dentre outros, dor\nnoturna e parestesia na mão. É a neuropatia compressiva mais comum e mais estudada do ser\nhumano. Não está relacionada dentre os fatores de risco dessa patologia:","options":{"A":"Gravidez.","B":"Hipertireoidismo.","C":"Tabagismo.","D":"Flexão extrema e repetitiva do punho no trabalho."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-129919","number":"129919","sourceNumber":"129919","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na avaliação de um paciente com quadro clínico de lombalgia e/ou lombociatalgia, a\nmanobra de Lasegue é geralmente considerada positiva quando a dor se irradia para o trajeto do\ndermátomo das raízes","options":{"A":"L2 e L3.","B":"L3 e L4.","C":"L4 e L5.","D":"L5 e S1."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-129877","number":"129877","sourceNumber":"129877","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher de 32 anos, com 35 dias de pós-parto, queixa-se de dor na região do processo\nestiloide radial direito e fraqueza à preensão com o polegar e o indicador da mão direita. Ao exame\nfísico, observam-se dor e tumefação na região da tabaqueira anatômica e manobra de Finkelstein\npositiva. Qual é a principal hipótese diagnóstica para essa paciente?","options":{"A":"Síndrome De Quervain.","B":"Contratura de Dupuytren.","C":"Síndrome do canal de Guyon.","D":"Dedo em gatilho."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-109304","number":"109304","sourceNumber":"109304","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Os pacientes com síndrome de Morquio apresentam inteligência normal, acentuada\nfrouxidão ligamentar e displasia progressiva do quadril. Qual tipo de mucopolissacaridose\ncaracteriza essa síndrome e qual é o seu defeito enzimático principal?","options":{"A":"Mucopolissacaridose tipo III e sulfato de Heparan.","B":"Mucopolissacaridose tipo IV e sulfato de Ceratan.","C":"Mucopolissacaridose tipo II e sulfato de Heparan.","D":"Mucopolissacaridose tipo I e sulfato de Ceratan."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-109311","number":"109311","sourceNumber":"109311","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quais músculos do antebraço são mais gravemente acometidos na síndrome de\nVolkmann decorrente de uma fratura de antebraço?","options":{"A":"Flexor radial do carpo e flexor ulnar do carpo.","B":"Flexor superficial dos dedos e pronador redondo.","C":"Flexor profundo dos dedos e flexor longo do polegar.","D":"Flexor radial do carpo e flexor longo do polegar."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-111430","number":"111430","sourceNumber":"111430","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Izaura, 85 anos, teve queda da própria altura há uma hora. Ao ser atendida pelo SAMU,\nqueixou-se de intensa dor no quadril esquerdo, com grande limitação funcional do membro inferior\nesquerdo. Como comorbidades, relatou Diabetes mellitus e hipertensão arterial sistêmica. Ao\nexame ortopédico, demonstrou discreta rotação externa do membro inferior esquerdo e muita dor\ndo quadril à movimentação passiva. RX da bacia demonstrou acentuada osteoporose e fratura do\ncolo do fêmur esquerdo, com acentuado desvio. O tratamento indicado, neste caso, é:","options":{"A":"Tração cutânea e repouso no leito por 90 dias.","B":"Osteossíntese do colo do fêmur com placa-parafuso.","C":"Osteossíntese com haste intramedular e parafuso no colo femoral.","D":"Artroplastia do quadril.","E":"Desarticulação do quadril."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-103719","number":"103719","sourceNumber":"103719","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em RN de 5 dias, portador de Sindactilia em dedos de mão esquerda, quanto à\npatologia descrita, não é correto afirmar que:","options":{"A":"Está associada à síndrome de Poland e Apert.","B":"O sexo masculino é o mais afetado.","C":"Terceiro e quarto dedos são mais acometidos.","D":"Deve ser indicada a cirurgia antes dos seis meses."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-101221","number":"101221","sourceNumber":"101221","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É um tendão que, por apresentar uma zona hipovascularizada na sua inserção no\ntubérculo maior do úmero, possui maior predisposição para desenvolver a síndrome do impacto.\nTrata-se do tendão:","options":{"A":"supraespinhal.","B":"redondo menor.","C":"infraespinhal.","D":"subescapular."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-111418","number":"111418","sourceNumber":"111418","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre a dor articular associada com a Síndorme da Hipermobilidade Articular, que\nassertiva é correta:","options":{"A":"A dor predomina no período noturno, por vezes, acordando a criança.","B":"A dor é pouco comum e, se ocorrer, dura de minutos a poucas horas.","C":"Somente ocorre em membros inferiores.","D":"É comum a dor persistir por mais de 3 meses.","E":"Provas de função reumática se alteram nos momentos de dor."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-110179","number":"110179","sourceNumber":"110179","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Para um paciente homem de 30 anos, com diagnóstico clínico radiológico de hérnia\ndiscal C5-C6, no exame físico, espera-se encontrar alteração:","options":{"A":"No reflexo tricipital.","B":"Sensitiva na face lateral do braço.","C":"Da força do músculo extensor radial curto do carpo.","D":"Sensitiva na face medial do braço."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-110183","number":"110183","sourceNumber":"110183","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A fratura atipíca do fêmur representa um novo padrão de lesão em pacientes com\ndoença osteoporótica em uso prolongado de\nbifosfonatos. Nos achados radiográficos destes\npacientes, a configuração esperada da fratura é:","options":{"A":"Cominuida.","B":"Espiral ou oblíqua longa.","C":"Segmentar com asa de borboleta.","D":"Transversa ou oblíqua curta."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-79570","number":"79570","sourceNumber":"79570","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um pré-escolar de 4 anos, sexo masculino, natural e procedente de Vitória (ES), iniciou\nquadro de claudicação dolorosa, que dificulta a deambulação, embora consiga ficar em pé. Duas\nsemanas antes do início desse quadro, apresentou 3 dias de sintomas sugestivos de resfriado,\nsemelhante a outros quadros de resfriado anteriores. Nega viagens nos últimos 12 meses. No\nmomento, apresenta-se afebril, em bom estado geral, consegue deambular, mas apresenta dor e\nlimitação de movimentos do quadril direito. A radiografia de quadril em anteroposterior é normal, e\na\nultrassonografia dos quadris evidencia discreto derrame articular. O hemograma evidencia\nleucometria normal e ausência de anemia, bem como discreta elevação da velocidade de\nhemossedimentação (VHS). A hipótese diagnóstica mais provável é:","options":{"A":"Artrite idiopática juvenil","B":"Doença de Legg-Calvé-Perthes","C":"Epifisiólise do quadril","D":"Sinovite transitória","E":"Artrite séptica"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-78083","number":"78083","sourceNumber":"78083","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de seis anos, do sexo masculino, com história clínica de claudicação e dor na\nface interna da coxa e joelho direito, além de claudicação à custa do mesmo membro. No exame\nclínico do quadril direito, apresenta abdução de 25 graus e rotação interna de 10 graus. O\ndiagnóstico mais provável deste paciente é:","options":{"A":"osteomielite aguda.","B":"artrite reumatoide.","C":"doença de Legg-Calvé-Perthes.","D":"sinovite transitória do quadril."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-86341","number":"86341","sourceNumber":"86341","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança de 04 anos é levada ao pronto-socorro com relato da mãe de que tentou\nsegurá-la pela mão direita quando ela correu\npara a rua em direção a uma bola com a qual estavam\nbrincando na calçada de casa. Desde então a criança está com dor intensa e restrição do\nmovimento no membro superior direito. A lesão decorrente desse tipo de trauma é:","options":{"A":"luxação de punho.","B":"fratura de cotovelo.","C":"pronação dolorosa do cotovelo.","D":"luxação do ombro."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-78093","number":"78093","sourceNumber":"78093","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 12 anos, com escoliose idiopática do adolescente, com radiografias\nmostrando curva torácica à D, com ângulo de Cobb de\n30 graus. Apresenta grande potencial de\ncrescimento, com sinal de Risser grau 1. O tratamento mais indicado é:","options":{"A":"tratamento conservador com acompanhamento semestral para observação do crescimento.","B":"tratamento conservador com fisioterapia.","C":"tratamento conservador com uso de colete tipo Milwaukee.","D":"tratamento cirúrgico com artrodese posterior."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-89977","number":"89977","sourceNumber":"89977","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É causa de osteonecrose isquêmica, exceto:","options":{"A":"Abuso de álcool.","B":"Colagenoses.","C":"Fluorose.","D":"Hemoglobinopatia.","E":"Pancreatite."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-89987","number":"89987","sourceNumber":"89987","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A respeito da Síndrome do Túnel do Carpo, podemos afirmar:","options":{"A":"Envolve o nervo mediano do punho.","B":"Os sintomas tipicamente agravam-se em atividades associadas à extensão contínua do punho.","C":"O sinal de Tinel é testado quando da flexão forçada do punho.","D":"O sinal de Phalen é testado percutindo-se o nervo mediano no punho.","E":"A musculatura hipotenar é a mais afetada."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-90025","number":"90025","sourceNumber":"90025","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança com 9 meses de idade apresenta dificuldades para trocar fraldas por limitação\nda abdução dos membros inferiores. Mãe procurou\nortopedista para avaliação. Ao exame físico,\napresenta manobras de Ortolani e Barlow negativas e pistonagem positiva. O diagnóstico mais\nprovável é:","options":{"A":"Displasia do desenvolvimento do quadril.","B":"Sinovite transitória do quadril.","C":"Doença de Perthes.","D":"Artrite séptica.","E":"Fratura do fêmur proximal sem desvio."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-89960","number":"89960","sourceNumber":"89960","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual é o teste representado na Figura 1: (VER IMAGEM)","options":{"A":"Lasègue.","B":"Adams.","C":"Lackman.","D":"Pivô Shift.","E":"Spurling."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/89960.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-92971","number":"92971","sourceNumber":"92971","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em um paciente com trauma mandibular que evidenciou fratura parassinfisária\nesquerda é necessário suspeitar também de\nfratura associada na região de:","options":{"A":"parassínfise direita.","B":"côndilo esquerdo.","C":"coronoide esquerdo.","D":"côndilo direito."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-85376","number":"85376","sourceNumber":"85376","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"João Pedro, 17 anos, estava jogando futebol e teve um trauma na região distal da coxa\ndireita, evoluindo com dor, mas sem prejuízo da marcha. Após uma semana, queixou-se de\naumento de volume da coxa e dor que foi piorando progressivamente, sem sinais de aumento de\ntemperatura local. Houve discreta melhora dos sintomas com a utilização de AINEs, mas não houve\ndiminuição do volume. A amplitude de movimento do quadril e do joelho estava normal. O exame\nde radiografia mostrou a presença de uma reação periosteal e neoformação óssea com\nadensamento do osso do canal medular e cortical. Com base no caso clínico, as principais\nhipóteses diagnósticas são:","options":{"A":"Osteossarcoma, condrossarcoma e osteoma osteoide.","B":"Tumor de Ewing, condroblastoma e tumor de células gigantes.","C":"Osteossarcoma, osteomielite e tumor de Ewing.","D":"Condrossarcoma, tumor de Ewing e osteoma osteoide."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-85367","number":"85367","sourceNumber":"85367","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O diagnóstico diferencial entre a artrite séptica (tratamento cirúrgico) e a sinovite\ntransitória do quadril (tratamento\nconservador) não é fácil de ser realizado. Muitas vezes, utiliza-se\numa propedêutica armada de exames que demanda maior custo e requer melhor infraestrutura da\ninstituição de saúde. Perante isso, torna-se evidente a necessidade de uma análise multifatorial dos\ndados clínicos e laboratoriais envolvidos para que se possam racionalizar exames visando a correta\nabordagem e evitando a indicação de procedimentos desnecessários, como a ressonância\nmagnética, ou mais invasivos, como a artrocentese e a drenagem cirúrgica. Na artrite séptica do\nquadril, qual das alternativas abaixo NÃO é considerada como um dos preditores diagnósticos\ndescritos por KOCHER?","options":{"A":"Dor no quadril, a ponto de não suportar o próprio peso.","B":"VHS > 40 mm/h.","C":"Leucocitose superior a 12.000 céls/ml.","D":"Rubor periarticular."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-85319","number":"85319","sourceNumber":"85319","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Cássio, 20 anos, jogador de vôlei, teve um trauma na mão direita e evoluiu com dor\nintensa à palpação e mobilização da articulação interfalângica distal do dedo anular, edema\nmoderado e limitação funcional. Feito diagnóstico clinicorradiológico de dedo em martelo, foi\nindicada cirurgia, devido ao grau de desvio com flexão > 30°. Essa flexão da articulação em\nquestão deve-se à lesão:","options":{"A":"do ligamento triangular.","B":"do tendão extensor da zona I.","C":"do ligamento retinacular de Landsmeer.","D":"da cápsula articular."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-78079","number":"78079","sourceNumber":"78079","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma criança pré-escolar de quatro anos saiu correndo de forma inadvertida para\natravessar uma rua sozinha. Sua mãe gritou\nalto e parou-a rapidamente pelo braço. A criança\ncomeçou a chorar e desde então, permanece com o braço imóvel ao lado do corpo, com o cotovelo\ndobrado. O diagnóstico mais provável é:","options":{"A":"sinovite transitória.","B":"pronação dolorosa.","C":"fratura em \"galho verde\".","D":"osteocondrite umeral."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-61253","number":"61253","sourceNumber":"61253","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As fraturas do escafoide com pior prognóstico em relação à consolidação e ao\ndesenvolvimento de complicações são as que ocorrem no:","options":{"A":"terço distal e as que apresentam traço oblíquo horizontal.","B":"terço proximal e as que apresentam traço\ntransverso.","C":"terço distal e as que apresentam traço oblíquo vertical.","D":"terço distal e as que apresentam traço transverso.","E":"terço proximal e as que apresentam traço oblíquo vertical."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-62724","number":"62724","sourceNumber":"62724","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente com 70 anos, do sexo feminino, menopausa há 20 anos, não fez reposição\nhormonal e refere mãe com antecedente de\nfratura do colo do fêmur. É tabagista há 50 anos (20\ncigarros/dia), sedentária, com cifose dorsal aumentada, história de fratura do punho direito após\nqueda de própria altura há 15 anos e tratada com gesso, tem doença de Parkinson, sendo\ndeambuladora domiciliar. Refere que há 12 horas sofreu queda no banheiro de sua casa, sentada,\ncom trauma no quadril esquerdo, com dor e limitação, posição de rotação externa e encurtamento\ndo membro inferior esquerdo, com desvio rotacional e impossibilidade de deambulação. Veio de\nambulância do interior com imobilização provisória e dois exames feitos em sua cidade. Realizada\nhoje uma radiografia da bacia em anteroposterior, que evidencia fratura do colo do fêmur no quadril\nesquerdo, com desvio dos fragmentos e desmineralização óssea difusa e uma densitometria óssea\nde seis meses atrás com T-score na coluna lombar de - 1,8 e no colo do fêmur direito de -1,5. No\ncaso dessa paciente,","options":{"A":"a fratura prévia do punho direito não representa risco aumentado para outras fraturas, como a do\ncolo femoral.","B":"o tratamento não cirúrgico com tração e imobilização é preferível ao tratamento cirúrgico devido\nà sua faixa etária.","C":"o tratamento cirúrgico com redução aberta e a fixação interna com parafusos canulados são\npreferíveis à artroplastia do quadril.","D":"o prognóstico de morrer no primeiro ano após a fratura do fêmur proximal é de 25% e de\napresentar alguma difilcudade em suas atividades de vida diárias é de 80%."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-61257","number":"61257","sourceNumber":"61257","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No tratamento de fraturas transtrocanterianas do fêmur, cominutas e decorrentes de\ntraumas de grande energia, além das radiografias nas incidências frente e perfil, deverá(ão) ser\nrealizada(s):","options":{"A":"radiografias com abdução dos quadris.","B":"radiografias com tração e rotação interna.","C":"radiografias com adução dos quadris.","D":"ressonância magnética.","E":"ultrassonografia."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-61260","number":"61260","sourceNumber":"61260","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quais os ligamentos laterais do tornozelo (complexo ligamentar lateral) são,\nrespectivamente, o menos resistente e o mais resistente?","options":{"A":"fibulocalcâneo e fibulotalar anterior.","B":"fibulotalar posterior e fibulotalar anterior.","C":"fibulocalcâneo e fibulotalar posterior.","D":"fibulotalar anterior e fibulolatar posterior.","E":"fibulolatar posterior e fibulocalcâneo."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-61264","number":"61264","sourceNumber":"61264","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na fisiopatologia da artrite séptica, quais articulações apresentam metáfise\nintracapsular que permite a penetração da bactéria na articulação?","options":{"A":"quadril, tornozelo e cotovelo.","B":"ombro, tornozelo e dedos.","C":"joelho, quadril e cotovelo.","D":"punho, cotovelo e tornozelo.","E":"quadril, joelho e tornozelo."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-63239","number":"63239","sourceNumber":"63239","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma maratonista após um período prolongado de treinamento notou dor ao nível do\nantepé direito, progressiva, que piorava durante o treino matinal e melhorava com o repouso. Qual\na suspeita clínica mais provável, e qual(is) o(s) métodos(s) diagnóstico(s) a serem solicitado(s)?","options":{"A":"Artopatia inflamatória; radiografia e/ou Ressonância Magnética.","B":"Fratura de estresse; Radiografia e/ou Ressonância Magnética.","C":"Fratura de estresse; Radiografia e/ou Tomografia Computadorizada.","D":"Osteomielite; Radiografia e/ou Ultra-sonografia.","E":"Osteomielite; Radiografia e/ou Tomografia Computadorizada."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-64601","number":"64601","sourceNumber":"64601","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente encontrado após tentativa de suicídio por enforcamento com o corpo em\nsuspensão completa, em ponto fixo por meio de\num laço que constringe o pescoço. Paciente\napresentava congestão crânio-facial, sufusões hemorrágicas nas conjuntivas, máscara equimótica\ne protrusão da língua. Qual é a fratura típica do enforcado?","options":{"A":"Fratura do Atlas (C1) ou Fratura de Jefferson.","B":"Subluxação por rotação em C1.","C":"Fratura dos elementos posteriores do Áxis (C2).","D":"Fratura e luxação de C3.","E":"Fratura da junção toraco-lombar (Fratura de chance)."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-64586","number":"64586","sourceNumber":"64586","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A lombociatalgia que acomete a raiz de L5 apresenta o seguinte comprometimento\nmotor e de reflexo:","options":{"A":"Músculos fibulares; reflexo aquíleo.","B":"Músculo tibial anterior; reflexo patelar.","C":"Músculo extensor longo hálux; sem reflexo.","D":"Músculo tibial posterior; sem reflexo.","E":"Músculo extensor longo; reflexo patelar."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-53599","number":"53599","sourceNumber":"53599","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quando uma paciente vítima de colisão de veículo apresenta o membro inferior\nencurtado, quadril em flexão, adução e rotação interna, devemos SUSPEITAR de:","options":{"A":"luxação anterior do quadril.","B":"luxação posterior do quadril.","C":"fratura da bacia.","D":"fratura do colo do fêmur.","E":"fratura de patela."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-48994","number":"48994","sourceNumber":"48994","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 20 anos, mão direita dominante, sofreu corte com vidro em região\npalmar do punho direito, há cerca de 2 horas. Ao exame, apresenta lesão de tendões flexores do\nterceiro e quarto dedos e do nervo mediano. Qual a melhor conduta?","options":{"A":"Tenorrafia dos flexores e neurorrafia do nervo mediano.","B":"Neurorrafia do nervo mediano e colocação de rod de silicone no terceiro e quarto dedos.","C":"Sutura em bloco para, em um segundo tempo, realizar enxerto de tendões e nervos.","D":"Limpeza da ferida e surtura da pele.","E":"Limpeza da ferida, sutura da pele e colocação de órtese para evitar rigidez da articulação até\nrealização de enxertos."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35831","number":"35831","sourceNumber":"35831","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 22 anos, atleta, operado de fratura de diáfise de fêmur há dois dias,\napresenta dispneia intensa, confusão mental, petéquias conjuntivais. A causa mais provável do\nquadro seria:","options":{"A":"Infarto agudo do miocárdio.","B":"Broncopneumonia.","C":"Embolia gordurosa.","D":"Embolia pulmonar.","E":"Traumatismo torácico com Derrame Pleural."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35800","number":"35800","sourceNumber":"35800","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Os ossos da fileira proximal do punho são:","options":{"A":"Escafoide, semilunar, captato e pisiforme.","B":"Hamato, semilunar, piramidal e pisiforme.","C":"Trapezoide, piramidal, escafoide e pisiforme.","D":"Trapézio, escafoide, semilunar e piramidal.","E":"Nehuma das opções."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35808","number":"35808","sourceNumber":"35808","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A localização óssea mais frequente da osteomielite aguda em ossos longos:","options":{"A":"R. metafisária.","B":"R. epifisária.","C":"R. diafisária.","D":"Intra-articular.","E":"Intramedular."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35845","number":"35845","sourceNumber":"35845","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É correto afirmar sobre Osteoporose, exceto:","options":{"A":"Osteoporose Pós-Menopausa geralmente surge nos primeiros 10 anos após menopausa e a\ndeficiência estrogênica é a anormalidade básica.","B":"Os principais determinantes do risco de Osteoporose são o pico de massa óssea e a velocidade\nde perda óssea, ambos influenciados por fatores\nGenéticos e Ambientais.","C":"Obesas, em comparação a mulheres magras, fazem um pico menor de massa óssea e a perda\nóssea é mais rápida.","D":"A determinação da massa óssea é o melhor indicador mensurável do padrão ósseo e é útil na\navaliação do risco de fraturas osteoporóticas.","E":"A vit. D (colecalciferol) desempenha um importante papel na absorção intestinal do cálcio e na\nmineralização do osso novo, e sua principal fonte é a pele."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35873","number":"35873","sourceNumber":"35873","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O quadril de uma criança apresentando exame físico com teste Ortolani (-) e Barlow (+)\npodemos dizer que o mesmo é:","options":{"A":"Reduzido, mas luxável.","B":"Reduzido e estável.","C":"Luxado e redutível.","D":"Luxado e irredutível.","E":"Displásico."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35651","number":"35651","sourceNumber":"35651","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A anemia falciforme é frequente em nosso meio e caracterizada por doença hemolítica\ncrônica e grave, resultante da destruição prematura dos eritrócitos. Relativamente a esta doença,\nindique a assertiva correta:","options":{"A":"A crise dolorosa deve ser tratada com a transfusão sanguínea.","B":"Quando ocorre osteomielite, a salmonella é um agente etiológico importante a ser considerado.","C":"A dactilite ocorre por isquemia de partes moles de mãos e pés em geral em crianças menores de\ndois anos.","D":"A vacina contra pneumococo deve ser feita em crianças maiores de dois anos e confere ampla\nproteção contra esse agente.","E":"A crise de sequestro é mais comum após cinco anos de idade."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-34075","number":"34075","sourceNumber":"34075","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As variações de angulação dos membros inferiores (genu varo e genu valgo\nfisiológicos) são razões comuns que levam os pais a procurarem a assistência médica. O","options":{"A":"genu varo fisiológico acontece em lactentes com menos de um ano.","B":"genu valgo fisiológico ocorre comumente entre oito e dez anos.","C":"genu varo fisiológico desaparece por volta de três e quatro anos.","D":"genu valgo fisiológico persiste até o início da adolescência."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-22992","number":"22992","sourceNumber":"22992","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em escoliose idiopática do adolescente,","options":{"A":"a curva principal mais comum é a torácica à direita.","B":"a curva lombar está associada à obliquidade pélvica.","C":"o tratamento com órteses objetiva obter a correção da curva .","D":"o tratamento cirúrgico está indicado em curvas acima de 20 graus."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-22998","number":"22998","sourceNumber":"22998","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma criança do sexo feminino, com dois anos de idade, primogênita, gerada em\napresentação pélvica e nascida de parto\ncesária, é trazida à consulta com história de retardo da\nmarcha e claudicação às custas do membro inferior esquerdo. Ao exame físico, apresenta sinal de\nHart positivo. O diagnóstico provável, neste caso, é:","options":{"A":"epifisiólise proximal do fêmur.","B":"doença de Legg Calvé Perthes.","C":"displasia do desenvolvimento do quadril.","D":"osteogênese imperfecta."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-27142","number":"27142","sourceNumber":"27142","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente gestante de 33 anos, com dor de início recente no quadril esquerdo,\napresentando osteopenia difusa da cabeça e do colo\nfemoral à esquerda na radiografia da bacia e\nalterações à Ressonância Magnética características de hipossinal em T1 e hiperssinal difuso em\nT2. Qual é o diagnóstico mais provável?","options":{"A":"Artrite inflamatória ou infecciosa","B":"Necrose avascular","C":"Distrofia simpática reflexa","D":"Neoplasia","E":"Osteoporose transitória do quadril"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-27143","number":"27143","sourceNumber":"27143","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Assinale a opção correta:","options":{"A":"A radiografia é mais sensível que a tomografia computadorizada no diagnóstico de osteoma\nosteóide","B":"Aumento volumétrico ósseo e esclerose são característicos da Doença de Paget","C":"Condroblastoma acomete a metáfise de ossos longos","D":"Osteocondromas são tumores cartilagenosos intra-medulares","E":"Os fibromas não ossificantes são lesões osteolíticas com base cortical na metáfise de osso\nlongos de indivíduos acima dos 30 anos"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-27209","number":"27209","sourceNumber":"27209","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Escolar de 9 anos apresenta claudicação e dor no membro inferior direito há 1 semana.\nRefere que há dois dias foi medicado com\npenicilina benzatina intramuscular, aplicada em glúteo,\npara tratamento de piodermite. Ao exame: febril (38,3 graus); dor a compressão de coxa direita,\nsem manifestações articulares e ausência de sinal de Lasègue. RX de quadril e membro inferior\ndireito normal. Hemograma: 18000 leucócitos/mm (83% neutrófilos, 15% bastões). VHS 59 mm na\nprimeira hora. O diagnóstico provável é:","options":{"A":"Artrite séptica","B":"Osteomielite","C":"Infarto ósseo","D":"Sarcoma de Ewing","E":"Artrite reumatoide juvenil"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-11105","number":"11105","sourceNumber":"11105","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 23 anos, com práticas esportivas regulares, com fratura de fêmur há 2 dias,\napresentando dispneia intensa e confusão mental, o diagnóstico mais provável:","options":{"A":"Choque hipovolêmico","B":"Crise de asma brônquica","C":"Tromboembolismo pulmonar","D":"Embolia gordurosa","E":"Broncopneumonia"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-11052","number":"11052","sourceNumber":"11052","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menino, 8 anos, negro, há 5 dias com aumento do volume, calor, vermelhidão e dor\nintensa no joelho direito que dificultam a\ndeambulação, acompanhados de febre há dois dias. Joga\nfutebol diariamente, mas nega traumatismo. Antecedente de pneumonia aos sete anos de idade.\n\nExame físico: estado geral satisfatório, toxemiado, T 38,7°C, tecido celular subcutâneo escasso,\nlinfoadenomegalia inguinal bilateral, escoriações e hematomas em pernas e muita dor à\nmovimentação. A hipótese diagnóstica e a conduta são:","options":{"A":"Artrite tuberculosa, radiografia de tórax","B":"Artrite séptica, punção articular","C":"Artrite isquêmica, prova de faleização","D":"Artrite reumatoide, pesquisa de fator reumatoide","E":"Artrite traumática; radiografia simples do joelho"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-11089","number":"11089","sourceNumber":"11089","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual das manobras propedêuticas abaixo, quando positiva, melhor representa o\nacometimento inflamatório das articulações sacroilíacas?","options":{"A":"Lasêgue.","B":"Finkelstein.","C":"Phalen.","D":"Volkmann.","E":"N.d.a."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-250214","number":"250214","sourceNumber":"250214","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante o trabalho em área rural, um homem de 36 anos sofreu um acidente com\nextenso ferimento, deixando exposta uma fratura\nde extremidade distal da tíbia. Ao exame físico,\nobserva- se grande sangramento na região do ferimento, mas com boa perfusão dos artelhos. Qual\ndos seguintes esquemas esquema de antibióticos é o mais adequado nessa situação?","options":{"A":"Cefalosporina de 1ª geração + vancomicina ,","B":"Cefalosporina de 1ª geração + aminoglicosídeo + penicilina cristalina.","C":"Cefalosporina de 1ª geração + penicilina cristalina.","D":"Cefalosporina de 1ª geração + aminoglicosídeo."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-216388","number":"216388","sourceNumber":"216388","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menino de 12 anos, previamente hígido, apresenta dor no joelho direito há 3 semanas.\nEle é atlético, joga basquete e pratica\ncorrida de rua. Nega trauma recente. Descreve aumento da\ndor ao correr ou pular. Seu exame físico é normal, exceto por edema discreto e dor à palpação\nsobre a tuberosidade tibial direita. Baseado no caso acima, assinale a alternativa INCORRETA.","options":{"A":"A doença é encontrada apenas em jovens adolescentes antes do fechamento da placa de\ncrescimento.","B":"O deslocamento da epífise femoral pode ser a causa da claudicação, sendo mais comum nos\nadolescentes com sobrepeso.","C":"O tratamento desta patologia consiste em diminuição da atividade.","D":"A causa mais provável da dor é fratura por estresse."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-84884","number":"84884","sourceNumber":"84884","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente vítima de queda de bicicleta apresenta fratura exposta. A seguinte medida\né prioridade no tratamento ortopédico das\nfraturas expostas:","options":{"A":"Osteossíntese interna imediata para estabilização rígida do foco de fratura.","B":"Tração esquelética com 20x do peso.","C":"Fixação externa.","D":"Imobilização gessada.","E":"Limpeza cirúrgica do foco."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35745","number":"35745","sourceNumber":"35745","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um jovem de 18 anos, masculino, desenvolveu calafrios, febre e edema articular\ndoloroso unilateral. Qual teste seria mais apropriado, a fim de ajudar a fazer o diagnóstico?","options":{"A":"Cultura de líquido sinovial do joelho afetado.","B":"Teste da doença de Lyme.","C":"Ressonância magnética.","D":"Eletroforese de proteínas séricas.","E":"Estudo de cristais na membrana sinovial."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-311532","number":"311532","sourceNumber":"311532","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 13 anos, sexo feminino, procura atendimento devido a dor nos joelhos.\nEla relata que a dor piora ao subir ou descer\nescadas e ao praticar atividades físicas leves e nega\nhistória de trauma, febre ou qualquer infecção viral. O exame físico mostra ausência de sinais\nflogísticos, com dor à palpação da patela na região distal do fêmur bilateralmente, que piora com\nflexão do quadríceps. A hipótese diagnóstica para esse caso é:","options":{"A":"Doença de Osgood-Schlatter.","B":"Condromalácia da patela.","C":"Menisco discoide.","D":"Doença de Séver.","E":"Artrite juvenil."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-278968","number":"278968","sourceNumber":"278968","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre os exames de imagem para pacientes com quadro de artrite séptica e/ou\nosteomielite, assinale a alternativa correta:","options":{"A":"A ultrassonografia é muito sensível e específica tanto para artrite séptica quanto para\nosteolmielite","B":"A tomografia computadorizada é considerada o padrão-ouro para o diagnóstico de artrite séptica\ne osteomielite, pois consegue avaliar muito bem o\ntecido ósseo, além de ser exame acessível.","C":"A radiografia consiste no exame mais sensível para o diagnóstico de osteomielite por ser capaz\nde evidenciar lesões ósseas precocemente e ser\num exame rápido e de fácil acesso.","D":"A ressonância magnética é evitada em crianças em razão da radiação e da necessidade de\nsedação.","E":"A cintilografia é capaz de detectar atividade osteoblástica; porém, é pouco específica, podendo\nser positiva em casos de doenças\ndegenerativas, tumores e pós-trauma."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-154388","number":"154388","sourceNumber":"154388","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 12 anos joga futebol todos os dias. Há 2 anos, apresenta dor no joelho\ndireito. Exame físico: dor à palpação na tuberosidade anterior da tíbia, com aumento de volume. O\ndiagnóstico provável é:","options":{"A":"Fibromialgia.","B":"Doença de Osgood-Schatter.","C":"Doença de Legg-Calvé-Perthes.","D":"Doença de Sever.","E":"Osteocondromatose."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313395","number":"313395","sourceNumber":"313395","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As \"dores de crescimento\" fazem parte do grupo das dores funcionais, de etiopatogenia\npouco esclarecida, mas de evolução benigna. São\ncaracterísticas dessa dor:","options":{"A":"Contínua, não articular e unilateral em membro inferior.","B":"Intermitente, não articular e bilateral em membros inferiores.","C":"Recorrente, articular e bilateral em joelhos e tornozelos.","D":"Cíclicas com predomínio em ossos longos e/ou grandes articulações."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-288133","number":"288133","sourceNumber":"288133","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, vítima de colisão frontal de carro versus muro com\nveículo em alta velocidade. Ao exame físico, observa-se membro inferior encurtado, em flexão,\nadução e rotação interna. Qual a hipótese diagnóstica?","options":{"A":"Fratura de colo do fêmur","B":"Luxação anterior do quadril","C":"Luxação posterior do quadril","D":"Fratura de pelve"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-283971","number":"283971","sourceNumber":"283971","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As ?dores de crescimento? fazem parte do grupo das dores funcionais, de\netiopatogenia pouco esclarecida mas de evolução benigna. São características dessa dor:","options":{"A":"contínua, não articular e unilateral em membro inferior","B":"intermitente, não articular e bilateral em membros inferiores","C":"recorrente, articular e bilateral em joelhos e tornozelos","D":"cíclicas com predomínio em ossos longos e/ou grandes articulações"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-254185","number":"254185","sourceNumber":"254185","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação ao atendimento inicial de um paciente com fratura exposta, é INCORRETO:","options":{"A":"Introduzir precocemente antibioticoterapia.","B":"Imobilizar provisoriamente uma fratura de cotovelo com imobilização axilo-braquial.","C":"Cobrir o ferimento com curativo limpo e avaliar situação vacinal.","D":"Iniciar analgesia após a realização do exame de imagem."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-208611","number":"208611","sourceNumber":"208611","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um menino de 6 anos sofreu queda de skate há 2 horas, com trauma no membro\nsuperior esquerdo. O exame físico revela dor e\nedema na região do antebraço esquerdo. A seguir,\na Figura do raio x: A conduta mais adequada é:","options":{"A":"cirúrgica, com fixação com placa e parafuso","B":"cirúrgia, com fixação com haste intramedular","C":"redução incruenta e gesso axilopalmar","D":"conservadora, utilizando gesso axilopalmar","E":"nenhuma das alternativas anteriores"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/208611.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-221055","number":"221055","sourceNumber":"221055","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A Epifisiólise é caracterizada pelo alargamento e consequente enfraquecimento da\ncamada hipertrófica da placa de crescimento\nproximal do fêmur. Mediante o estresse mecânico\nlocal, propicia o escorregamento da Epífese em relação ao colo femoral ou vice-versa. Qual\nalteração do movimento do quadril é mais característica de uma Epifisiólise?","options":{"A":"Aumento da flexão e diminuição da rotação medial.","B":"Extensão aumentada e diminuição da abdução.","C":"Flexão diminuída e diminuição da rotação.","D":"Flexão diminuída e aumento da rotação medial."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-208620","number":"208620","sourceNumber":"208620","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na avaliação neonatal de um paciente com suspeita de displasia do quadril, o(s)\nexame(s) de imagem mais indicado(s) é:","options":{"A":"radiografias em frente e perfil de bacia","B":"ultrassonografia dos quadris","C":"radiografias em incidência alar e obturatriz","D":"tomografia computadorizada dos quadris","E":"ressonância magnética dos quadris"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-221366","number":"221366","sourceNumber":"221366","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação aos tumores ósseos da parede torácica, assinale a alternativa\nINCORRETA:","options":{"A":"A displasia fibrosa é responsável por aproximadamente 30% destes tumores.","B":"O osteocondroma ocorre comumente em homens de meia idade, cujo principal sintoma inicial e\nprecoce é a dor torácica localizada.","C":"Os condromas são responsáveis por 15% a 20% das lesões benignas da parede torácica e\noriginam-se na junção costocondral anterior.","D":"O granuloma eosinofílico é um componente benigno da histiocitose fibrosa maligna e afeta\nprincipalmente os homens."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-214093","number":"214093","sourceNumber":"214093","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"São características das dores recorrentes inespecíficas nos membros: I- piora ao calor\ne massagem. II- são mais frequentes entre 6 e 13\nanos, mas podem aparecem a partir dos 3 anos.\nIII- a dor habitualmente ocorre nos membros inferiores, mas podem surgir também nos membros\nsuperiores. IV- o exame físico é normal. V- dores musculares são intermitentes, de intensidade e\nfrequência variáveis. Estão CORRETAS:","options":{"A":"II, III, IV e V.","B":"I, II, IV e V.","C":"I, III e V.","D":"III, IV e V."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-208534","number":"208534","sourceNumber":"208534","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na avaliação neonatal de um paciente com suspeita de displasia do quadril, o(s)\nexame(s) de imagem mais indicado(s) é:","options":{"A":"radiografias em frente e perfil de bacia","B":"ultrassonografia dos quadris","C":"radiografias em incidência alar e obturatriz","D":"tomografia computadorizada dos quadris","E":"ressonância magnética dos quadris"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-185235","number":"185235","sourceNumber":"185235","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"São características das dores recorrentes inespecíficas nos membros em crianças e\nadolescentes, EXCETO:","options":{"A":"Dores musculares intermitentes, de intensidade e frequência variáveis.","B":"Habitualmente ocorre em membros inferiores e é sempre não articular.","C":"Localiza-se principalmente na coxa, face anterior da tíbia, no cavo poplíteo e nas panturrilhas.","D":"A dor é mais frequente no final do dia ou à noite e pode despertar a criança no sono noturno,\nsendo que, na manhã seguinte, a criança acorda\nsem dor.","E":"Dor a palpação muscular e à movimentação passiva."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-177345","number":"177345","sourceNumber":"177345","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quais são os cromossomos em que o sarcoma de Ewing e os tumores\nneuroectodérmicos primitivos (PNETs) apresentam a mesma translocação?","options":{"A":"cromossomos 11 e 22","B":"cromossomos 17 e 22","C":"cromossomos 15 e 22","D":"cromossomos 18 e 22","E":"nenhuma das alternativas anteriores"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-167818","number":"167818","sourceNumber":"167818","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre as ostemielites, assinale a afirmativa correta.","options":{"A":"As osteomielites crônicas representam um grande problema de saúde, decorrentes da\nimportante morbidade e alta mortalidade.","B":"A antibioticoterapia empírica deve ser sempre utilizada nas osteomielites crônicas.","C":"Os príncipios de terapêutica operatória incluem desbridamento localizado do osso desvitalizado.","D":"O Staphylococcus aureus é o agente mais isolado da osteomielite crônica."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-136747","number":"136747","sourceNumber":"136747","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante a linfadenectomia axilar, qual nervo que seccionado pode causar a discinesia\nde escápula ou \"escápula alada\"?","options":{"A":"Intercostobraquial","B":"Torácico longo","C":"Tóraco-dorsal","D":"Intercostal"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-309793","number":"309793","sourceNumber":"309793","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um jovem de sexo masculino, 28 anos de idade, em tentativa de suicídio, saltou do\ntelhado de sua casa com altura estimada em ± 4,5 m, na posição ortostática. Seguindo a\ncaracterística da mecânica do trauma, quais fraturas são esperadas, para que seja realizado seu\nexame físico direcionado?","options":{"A":"Fratura de clavícula, fratura de Colles, fratura de crânio e fratura de tornozelo;","B":"Fratura de arcos costais, fratura de cotovelo, fratura de úmero e coluna cervical;","C":"Fratura de Bacia, Síndrome da cauda equina, fratura de Colles e fratura de tornozelo;","D":"Fratura de calcâneo, fratura platô tibial, fratura de quadril e fratura toracolombar;","E":"Síndrome da cauda equina, fratura de Colles e fratura de clavícula;"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-309794","number":"309794","sourceNumber":"309794","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante visita da equipe de saúde a um domicílio, a Sra. Gilvanete informa que seu\nfilho de 13 anos de idade, IMC = 28,\nqueixou-se de dor em face anteromedial de coxa e joelho\ndireito, claudicante há 1 mês e com rotação externa do pé direito quando este avaliado em decúbito\ndorsal, com sinal de Drehman positivo. Baseado no quadro que o filho da Sra. Gilvanete apresenta,\npode-se suspeitar do diagnóstico mais provável de:","options":{"A":"Fratura do platô tibial medial do joelho direito.","B":"Lesão do menisco medial do joelho direito.","C":"Doença de Legg-Calvé-Perthes.","D":"Epifisiólise proximal do fêmur.","E":"Marcha anormal por defeito de fechamento neural do grupo lombar baixo."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-286093","number":"286093","sourceNumber":"286093","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante visita da equipe de saúde a um domicílio, a Sra. Gilvanete informa que seu\nfilho de 13 anos de idade, IMC = 28,\nqueixou-se de dor em face anteromedial de coxa e joelho\ndireito, claudicante há 1 mês e com rotação externa do pé direito quando este avaliado em decúbito\ndorsal, com sinal de Drehman positivo. Baseado no quadro que o filho da Sra. Gilvanete apresenta,\npode-se suspeitar do diagnóstico mais provável de:","options":{"A":"Fratura do platô tibial medial do joelho direito;","B":"Lesão do menisco medial do joelho direito;","C":"Doença de Legg-Calvé-Perthes;","D":"Epifisiólise proximal do fêmur;","E":"Marcha anormal por defeito de fechamento neural do grupo lombar baixo."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-274846","number":"274846","sourceNumber":"274846","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Os Sarcomas de Extremidades constituem um grupo de neoplasias de grande\nimportância, principalmente em pacientes jovens. Com relação a essas neoplasias, qual o seu\nprincipal sítio de metástase?","options":{"A":"Linfonodos.","B":"Fígado.","C":"Pulmão.","D":"Ossos.","E":"Cérebro."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-220272","number":"220272","sourceNumber":"220272","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um jovem de sexo masculino, 28 anos de idade, em tentativa de suicídio, saltou do\ntelhado de sua casa com altura estimada em ± 4,5 m, na posição ortostática. Seguindo a\ncaracterística da mecânica do trauma, para que seja realizado seu exame físico direcionado, quais\nfraturas são esperadas dentre as apresentadas a seguir?","options":{"A":"Fratura de clavícula, fratura de Colles, fratura de crânio e fratura de tornozelo.","B":"Fratura de arcos costais, fratura de cotovelo, fratura de úmero e coluna cervical.","C":"Fratura de Bacia, Síndrome da cauda equina, fratura de Colles e fratura de tornozelo.","D":"Fratura de calcâneo, fratura platô tibial, fratura de quadril e fratura toracolombar."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-220233","number":"220233","sourceNumber":"220233","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante visita da equipe de saúde a um domicílio, a sra. Gilvanete informa que seu filho\nde 13 anos de idade, IMC = 28, queixou-se de dor em face anteromedial de coxa e joelho direito,\nclaudicante há 1 mês e com rotação externa do pé direito quando este avaliado em decúbito dorsal,\ncom sinal de Drehman positivo. Baseado no quadro que o filho da sra. Gilvanete apresenta, o\ndiagnóstico mais provável é:","options":{"A":"Fratura do platô tibial medial do joelho direito.","B":"Lesão do menisco medial do joelho direito.","C":"Doença de Legg-Calvé-Perthes.","D":"Epifisiólise proximal do fêmur."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-221302","number":"221302","sourceNumber":"221302","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação aos tumores ósseos da parede torácica, assinale a alternativa\nINCORRETA:","options":{"A":"A displasia fibrosa é responsável por aproximadamente 30% destes tumores.","B":"O osteocondroma ocorre comumente em homens de meia idade, cujo principal sintoma inicial e\nprecoce é a dor torácica localizada.","C":"Os condromas são responsáveis por 15% a 20% das lesões benignas da parede torácica e\noriginam-se na junção costocondral\n\nanterior.","D":"O granuloma eosinofílico é um componente benigno da histiocitose fibrosa maligna e afeta\nprincipalmente os homens."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-187406","number":"187406","sourceNumber":"187406","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Assinale a assertiva CORRETA:","options":{"A":"Na lombalgia mecânica a dor geralmente se irradia para as coxas e apresenta evolução\ninsidiosa.","B":"A dor da hérnia discal geralmente inicia-se nas primeiras horas do dia, com quadro agudo,\nintenso, com irradiação da dor para um dos membros inferiores.","C":"No osteoma osteoide a dor ocorre durante o dia, à movimentação, devido à liberação de\nprostaglandinas pelas células tumorais nesse horário.","D":"No estreitamento do canal raquidiano a dor ao caminhar piora pricipalmete ladeira acima e\nmelhora ladeira abaixo, diferenciando da claudicação vascular.","E":"A dor de origem psicossomática apresenta-se com sensibilidade dolorosa profunda, sem\nalternância de localização."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183498","number":"183498","sourceNumber":"183498","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 5 anos, portador de doença falciforme, é internado na enfermaria de\npediatria com diagnóstico de osteomielite. Quais os principais microrganismos responsáveis por\nosteomielite na doença falciforme?","options":{"A":"Haemophilus influenzae e Mycoplasma pneumoniae.","B":"Staphylococcus aureus e Salmonella sp.","C":"Staphylococcus aureus e Haemophilus influenzae.","D":"Haemophilus influenzae e Salmonella sp.","E":"Salmonella sp e Mycoplasma pneumoniae."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-156315","number":"156315","sourceNumber":"156315","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 12 anos procura atendimento médico de emergência, queixando-se de\nfortes dores no quadril esquerdo e impotência funcional do membro inferior esquerdo. Ao exame\nfísico, o pediatra verificou peso de 91 kg, estatura de 149 cm, pressão arterial 130/90 mmHg, sem\ndemais anormalidades, Segundo a mãe, o paciente está em vigência de tratamento para\nemagrecer, e não houve nenhum tipo de trauma no quadril. A hipótese diagnóstica mais provável é:","options":{"A":"Deslocamento epifisário femoral.","B":"Sinovite transitória de quadril.","C":"Artrite reumatoide juvenil.","D":"Artrite séptica de quadril.","E":"Fratura de colo de fêmur."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-130016","number":"130016","sourceNumber":"130016","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Tratando-se da Doença de Legg-Calvé-Perthes, qual afirmativa abaixo está\nINCORRETA?","options":{"A":"Afeta primariamente crianças do sexo masculino.","B":"Ocorre mais frequentemente entre 2 e 12 anos de idade, com pico de incidência aos 6 anos de\nidade.","C":"Dividida em estágios: inicial, fragmentação, reossificação e remodelação.","D":"O início dos sintomas é rápido e os mais frequentes são: dor, rigidez, limitação de movimentos\ndo quadril comprometido e claudicação."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-132299","number":"132299","sourceNumber":"132299","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 14 anos, apresenta dor ao redor do joelho direito há3 meses, contínua,\ncom calor em região de fêmur distal e\naumento de volume local. Nega febre e perda de peso. À\nradiografia, apresenta lesão lítica irregular em região metafisária do fêmur, triângulo de Codman,\nreação periosteal em aspecto de \"raios de sol\", com invasão de partes moles. A biópsia foi\ncompatível com um tumor ósseo maligno. Assinale a alternativa CORRETA sobre este caso:","options":{"A":"O diagnóstico mais provável é Osteoma Osteoide, um tumor que frequentemente apresenta\nmetástases pulmonares.","B":"O diagnóstico mais provável é Sarcoma de Ewing, um tumor mais frequente entre o sexo\nfeminino.","C":"O diagnóstico mais provável é Osteossarcoma, um tumor que acomete mais frequentemente o\nsexo masculino.","D":"O diagnóstico mais provável é Fibrohistiocitoma maligno, o tumor ósseo mais frequente entre\ncrianças e adolescentes."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-107555","number":"107555","sourceNumber":"107555","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 36 anos, com quadro de dor em joelho D com derrame articular\nvolumoso, limitação funcional importante associada à eritema e aumento de temperatura local.\nVocê fez o diagnóstico de monoartrite e decidiu realizar artrocentese para diagnóstico de artrite\nséptica. Qual a análise abaixo confirmaria o diagnóstico de artrite séptica?","options":{"A":"Leucócitos entre 10,000 e 100,000 com predomínio de polimorfonucleares.","B":"Leucócitos > 100,000 com predomínio de polimorfonucleares.","C":"Leucócitos entre 10,000 e 100,000 com predomínio de polimorfonucleares e glicose normal.","D":"Líquido sinovial com aumento de viscosidade e cor amarelo citrino.","E":"Leucócitos 10.000 com 75% de polimorfonucleares."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-111722","number":"111722","sourceNumber":"111722","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As variações de torção e angulação dos membros inferiores são razões comuns pelas\nquais a família busca assistência médica. Sobre elas assinale a alternativa CORRETA:","options":{"A":"As deformidades angulares ocorrem principalmente no fêmur e mais raramente na tíbia e são em\nsua maioria patológicas.","B":"O Genu varo fisiológico apresenta pernas arqueadas, com os joelhos inclinados em direção a\nlinha média, aproximados.","C":"O tratamento do Genu varo fisiológico é raramente indicado, recomendado apenas se persistir\nalém de 2 a 3 anos de idade.","D":"O Genu valgo é uma variação angular comum no primeiro ano de vida e corrige-se\nhabitualmente antes dos 3 anos de idade.","E":"A torção femoral medial revela marcha com os pés virados para dentro e demanda correção\ncirúrgica antes de 2 anos de idade."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-83450","number":"83450","sourceNumber":"83450","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente, 65 anos, masculino, com quadro de lombalgia há 2 meses, com piora à\nmovimentação. Refere que há 45 dias iniciou paraparesia e há 2 dias está com incapacidade de\nmovimentação de membros inferiores. Você está de plantão no pronto-socorro e faz o primeiro\natendimento do paciente. Escolha a conduta CORRETA:","options":{"A":"Trata-se de lombalgia crônica com sinais de gravidade. Deve-se internar o paciente e solicitar o\nTC de coluna lombar e torácica para\navaliação de compressão\n\nmedular.","B":"Deve-se solicitar TC de coluna lombar e, se normal, iniciar tratamento domiciliar com analgesia.","C":"Trata-se de lombociatalgia e deve-se realizar tratamento com AINE e fisioterapia.","D":"Deve-se considerar a hipótese diagnóstica de espondilite anquilosante, visto tratar-se de\nhomem com lombalgia crônica.","E":"Não é necessário realização de exames complementares, visto tratar-se de lombalgia aguda\ncuja principal etiologia é de origem mecânica."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-34530","number":"34530","sourceNumber":"34530","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Assinale a alternativa correta quanto à osteoporose:","options":{"A":"O diagnóstico de osteoporose é feito com anamnese, dosagem de cálcio sérico e raio X de\ncoluna lombar e fêmur.","B":"A fisiopatologia é basicamente aumento da remodelação óssea com diminuição da reabsorção,\nem pacientes com disfunção da mineralização óssea.","C":"A Organização Mundial da Saúde define osteoporose como uma condição na qual a densidade\nmineral óssea é inferior a -1,0, desvio padrão do T-Score.","D":"Entre os fatores de risco para desenvolvimento de osteoporose temos: mulheres com\nmenopausa tardia, homens acima dos 65 anos,\nalimentação pobre em leite e derivados; tabagismo\ne sedentarismo.","E":"A osteoporose pode ter causas secundárias como: anorexia nervosa, hipertireoidismo,\nhiperparatireoidismo, diabetes mellitus, cirrose biliar primária, mieloma múltiplo, síndrome de\nMarfan, uso crônico de corticoides e artrite reumatoide, entre outras."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-22616","number":"22616","sourceNumber":"22616","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação às artrites bacterianas, é correto afirmar:","options":{"A":"São comumente poliarticulares.","B":"Sacroileíte é a manifestação predominante da brucelose em crianças.","C":"Haemophilus influenzae é o agente etiológico mais comum em neonatos.","D":"Pacientes com hipogamaglobulinemia são mais susceptíveis a infecções por neisseria.","E":"Diabetes, hemofilia e doença hepática avançada constituem fatores de risco."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-22634","number":"22634","sourceNumber":"22634","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A fratura em ?galho verde?, peculiar em crianças, é do tipo:","options":{"A":"Espiralada","B":"Cominutiva","C":"Transversa","D":"Incompleta","E":"nenhuma das anteriores"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-22637","number":"22637","sourceNumber":"22637","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação à artrite séptica de quadril na criança, assinale a INCORRETA:","options":{"A":"Pode desenvolver-se por contiguidade a partir de uma osteomielite.","B":"Os Streptococcus do grupo B e Staphylococcus aureus ocorrem predominantemente, abaixo de\n4 meses de idade.","C":"O S. aureus e S. pyogenes ocorre, predominantemente, em maiores de 4 meses.","D":"O tratamento é essencialmente clínico com antibióticoterapia.","E":"O uso de cateter umbilical em RN é fator predisponente para a artrite de quadril."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-359369","number":"359369","sourceNumber":"359369","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Homem de 57 anos é admitido no hospital com quadro de febre e calafrios há três dias.\nNão apresenta queixas localizatórias à admissão. Não possui comorbidades conhecidas e\napresenta creatinina sérica de 0,8mg/dL. Após as hemoculturas apresentarem crescimento de\nStaphylococcus aureus, o paciente recebe a prescrição de vancomicina pela via IV. O\necocardiograma transtorácico não revela quaisquer anormalidades. No segundo dia do tratamento\ncom vancomicina, o paciente se queixa de lombalgia moderada contínua, pior durante a\ndeambulação. Assinale a alternativa que apresenta uma conduta INADEQUADA nesse caso:","options":{"A":"Realizar a dosagem de vancomicina diariamente.","B":"Solicitar ecocardiograma transesofágico.","C":"Solicitar hemoculturas a cada 48h até a negativação.","D":"Solicitar Ressonância Magnética da coluna lombar."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-127407","number":"127407","sourceNumber":"127407","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação às Lesões por Esforços Repetitivos - Distúrbios Osteomusculares\nRelacionados ao Trabalho (LER-DORT) assinale a alternativa ERRADA:","options":{"A":"Normas de produção, modo operatório, exigências de tempo, ritmo de trabalho e conteúdo das\ntarefas estão entre seus principais determinantes","B":"O reconhecimento dos quadros de LER-DORT pelo INSS aumentou com a instituição do Nexo\nTécnico Epidemiológico Previdenciário (NETEP)","C":"Dentre as ações de saúde do trabalhador a serem desenvolvidas pelo Sistema Único de Saúde\n(SUS) está a reabilitação física dos\ntrabalhadores com Distúrbios Osteomusculares Relacionados\nao Trabalho","D":"Os distúrbios clínicos que acompanham os quadros de LER-DORT resultam de lesões agudas\ndo sistema osteomuscular"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-112055","number":"112055","sourceNumber":"112055","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Determinadas condições de trabalho podem desencadear ou agravar a Síndrome do\nManguito Rotatório. Constitui uma característica da síndrome:","options":{"A":"Dor contínua do ombro que melhora a noite","B":"Diagnóstico dependente das imagens do ombro podendo ser realizado por meio de radiografias\nsimples","C":"Melhora clínica com imobilização prolongada do ombro por pelo menos 6 semanas","D":"A associação com abdução e elevação dos braços acima da linha de ombros e elevação de\ncotovelo"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-22830","number":"22830","sourceNumber":"22830","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Homem, 42 anos, procura você para consulta por causa de dor lombar há 10 dias. Ao\ninício era discreta, mas agravou-se e agora impede de trabalhar e andar. É pedreiro, nega trauma,\nfebre, emagrecimento ou história médica anterior. A dor se irradia da região posterior da coxa\ndireita até o tornozelo. A extensão do membro é muito dolorosa, mas a força de extensão do hálux\né normal e, também, são normais os reflexos aquileu e patelar. Pode-se afirmar, EXCETO:","options":{"A":"Degeneração discal lombar e lesões das estruturas paravertebrais devem ser a causa deste\nquadro.","B":"Deve-se fazer repouso, mas apesar do prognóstico favorável, é necessário usar corticosteroide\nsistêmico e vitamina B12.","C":"Não é necessária qualquer propedêutica de imagem até a avaliação da resposta terapêutica\ninicial em algumas semanas.","D":"São fatores de risco para esta condição as atividades físicas, extenuantes ou sedentárias, o\ntrabalho estressante e distúrbios emocionais como ansiedade e depressão."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-259397","number":"259397","sourceNumber":"259397","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O trauma continua sendo uma causa proeminente de morte e incapacidade em todo o\nmundo. Em geral, a quantidade de energia absorvida pelo paciente politraumatizado corresponde à\nextensão das lesões musculoesqueléticas. As fraturas expostas requerem cuidado cirúrgico\nprecoce para tratamento adequado, de forma a minimizar complicações e sequelas. Com relação\nàs fraturas expostas, analise as assertivas abaixo: I - Fratura exposta é aquela na qual o osso\nfraturado ultrapassa os limites da pele, sendo obrigatória a visualização direta de osso exposto\npara\nesta caracterização. II - De acordo com a classificação de Gustillo-Anderson, as fraturas do tipo\nIIIC\nsão aquelas em que há lesão vascular associada, com necessidade de reparo. III - A lavagem\nprecoce e o desbridamento são os princípios fundamentais do tratamento, acompanhado de\nantibióticos e profilaxia anti-tetânica. IV - A fixação externa está proscrita no tratamento de\nfraturas\nexpostas devido ao elevado risco de síndrome compartimental aguda. Estão CORRETAS as\nassertivas:","options":{"A":"I, II e III, apenas.","B":"I e IV, apenas.","C":"III, apenas.","D":"II e III, apenas."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-238765","number":"238765","sourceNumber":"238765","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma criança de 2 anos de idade queixa-se de dor em membro superior direito com\nlimitação de movimento do antebraço após ter sido levantado pela mão enquanto passeava com o\npai. O diagnóstico mais provável nesse caso é:","options":{"A":"Sinovite do cotovelo.","B":"Anquilose do cotovelo.","C":"Doença de Legg-Calvé-Perthes.","D":"Pronação dolorosa do cotovelo."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-253931","number":"253931","sourceNumber":"253931","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Pré-escolar de dois anos foi levado emergência com dores no braço após ter sido\nlevantado pelo antebraço na escada de um\nshopping. antinha o antebraço fletido com a mão direita\nsobre o abdome e chora a pedindo para não mexer o membro, nem queria que tocassem no\ncotovelo. Este tipo de condição é conhecida por:","options":{"A":"Síndrome da pronação dolorosa","B":"Epicondilite lateral do cotovelo","C":"Sinovite transitória do cotovelo","D":"Osteocondrose da epífise do mero"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-217220","number":"217220","sourceNumber":"217220","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente 85 anos com fratura de colo de fêmur chega ao hospital para ser submetido a\ntratamento cirúrgico. Como antecedente é cardiopata, coronariopata e nefropata e usuário de AAS,\nclopidogrel, estatina, bloqueador de bomba de prótons, espironolactona e carvedilol. O ortopedista\npede orientação ao plantonista da emergência quanto a prevenção de sangramento\n\nintra-operatório. A afirmação verdadeira é:","options":{"A":"Administrar plasma fresco congelado para corrigir disfunção causada pelo AAS e clopidogrel.","B":"Administrar complexo protrombínico para corrigir disfunção do AAS e clopidogrel evitando-se a\nsobrecarga hídrica.","C":"Em caso de sangramento utilizar transfusão de plaquetas ou DDAVP venoso.","D":"Não operar no momento. Aguardar 7 dias para suprimir os efeitos do AAS e clopidogrel."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-203876","number":"203876","sourceNumber":"203876","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Cuidado com o tamanho e o excesso de peso da mochila para evitar danos como dores\ne, mais tarde, desvio da coluna deve ser uma\npreocupação de pais, familiares e educadores. A\nliteratura atual, em relação a essa medida preventiva, recomenda que o peso CORRETO da\nmochila não deva ultrapassar:","options":{"A":"10% do peso corporal da criança.","B":"7% do peso corporal da criança.","C":"5% do peso corporal da criança.","D":"3% do peso corporal da criança."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181978","number":"181978","sourceNumber":"181978","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A displasia do desenvolvimento do quadril é uma doença silenciosa, mas de\nprognóstico ruim quando não diagnosticada. O\nconjunto de sinais e sintomas dessa doença,\nfacilmente torna o diagnóstico fácil. Qual o sinal relacionado abaixo é devido a fraqueza do glúteo\nmédio?","options":{"A":"Hart.","B":"Trendelenburg.","C":"Barlow.","D":"Ortolani."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-182013","number":"182013","sourceNumber":"182013","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Os traumas que acometem as crianças diferem do adulto, onde lesões leves e\nmoderadas no adulto são consideradas muito\ngrave na criança, isso se deve a diferença do\ncomportamento do sistema músculo-esquelético. Em relação a esses conhecimentos, marque a\nopção correta.","options":{"A":"A capsula articular e os ligamentos na criança são de 2 a 5 vezes mais resistente que a fise,\npodendo contribuir, em parte, com as lesões fisárias.","B":"Apesar do trauma ser importante nas lesões fisárias, outros mecanismos causam maiores a\ndanos à fise, como: queimaduras por frio e\ncalor, infeções e lesões por insuficiência vascular.","C":"A lesão ligamentar do joelho de um adulto são mais frequentes e mais graves em relação a\nlesão ligamentar de uma criança.","D":"A epífise, conhecida como cartilagem de crescimento ou fise, está localizada entre a metáfise e\na diáfise dos ossos longos e pode facilmente\nser lesada nos traumas esportivos."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-179246","number":"179246","sourceNumber":"179246","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Recém-nascido com 12 horas de vida, nascido de parto vaginal, a termo, é avaliado em\nalojamento conjunto. Em relação ao exame físico desta criança, é CORRETO afirmar que:","options":{"A":"Se for detectada ao exame, paralisia braquial do tipo Erb-Duchene, esta pode estar associada à\nfratura de clavícula.","B":"Mancha arroxeada em região de nádegas, é sinal de tocotraumatismo, e deve ser investigada\ncuidadosamente.","C":"O eritema tóxico, quando diagnosticado, é característico de doença grave, e deve ser tratado\nagressivamente com emolientes.","D":"O achado clínico de craniotabes, é característico de algumas síndromes, e deve ser investigado."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-158234","number":"158234","sourceNumber":"158234","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança de 10 anos apresenta dor em perna esquerda com edema em região\nmetafisária de tíbia e febre há 15 dias. Refere\ntrauma há 30 dias, durante uma partida de futebol.\nRadiografia do membro acometido mostrou imagem tipo reação periosteal na região da dor.\n\nExames laboratoriais mostraram leucocitose com desvio a esquerda e anemia discreta, aumento do\nVHS e PCR. Para se ter o diagnóstico de\ncerteza da doença em questão, qual é o melhor exame a\nser solicitado?","options":{"A":"Eletroforese de proteínas;","B":"Tomografia computadorizada;","C":"Ressonância nuclear magnética;","D":"Biopsia óssea."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-158282","number":"158282","sourceNumber":"158282","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma criança de 8 anos, do sexo masculino, foi levada ao pronto atendimento devido a\ntrauma em terço distal de perna direita, durante uma partida de futebol. Seu tornozelo direito\nestava\ncom edema, dolorido e com limitação dos movimentos. Uma radiografia foi realizada e fizeram o\ndiagnóstico de fratura de Salter-Harris do tipo II. Em relação a essa fratura, podemos afirmar que:","options":{"A":"Ocorre na região metaepifisária dos ossos longos, com um fragmento da epífise aderida na\nmetáfise proximal.","B":"Ocorre na região diafisária dos ossos longos na transição entre a diáfise e a metáfise, sendo\nchamado o fragmento de Thurston Holland.","C":"Ocorre na camada hipertrófica da epífise de crescimento, sendo a fratura mais frequente do tipo\nSalter-Harris.","D":"Ocorre na camada basal da epífise distal dos ossos longos, onde existe uma maior capacidade\nde proliferação celular, predispondo a fraturas."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-157834","number":"157834","sourceNumber":"157834","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um homem de 22 anos queixa-se de dor lombar que persiste há 4 meses, além de\nrigidez na região lombar, que piora com a inatividade. Relata dificuldade para sair da cama de\nmanhã e necessidade de rolar de lado, tentando não flexionar ou girar a coluna vertebral para\ndiminuir a dor. A radiografia de coluna lombossacra provavelmente irá evidenciar:","options":{"A":"Doença articular degenerativa com formação de osteófitos.","B":"Destruição de corpo vertebral com fraturas em cunha.","C":"Osteonecrose difusa de coluna lombossacra.","D":"Sacroileíte com esclerose em torno das articulações sacroilíacas.","E":"Osteoporose com fraturas por compressão de L3?L5."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-137460","number":"137460","sourceNumber":"137460","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Pré-escolar de quatro anos é levado à consulta porque seus pais estão preocupados\ncom o fato de a criança apresentar quedas\nfrequentes e ?ter as pernas tortas?. Exame físico: geno\nvalgo. Considerando a evolução mais provável nesta condição, a conduta adequada é:","options":{"A":"Tranquilizar os pais.","B":"Encaminhar ao ortopedista.","C":"Solicitar radiografia de membros inferiores.","D":"Indicar a prática de exercícios físicos."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-105409","number":"105409","sourceNumber":"105409","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Após apresentar várias lesões compatíveis com piodermite, uma criança de sete anos\nde idade, sexo masculino, reclama dor no\njoelho esquerdo. Ao exame, está com 39°C, não\nconsegue apoiar o mesmo pé no chão. Não há imitação ao movimento da articulação. A velocidade\nde hemossedimentação é de 70 mm/1ª hora, e a proteína C reativa está positiva. Qual a hipótese\ndiagnóstica mais provável e o tratamento recomendado?","options":{"A":"Artrite piogênica; antibióticos.","B":"Osteomielite aguda; antibióticos.","C":"Doença de Osgood-Schlatter; antibiótico.","D":"Necrose avascular do fêmur proximal; imobilização do membro afetado."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-89150","number":"89150","sourceNumber":"89150","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente teve a perna esmagada sob motocicleta durante 5h, com fraturas da tíbia e\nfíbula. Inicialmente foi tratado com gesso,\nevoluindo com dor intensa. Este aparelho foi bivalvado,\nporém a dor não melhorou. Após 4 meses, o exame físico mostrou deformidade do pé com 45\ngraus de equino e varo e mínima capacidade de extensão dos dedos e tornozelo. O pé é doloroso à\ncarga. Baseado na história e exame clínico, qual deveria ser o melhor diagnóstico:","options":{"A":"Distrofia simpaticorreflexa","B":"Trombose venosa profunda","C":"Síndrome compartimental posterior superficial e profunda","D":"Osteomielite crônica esclerosante"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-33845","number":"33845","sourceNumber":"33845","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Aplicando-se os conhecimentos de anatomia humana, marque a alternativa\nINCORRETA:","options":{"A":"O nervo laríngico recorrente pode ser lesado nas tireoidectomias por sua íntima relação com a\nartéria tireoideana inferior.","B":"A trombose aguda e oclusiva no tronco da artéria mesentérica superior geralmente causa\nisquemia desde o jejuno até a junção retossigmoideana.","C":"Fazem parte da constituição da parede anterolateral do abdome os músculos reto abdominal,\noblíquo externo, oblíquo interno, transverso e piramidal.","D":"Os músculos do quadríceps da coxa são inervados pelo nervo femoral e têm como principal\nfunção estender a perna e controlar sua flexão."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-347422","number":"347422","sourceNumber":"347422","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um adolescente de 12 anos, pesando 85 kg e com índice de massa corpórea de 30\nkm/m², é atendido na emergência queixando-se de fortes dores no quadril direito e de impotência\nfuncional do membro inferior direito. O pai informa ao médico de plantão que o menino é\nhipertenso, que realiza um tratamento para emagrecer e nega associação do problema na perna a\ntrauma. Nesse caso, a hipótese diagnóstica mais provável é de","options":{"A":"epifisiólise femural.","B":"artrite séptica do quadril.","C":"artrite reumatoide juvenil.","D":"sinovite transitória do quadril."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-319911","number":"319911","sourceNumber":"319911","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Uma adolescente de 13 anos foi levada pela mãe à unidade básica de saúde, por\napresentar desvio na coluna. Segundo\ninformações maternas, a adolescente tem o hábito de usar\numa mochila pesada só de um lado do ombro e, com o passar do tempo, tem ficado \"mais torta\". A\nmãe informou que, quando jovem, também era assim, mas, em sua opinião, o caso da filha é pior.\nNegou outras queixas. No exame físico, observou-se assimetria dos ombros, escápula bastante\nproeminente à direita. O teste de Adams mostrou assimetria da caixa torácica. No caso em\nquestão, a hipótese diagnóstica é de","options":{"A":"escoliose familiar, sendo dispensada a investigação com exames complementares.","B":"lordose familiar, indica-se uma investigação com exame radiológico da coluna.","C":"escoliose, sendo necessária a determinação do ângulo de Cobb para indicar o tratamento clínico\nou cirúrgico.","D":"lordose associada à espinha bífida, uma vez que o teste de Adams foi positivo."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-318574","number":"318574","sourceNumber":"318574","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante um jogo de basquete feminino, a estrela da equipe, com 19 anos de idade,\napós um salto para \"enterrar\" a bola, pisou\nde maneira inadequada no solo e caiu. Não tendo sido\nmais capaz de se levantar naquele momento, foi levada para o Pronto-Socorro, onde chegou\ndeambulando, embora mancasse. A jogadora apresentava dor aos movimentos, edema e equimose\nno tornozelo esquerdo. Ao palpar o tornozelo, o médico não evidenciou nenhum ponto ósseo\nespecífico de dor. Diante desse quadro, considerando o preconizado em casos de entorse de\ntornozelo, a conduta adequada é","options":{"A":"pedir uma radiografia do tornozelo para avaliar a fratura.","B":"aplicar calor local e encaminhar a paciente para avaliação do ortopedista.","C":"iniciar fisioterapia motora precoce e solicitar o parecer de um ortopedista.","D":"imobilizar o membro afetado e medicar a paciente com anti-inflamatórío."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-269747","number":"269747","sourceNumber":"269747","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 81 anos sofreu queda da própria altura, evoluindo com fratura de Colles.\nEsse tipo de fratura se localiza:","options":{"A":"Ulna.","B":"Rádio.","C":"Fêmur.","D":"Úmero.","E":"Tíbia."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-269765","number":"269765","sourceNumber":"269765","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Jovem de 18 anos, boa condição sistêmica, praticante de esqui aquático, ao realizar\nhiperflexão do quadril com o joelho em extensão apresentou quadro doloroso súbito e hematoma\nna região posterior da coxa. No atendimento médico, relatou um estalido audível no momento do\nmovimento, dor durante a palpação e fraqueza muscular. Quarenta e oito horas depois da lesão foi\nrealizado exame de imagem e diagnosticado fratura por avulsão proximal da origem dos músculos\nisquiotibiais. Sobre os tecidos envolvidos na lesão e suas relações anatômicas, assinale a\nalternativa correta.","options":{"A":"Os músculos isquiotibiais possuem origem proximal na região posterolateral do fêmur, na linha\náspera e na crista supracondilar.","B":"O tecido ósseo é ágil em realizar reparo tecidual e o primeiro osso a ser formado em casos de\nfraturas ósseas é o lamelar, constituído de sistemas de Havers.","C":"A miogênese está restrita ao desenvolvimento pré-natal, no qual as células satélites apresentam\ncapacidade extraordinária de se diferenciarem em fibras musculares.","D":"Os músculos acometidos na lesão do jovem praticante de esqui aquático foram a cabeça curta\ndo bíceps femoral, semintedíneo e\nsemimembranáceo.","E":"A reinserção cirúrgica da avulsão proximal dos músculos isquiotibiais acontece no ísquio, na\nregião de tuberosidade isquiática."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-216319","number":"216319","sourceNumber":"216319","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menina de 11 anos, com história de aumento de volume em joelho direito iniciado há 65\ndias não tendo procurado facultativo. Apresentou queda da própria altura inadvertida onde evoluiu\ncom dor em MID e piora do edema inicial, além de refratariedade à analgesia convencional\ndomiciliar. Genitora relatou perda ponderal de 2kg no período. Neste momento procurou facultativo\nque solicitou as imagens radiográficas ao lado. Em relação à descrição radiológica, suspeita\ndiagnóstica e propedêutica confirmatória, é correto afirmar que:","options":{"A":"imagem em pipoca - Condrossarcoma - Biópsia excisional da lesão.","B":"fratura patológica - Mieloma - Punção de medula óssea.","C":"sarcoma granulocítico - Leucemia aguda - Citoquímica e imunofenotipagem.","D":"abscesso de Brondie - Osteomielite - Punção intraóssea e análise microbiológica.","E":"Triângulo de Codman - Osteossarcoma - PAAF."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/216319.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-203726","number":"203726","sourceNumber":"203726","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Pintor de 42 anos queixa-se de dor em cotovelo esquerdo. Ao exame, apresenta flexão\ne extensão preservadas, porém manifesta dor à\npalpação na face lateral do cotovelo, além de dor\nno local após manobra de extensão do punho contra resistência com cotovelo a 90°. Nesse caso, o\ndiagnóstico é:","options":{"A":"Bursite olecraniana.","B":"Artrite de cotovelo.","C":"Síndrome do canal de Guyon.","D":"Epicondilite lateral.","E":"Síndrome do pronador."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181782","number":"181782","sourceNumber":"181782","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"João Batista, 27 anos de idade, comparece à unidade básica de saúde com queixa de\ndor intensa na perna esquerda. Foi vítima de\nacidente de trânsito há 1 dia. A perna encontra-se\nedemaciada, com escoriações leves em terço médio da perna. Refere que foi atendido na unidade\nde prontoatendimento no dia do acidente, onde foi realizado o raio X, que não evidenciou fratura. O\nexame físico não evidenciou sinais de instabilidade ligamentar. A dor de João Batista foi\nclassificada pelo médico como de moderada intensidade. Sobre esta situação é correto afirmar que:","options":{"A":"o médico deve prescrever ao paciente paracetamol até melhora do quadro.","B":"o médico deve prescrever ao paciente um opioide forte mais paracetamol até melhora do\nquadro.","C":"o médico deve encaminhar o paciente para o serviço de ortopedia para reavaliação de fratura.","D":"o médico deve prescrever ao paciente um opioide fraco mais paracetamol","E":"não há necessidade de tratamento medicamentoso."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181926","number":"181926","sourceNumber":"181926","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Durante investigação clínica de uma paciente de oito anos de idade que apresenta\nfratura supracondiliana do úmero esquerdo, associado\ncom lesão neurológica, sinal de Kiloh-Nevin\npositivo, comprometimento dos músculo flexor profundo do dedo indicador, flexor do polegar e\npronador quadrado. O nervo que está comprometido neste paciente, é:","options":{"A":"nervo ulnar","B":"nervo radial","C":"nervo interósseo anterior","D":"nervo axilar","E":"nervo iterósseo posterior"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181936","number":"181936","sourceNumber":"181936","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente com lesão de tendão do músculo bíceps braquial porção longa. O teste clínico\nque indica está lesão, é:","options":{"A":"teste de Yergasson","B":"teste de Thompson","C":"teste de Gerber","D":"teste de Neer","E":"teste de Tinel"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181942","number":"181942","sourceNumber":"181942","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Das lesões a seguir, a que, quando presente em um paciente, indica fratura exposta\ntipo lll-C de Gustilo & Anderson é:","options":{"A":"Lesão vascular.","B":"Ferida com diâmetro de 5 cm.","C":"Fratura ocorrida em zona urbana.","D":"Lesão nervosa.","E":"Trombose venosa profunda."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181916","number":"181916","sourceNumber":"181916","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente do sexo masculino praticante de tênis de quadra, apresenta dor no cotovelo,\nlimitando sua função motora. O teste clínico realizado que indica a presença de epicondilite lateral\ndo cotovelo, é:","options":{"A":"teste de Allen","B":"teste de Thomas","C":"teste de Ober","D":"teste Apley","E":"teste de Cozen"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181930","number":"181930","sourceNumber":"181930","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É característica de osteomielite aguda hematogênica em crianças:","options":{"A":"afeta principalmente a região diafisária de ossos longos, onde a circulação é mais abundante.","B":"afeta região metafisária dos ossos longos, onde a resposta inflamatória é mais lenta para\nalcançar o agente patógeno.","C":"afeta principalmente a região epifisária, envolvendo a placa de crescimento.","D":"não tem predileção de região em ossos longos e a lesão óssea depende da quantidade de\ntoxinas e agentes patógenos.","E":"afeta principalmente a região diafisária em consequência de um aporte sanguíneo maior pelas\ninserções musculares nessa região."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181944","number":"181944","sourceNumber":"181944","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na avaliação clínica em criança portadora de sinal de Trendelenburg positivo indica\numa disfunção da estrutura anatômica:","options":{"A":"alteração da placa fisária distal do fêmur","B":"alteração da circulação do membro superior","C":"insuficiência do músculo glúteo médio","D":"lesão degenerativa da região sacroilíaca","E":"instabilidade da articulação do tornozelo"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-181951","number":"181951","sourceNumber":"181951","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente vítima de trauma fechado na perna esquerda, ao saltar sentiu dor aguda.\nNa investigação clínica o médico observou o teste\nde Thompsom positivo. Essa positividade indica:","options":{"A":"fratura de maléolo de tornozelo","B":"fratura diafisária de fíbula","C":"lesão do músculo tibial anterior","D":"lesão do nervo fíbula","E":"lesão do tendão calcâneo"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-134621","number":"134621","sourceNumber":"134621","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança de 06 anos com fratura supracondiliana do úmero, inicialmente sem déficit\nneurológico. Foi realizada redução incruenta e fixação percutânea dessa fratura. No primeiro\n\npós-operatório, com déficit de flexão da interfalangeana do polegar e da interfalangeana distal do\nindicador, sem déficit sensitivo. Neste caso, ocorreu lesão do nervo:","options":{"A":"Interósseo anterior.","B":"Radial.","C":"Ulnar.","D":"Mediano.","E":"Interosseo posterior."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-70296","number":"70296","sourceNumber":"70296","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As dores recorrentes nos membros são mais frequentes nos escolares entre 6 a 10\nanos de idade, com discreto predomínio nas\nmeninas. Essas dores acometem, principalmente, os\nmembros inferiores e costumam ser não articulares. O diagnóstico mais comum dessas dores é\nchamado:","options":{"A":"Dores reumáticas crônicas","B":"Artrite Reumatoide Juvenil","C":"Dor do crescimento","D":"Leucemia mieloide aguda","E":"Lúpus Eritematoso Sistêmico"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-50130","number":"50130","sourceNumber":"50130","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na abordagem ao paciente com queixas neurológicas, como parestesias, dor e\nfraqueza, utilizamos diversas manobras durante o\nexame físico para auxiliar na nossa investigação.\nConsidere, a esse respeito, as apresentadas no quadro a seguir: Manobras semiológicas: 1.\n\nPhalen; 2. Laségue; 3. Mingazzini/Enfermidades: a. Lombociatalgia; b. Síndrome do túnel do carpo;\n\nc. Miopatia inflamatória. Assinale a alternativa em que se correlaciona corretamente as manobras\nsemiológicas com as enfermidades a elas relacionadas.","options":{"A":"1-c; 2-a; 3-b.","B":"1-b; 2-a; 3-c.","C":"1-a; 2-c; 3-b.","D":"1-b; 2-c; 3-a.","E":"1-c; 3-b; 2-a."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-264510","number":"264510","sourceNumber":"264510","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança de 14 meses, dá entrada na consulta pediátrica, com a mãe, que relata que a\nfilha vem mancando desde que começou a andar. No exame físico, observa-se a perna direita mais\ncurta do que a esquerda e alteração da marcha, como também abdução da articulação coxo\nfemural direita é limitada. A suspeita diagnostica mais provável é:","options":{"A":"Tumor de fêmur a direita (Sarcoma de Wilms).","B":"Luxação congênita do quadril.","C":"Epifisiólise.","D":"Paralisia cerebral.","E":"Sinovite Transitoria do quadril."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-257235","number":"257235","sourceNumber":"257235","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"João tem 45 anos e vem à Unidade de Saúde da Família (USF) referindo dor no ombro\ndireito, que piora quando eleva o membro superior acima da cabeça. Nega história de trauma.\n\nTrabalha como estoquista em um supermercado. Ao exame físico, foi identificado dor na região\nsubacromial à palpação; amplitude de movimento preservada à movimentação passiva e diminuída\nà movimentação ativa de elevação; dor no teste de Apley, força preservada e dor nas manobras de\nNeer e Hawkins. Pela história e exame físico, a médica da USF identifica tendinopatia do manquito\nrotador e orienta crioterapia, uso de AINE, repouso relativo (fornece atestado para 10 dias) e\nencaminhamento para fisioterapia. Discutindo o caso com um colega residente de ortopedia, a\nmédica foi repreendida por não ter encaminhado o paciente João para o especialista ou por não ter\nsolicitado uma ressonância magnética do ombro, pois havia o risco de haver lesão do tendão do\nsupraespinhoso. Observando a história do paciente João e a discussão entre a médica da USF e o\ncolega residente em ortopedia, a melhor opção na consulta realmente teria sido:","options":{"A":"A informada pelo residente de ortopedia de referenciar o paciente para o ortopedista, já que\nesse tipo de situação não se resolve na\nAtenção Primária à Saúde.","B":"A de não encaminhar, mas solicitar ultrassonografia do ombro e não a ressonância magnética,\npois é mais barato para os pacientes que\nfrequentam a Atenção Primária à Saúde.","C":"A tomada pela médica, pois a história e exames físicos reforçam a avaliação de tendinopatia e o\nmanejo inicial deveria ser como o recomendado pela profissional.","D":"A orientada pelo residente de ortopedia, somente após a chegada do resultado da ressonância\nmagnética, que é o exame padrão ouro para os sintomas do paciente.","E":"A orientada pelo residente de ortopedia, porém sem a necessidade do exame de imagem, já que\na história e exame físico reforçam lesão que\nrequer tratamento cirúrgico."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-240917","number":"240917","sourceNumber":"240917","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente vítima de atropelamento, com imobilização em perna direita, curativo em faixa.\nAo exame físico, evidenciado ferimento\nextenso na perna com mais de 10 cm, com presença de\nsangramento ativo, com gotículas de gordura no mesmo. Não havia presença de asfalto, grama ou\noutras contaminações na ferida. Raio X evidenciava fratura multifragmentada diafisária de tíbia e\nfíbula. Qual a classificação da fratura, de acordo com a classificação de Gustilo e Anderson, e qual\nantibioticoterapia deve ser iniciada?","options":{"A":"Tipo III, cefalosporina de primeira geração + aminoglicosídeo.","B":"Tipo III, macrolídeo + quinolona.","C":"Tipo I, cefalosporina de primeira geração.","D":"Tipo II, cefalosporina de terceira geração.","E":"Tipo III, cefalosporina de terceira geração."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-241003","number":"241003","sourceNumber":"241003","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Escolar de 6 anos, previamente hígido com queixa de súbita claudicação ao acordar. A\nmãe relata que a criança não consegue apoiar o pé direito no chão e reclama de muita dor no\nquadril. Nega febre e outras queixas, mas refere quadro gripal na semana anterior. O exame físico\né normal exceto pela limitação de movimentação do quadril. A hipótese mais provável e o exame a\nser realizado é:","options":{"A":"Artrite séptica do quadril e artroscopia.","B":"Necrose asséptica da cabeça do fêmur e RX de quadril.","C":"Artrite reumatoide aguda e fator reumatoide.","D":"Lúpus eritematoso juvenil e FAN.","E":"Sinovite transitória do quadril e USG de quadril."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-212554","number":"212554","sourceNumber":"212554","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Enzo, seis anos, é levado ao pronto atendimento pediátrico por estar claudicando há\numa semana. Não há relato de traumas e a\ngenitora afirma que de intercorrências apresentou um\nquadro disentérico há 3 semanas tratado com ciprofloxacina por 3 dias. Exame físico: sinais vitais\nnormais e IMC entre o z escore +1 e +2 DP. Ausculta cardiorrespiratória sem alterações. Abdome\ninocente. Dor na articulação do quadril direito em movimentos de rotação e adução. Exames\nlaboratoriais: leucócitos normais, discreta elevação da VHS. Radiografias de perna e quadril\ndireitos: normais. Qual o diagnóstico do paciente?","options":{"A":"Artrite séptica.","B":"Sinovite transitória do quadril.","C":"Epifisiólise.","D":"Doença de Legg-Calvé-Perthes.","E":"Artrite psoriática."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-212555","number":"212555","sourceNumber":"212555","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente com 13 anos de idade, apresentando dor no membro inferior à direita,\nfebre e emagrecimento. Radiografia simples\nrevela imagens de ?cascas de cebola? e a\nressonância mostra envolvimento de partes moles. O quadro descrito sugere:","options":{"A":"Osteomielite.","B":"Osteossarcoma.","C":"Condrossarcoma.","D":"Sarcoma de Ewing.","E":"Linfoma."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-110417","number":"110417","sourceNumber":"110417","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Não é sinal de alerta para dor lombar:","options":{"A":"Trauma recente importante.","B":"Perda de peso involuntária.","C":"Postura antálgica.","D":"Idade acima de 70 anos.","E":"Dor refratária ao tratamento, após 6 semanas."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-65933","number":"65933","sourceNumber":"65933","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A osteomielite hematogênica aguda se inicia geralmente na metáfise dos ossos longos,\ndecorrente de bactérias vindas de um foco à distância, porque: I- As defesas orgânicas neste local\nsão menores; II- O fluxo sanguíneo lento, através das dilatações vasculares, facilita a sua\nimplantação; III- O tecido medular (osso) funciona como meio de cultura. Está(ão) correta(s):","options":{"A":"Apenas I e III.","B":"Apenas II e III.","C":"Apenas I e II.","D":"Apenas I.","E":"I, II e III."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-65854","number":"65854","sourceNumber":"65854","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"J.D.G., masculino, 8 anos de idade, teve fratura fechada dos ossos do antebraço\ndireito, sendo realizada redução incruenta e\naparelho gessado axilopalmar. Retorna ao PS, após\n6h, com dor em todo o membro superior acometido e parestesia na mão. No momento, há boa\nperfusão e pulso presente. Qual a sua conduta inicial?","options":{"A":"Orientar analgésico e manter o membro elevado, em casa.","B":"Contatar a equipe de ortopedia e traumatologia.","C":"Abrir (bivalvar) o gesso e manter o membro elevado, em observação.","D":"Retirar o gesso e realizar fasciotomia ampla.","E":"Retirar o gesso, medir a pressão intracompartimental e realizar a fasciotomia ampla."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-71580","number":"71580","sourceNumber":"71580","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um paciente do sexo masculino, de 5 anos, chega claudicando no pronto-socorro com\numa história de dor em quadril esquerdo que se\nirradia para o joelho esquerdo há 2 dias. Mãe\nrelata quadro de faringite viral duas semanas antes que se resolveu sem medicação. Ao exame\nfísico, apresenta-se com o quadril esquerdo abduzido e flexionado, com dor à movimentação\npassiva. A velocidade de hemossedimentação é de 28 mm/h. O diagnóstico mais provável é:","options":{"A":"Artrite reumatoide juvenil pauciarticular.","B":"Febre reumática.","C":"Artrite séptica.","D":"Sinovite transitória do quadril.","E":"Doença de Legg-Calvè-Perthes."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-36712","number":"36712","sourceNumber":"36712","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual das afirmações abaixo é verdadeira?","options":{"A":"A síndrome compartimental desenvolve-se nas primeiras 12 horas.","B":"As fraturas de fêmur podem provocar hipervolemia.","C":"A presença de pulso periférico afasta lesão vascular.","D":"As fraturas expostas da perna evoluem para síndrome compartimental.","E":"O tratamento da síndrome compartimental consiste em elevar e aquecer o membro afetado."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-322060","number":"322060","sourceNumber":"322060","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Nina, 43 anos, vem para consulta por dores no corpo que se intensificaram há 2 meses.\nComeçou com dores na região lateral do quadril, à direita, irradiando pela lateral da coxa e da\nperna, até o pé. Tem agravamento no final do dia de trabalho como auxiliar de limpeza, mas no\núltimo mês passou a ter dores também na perna esquerda e no pescoço, na maioria dos dias e, às\nvezes, também lhe dói o cotovelo direito. Usou paracetamol 35 gotas (200mg/mL) até 2 vezes ao\ndia e diclofenaco + dipirona + orfenadrina + cafeína outras vezes, sempre com melhora parcial e\ntransitória. Sobre este caso clínico, avalie as asserções a seguir. I. A dor em membro inferior\ndireito\né uma provável ciatalgia. É, portanto, recomendado que se proceda ao teste de Lasègue, no exame\nfísico. II. Limitação da amplitude de adução e reprodução da dor em membro inferior direito ao\npressionar a região proximal ao trocanter indicam dor miofascial. III. A hipótese de fibromialgia é\nprovável. Portanto, está indicado, no exame físico, que se realize a pesquisa de pontos dolorosos\npadronizados para fibromialgia. IV. Caso o exame físico não indique outros sinais flogísticos além\ndas dores, seria indicado suspen- der o fármaco contendo AINE e aumentar a dose e frequência do\nparacetamol. As assertivas que se aplicam corretamente à consulta atual são apenas","options":{"A":"I e III apenas.","B":"I e IV apenas.","C":"II e III apenas.","D":"II e IV apenas.","E":"III e IV apenas."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-257463","number":"257463","sourceNumber":"257463","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Lactente de 18 meses é trazido ao hospital por queixas de febre e dor em membro\ninferior direito de início há 3 dias, que\nevoluiu com claudicação e atualmente recusa em deambular.\nAo exame apresenta edema, eritema e calor em extremidade distal do fêmur. Radiografia do\nmembro demonstra deslocamento dos planos musculares profundos em relação à metáfise\nadjacente, comparado ao membro oposto. Sobre esta situação, analise as alternativas abaixo. I ? O\nmelhor exame para confirmar o esclarecimento desta situação é a ressonância magnética. II ? É\nessencial obter material para culturas (sangue, osso) antes da administração de antibióticos,\nmesmo que haja atraso em algumas horas para o início dos antibióticos. III ? Para a maioria das\ninfecções a duração da antibioticoterapia é de 21 a 28 dias, de forma endovenosa por todo o\nperíodo. Estão corretas as assertivas","options":{"A":"I apenas.","B":"I e II apenas.","C":"I e III apenas.","D":"II e III apenas.","E":"I, II e III."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-257523","number":"257523","sourceNumber":"257523","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 46 anos, previamente hígido, relata 2 semanas de evolução de dor em\ncoluna torácica, contínua, seguida de febre aferida. Quando da investigação realizou ressonância\nque demonstrou alteração de T5 e T6, com hipossinal em T1 com perda de definição de corpos e\nplanaltos vertebrais e hiperssinal do disco e corpos vertebrais em T2. Foi feita punção guiada por\ntomografia que evidenciou cocos gram positivos. Considerando a hipótese diagnóstica principal,\nassinale a assertiva correta:","options":{"A":"Leucocitose e neutrofilia tem altos níveis de sensibilidade diagnóstica.","B":"A biópsia guiada por tomografia tem alta sensibilidade e exclui a doença quando negativa.","C":"VHS e proteína c reativa tem baixa sensibilidade, não podendo ser usados para excluir a\ncondição.","D":"A tomografia por emissão de pósitrons (FDG-PET) apresenta alta acurácia e é alternativa à\nressonância.","E":"A radiografia simples apresenta alta sensibilidade na detecção da condição, com menor custo\nem relação à ressonância."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-232670","number":"232670","sourceNumber":"232670","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Escolar de 10 anos apresenta-se com dor em membro inferior direito há 2 meses, que\nvem aumentando progressivamente, agora limitando\nos movimentos, sem febre. Ao exame\nobserva-se um aumento de volume de metáfise de fêmur direito, doloroso à palpação. Realizado\nraio X que revela destruição óssea com margens pouco definidas, associada ao descolamento do\nperiósteo com aspecto de ?casca de cebola?. Analise as alternativas a seguir sobre este caso. I. A\nressonância magnética é o exame mais adequado para complementar o diagnóstico. II. O local\nmais acometido por metástases é o fígado. III. Após confirmação do diagnóstico por biópsia, o\npaciente deve ser submetido ao tratamento quimioterápico antes do tratamento cirúrgico local. IV.\nExistem altas taxas de cura, mesmo nos pacientes metastáticos. Estão CORRETAS apenas as\nalternativas:","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II e IV.","E":"I, III e IV."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-202884","number":"202884","sourceNumber":"202884","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente, 60 anos, é cozinheira e procura a unidade de saúde porque há 3 semanas\nvem apresentando forte dor em ombro direito,\nprincipalmente ao cozinhar, varrer a casa e estender\nroupa no varal. O que tirou a dor momentaneamente foi tomar um medicamento originalmente\nprescrito para seu marido após uma cirurgia do joelho. Observa que, talvez pelo uso desse\nfármaco, ficou com o intestino \"ressecado\". Mesmo assim solicita receita porque gostou muito dos\nefeitos e a farmácia exigiu prescrição médica para lhe vender. Avalie as asserções a seguir: I)\nProvavelmente trata-se de constipação por uso de derivados de opioide II) Anamnese e exame\nfísico não bastam para definir a abordagem terapêutica e o exame de escolha é o ultrassom, por ter\nbaixo custo. III) Trata-se de uma dor de ritmo inflamatório e, portanto, AINE auxiliaria no processo\ncicatricial da lesão no ombro. IV) Paciente deve ser orientada a realizar repouso absoluto do ombro\npara que haja remissão completa da dor. Assinale a alternativa que indique a (s) assertiva (s)\nCORRETA (S):","options":{"A":"Apenas a I está correta.","B":"Apenas a III está correta.","C":"Apenas I e III estão corretas.","D":"Apenas I e II estão corretas.","E":"Todos estão corretas."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-174215","number":"174215","sourceNumber":"174215","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente do sexo feminino, de 64 anos de idade relata dor em transição toraco-lombar\ncom 4 semanas de evolução, contínua, que não\nalivia com o repouso. Relata alguns episódios de\nfebre no período, uso diário de analgésicos comuns com alívio parcial da dor. Nega comorbidades.\nHemograma com 9500 leucócitos 7% de bastões, proteína-C-reativa=98 mg/L. Realizou\nressonância que demonstrou redução e realce heterogênio do disco e dos corpos vertebrais de\nT11-T12, com extensão paravertebral. Considerando o caso, é correto afirmar que:","options":{"A":"A presença de febre aferida é patognomônica de processo infeccioso bacteriano.","B":"A ausência de leucocitose exclui o diagnóstico de infecção bacteriana.","C":"A causa mais comum da doença é a disseminação por contiguidade.","D":"A biópsia guiada por tomografia é o padrão ouro de diagnóstico.","E":"A doença é mais comum em pacientes do sexo masculino."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-103176","number":"103176","sourceNumber":"103176","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente feminina, de 53 anos, com história de diabetes, em uso de metformina,\napresenta 4 meses de evolução de parestesia\nem mão direita, que acomete os 4 primeiros\nquirodáctilos e piora durante a noite. Apresenta força motora, reflexos e trofismo preservados.\nTinel\ne Phalen positivos. Em relação ao caso, assinale a assertiva correta.","options":{"A":"O diabetes mellitus não está associado ao quadro.","B":"O uso de tala de imobilização do punho em posição neutra deve ser indicado apenas como\nterapia de segunda linha.","C":"Como a paciente ainda não apresenta alteração trófica ou de força motora a descompressão\ncirúrgica precoce é estratégia aceitável para\nevitar progressão.","D":"Com a evolução da doença pode ocorrer fraqueza dos movimentos de oposição e abdução do\npolegar.","E":"Os achados da eletroneuromiografia são diagnósticos, mas não são relevantes em relação à\ndefinição terapêutica."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-35095","number":"35095","sourceNumber":"35095","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Com relação ao tratamento da osteomielite bacteriana da coluna vertebral, é\nCORRETO afirmar que:","options":{"A":"A drenagem cirúrgica está indicada na maioria dos casos.","B":"O tempo de tratamento com antibióticos adequados deve se prolongar, em geral, por 6 a 8\nsemanas.","C":"A melhora da dor não está relacionada à imobilização e repouso no leito.","D":"O tratamento com antibióticos deve ser descontinuado mesmo que a melhora dos\nníveis de VHS e PCR, com relação aos valores iniciais, seja < 30%.","E":"Os grandes abscessos epidurais não devem ser drenados."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-27916","number":"27916","sourceNumber":"27916","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O principal agente etiológico da artrite séptica no lactente é:","options":{"A":"Staphylococcus aureus.","B":"Haemophilus influenzae.","C":"Escherichia coli.","D":"Streptococcus pneumoniae.","E":"Streptococcus viridans."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-27924","number":"27924","sourceNumber":"27924","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 35 anos de idade, sexo masculino, deu entrada no serviço de emergência\nreferindo que ao jogar futebol torceu o\ntornozelo direito. Ao exame, ele apresentava um edema\nacentuado com equimoses no bordo externo do tornozelo; dor importante e impotência funcional do\nmembro inferior direito. Na radiografia do tornozelo se observa uma fratura por avulsão do maléolo\nfibular. Em relação a este caso, assinale a alternativa correta:","options":{"A":"Este tipo de lesão deve ser considerado como entorse grau I","B":"Pela fratura em avulsão o entorse deve ser considerado grau III","C":"Considera-se este tipo de lesão como uma distensão muscular","D":"O entorse deve ser classificado como grau II pela pequena instabilidade","E":"O mais importante é realizar um exame de Ressonância Magnética, pois os dados apresentados\nsão insuficientes para julgar o caso"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-360336","number":"360336","sourceNumber":"360336","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Assinale a alternativa correta: I - O tratamento cirúrgico das fraturas supra e\nintercondilianas do úmero deverá ser feito\nnos primeiros dois ou três dias após a fratura , desde que\nexistam materiais adequados e equipe treinada; II - Osteoma osteóide é um tumor benigno\nformador de osso, caracterizado por um núcleo pequeno, com potencial de crescimento\ndesproporcional à dor. Clinicamente, os osteomas osteóides surgem nas diáfises de ossos longos\nde adolescentes (10 a 25 anos), tíbia e fêmur principalmente, podendo aparecer também na coluna,\ncom dor que piora à noite. III - Classicamente, a ruptura espontânea do tendão de Aquiles acomete\nindivíduos de meia idade, sedentários, que se envolvem em atividades esportivas durante o lazer.\n\nEpidemiologicamente, ocorrem dois picos de lesão na ruptura espontânea. O primeiro pico, dos\nadultos jovens e de meia-idade, de alta\nincidência, em geral, está associado a práticas esportivas.O\nsegundo pico ocorre na faixa etária dos 70 anos e de causa não bem definida","options":{"A":"I, II e III estão corretas.","B":"I e III estão corretas.","C":"Apenas e III está correta.","D":"I e II estão corretas."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-345007","number":"345007","sourceNumber":"345007","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre seu conhecimento a respeito da anatomia dos ossos do corpo, responda a\nalternativa correta:","options":{"A":"Na fileira proximal estão os ossos escafoide, semilunar, piramidal e unciforme","B":"Os ossos piramidal e pisiforme se articulam","C":"Trapézio e trapezoide fazem parte da terceira fileira","D":"Capitato e escafoide estão na fileira distal"},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313786","number":"313786","sourceNumber":"313786","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação à anatomia do tornozelo:","options":{"A":"O domo talar é mais largo na sua porção posterior.","B":"Na flexão plantar cria-se uma situação de \"\"estabilidade óssea\"\".","C":"Na dorsiflexão o tálus força a fibula em rotação externa.","D":"Na dorsiflexão a articulação é mais móvel."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313787","number":"313787","sourceNumber":"313787","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O compartimento lateral da perna é composto por:","options":{"A":"Músculo fibular curto e nervo fibular profundo.","B":"Músculo gastrocnêmio e sóleo.","C":"Músculo tibial posterior, plantar, flexor longo dos dedos e flexor longo do hállux.","D":"Músculo fibular longo e curto, e nervo fibular superficial."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313788","number":"313788","sourceNumber":"313788","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na epicondilite lateral:","options":{"A":"O tratamento é geralmente cirúrgico.","B":"A origem da lesão é no extensor radial longo do carpo.","C":"No estudo imuno-histoquímico é encontrado processo inflamatório acentuado.","D":"O extensor comum dos dedos é a origem da doença em um terço dos casos."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313789","number":"313789","sourceNumber":"313789","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O tendão do músculo tibial posterior:","options":{"A":"Tem origem na face posterior e medial do terço proximal e médio da tíbia.","B":"Tem a inserção na tuberosidade do navicular.","C":"Não tem expansões em leque para as bases plantares do primeiro, segundo e terceiro\ncuneiformes.","D":"É agonista dos fibulares longo e curto."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-313790","number":"313790","sourceNumber":"313790","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quanto à fasceíte plantar:","options":{"A":"A fáscia origina-se na tuberosidade lateral do calcâneo.","B":"A indicação cirúrgica é frequente.","C":"É comum no pé cavo.","D":"Tratada com corticoesteróide não interfere no metabolismo do tecido colágeno."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-314849","number":"314849","sourceNumber":"314849","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 16 anos refere dor ao redor do joelho esquerdo há cerca de 2 semanas.\nPratica esportes com frequência e treina\nfutebol regularmente. Apresenta aumento de volume em\nregião de tíbia proximal esquerda, levemente doloroso à palpação. Médico solicita radiografia do\nlocal com os seguintes achados: levantamento periosteal em região de tíbia proximal esquerda\nassociada à área osteolítica mal delimitada e edema de partes moles. Avalie as alternativas abaixo\ne marque a que melhor indica a hipótese diagnóstica e a conduta inicial:","options":{"A":"Fratura por estresse devido à prática de exercícios físicos e imobilização com gesso.","B":"Osteossarcoma e biópsia por punção feita por ortopedista oncológico.","C":"Doença de Osgood-Schlatter e repouso com antinflamatórios não hormonais.","D":"Fratura simples e imobilização com gesso."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-304723","number":"304723","sourceNumber":"304723","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Recém-nascido a termo, com peso de nascimento = 4.100g, apresentou fratura de\nclavícula à direita, que foi acompanhada de diminuição da mobilidade do membro superior direito,\ncom limitação da flexão e extensão do antebraço e manutenção da força da mão. Esse quadro é\nsugestivo de uma paralisia do:","options":{"A":"Plexo braquial médio","B":"Plexo braquial inferior","C":"Plexo braquial superior","D":"Ramo clavicular do plexo braquial","E":"Nenhuma das anteriores"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-299277","number":"299277","sourceNumber":"299277","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre crianças com osteomielite aguda hematogênica, leia as assertivas a seguir e\nassinale a alternativa CORRETA. I. Infecção envolve, em geral, metáfises de ossos longos com\ncrescimento rápido. II. Com o aumento do abscesso, cresce a pressão intramedular que leva a\nisquemia cortical e escape do material purulento para o espaço subperiosteal. III. Em crianças\nmenores de 2 anos, pode haver propagação da infecção para a epífise.","options":{"A":"I está correta.","B":"II está correta.","C":"I e II estão corretas.","D":"II e III estão corretas.","E":"I, II e III estão corretas."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-269537","number":"269537","sourceNumber":"269537","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Quanto às fraturas de ossos longos do esqueleto apendicular, é correto afirmar:","options":{"A":"O calo ósseo formado em uma fratura é a comprovação da existência de consolidação óssea por\nprimeira intenção.","B":"Fraturas metaepifisárias possuem traço de fratura comprometendo a superfície articular.","C":"Materiais de osteossíntese são utilizados para se obter consolidação óssea sem formação de\ncalo ósseo.","D":"Fraturas diafisárias devem consolidar-se em estabilidade absoluta ? ausência total de\nmovimento entre os fragmentos.","E":"A formação de calo ósseo é especialmente desejável nas fraturas articulares."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-269538","number":"269538","sourceNumber":"269538","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em pacientes idosos portadores de osteoporose, há o risco aumentado de fraturas do\nfêmur. Sobre os tipos de fraturas do fêmur nessa população, é CORRETO afirmar:","options":{"A":"A fratura do colo do fêmur predomina em homens, enquanto que a fratura intertrocantérica\npredomina nas mulheres.","B":"A fratura do colo do fêmur é três vezes mais frequente do que a fratura intertrocantérica.","C":"A fratura do colo do fêmur preserva melhor a vascularização da cabeça femoral do que a fratura\nintertrocantérica.","D":"A fratura do colo do fêmur cursa com incidência menor de pseudartrose do que a fratura\nintertrocantérica.","E":"A fratura do colo do fêmur apresenta rotação externa menos proeminente do que a rotação da\nfratura intertrocantérica."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-269542","number":"269542","sourceNumber":"269542","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente do sexo masculino, 64 anos, vem à consulta por dor lombar tipo ?facada? que\npiora com a marcha e à evacuação, irradiando-se para a região póstero-lateral da coxa direita. Ao\nexame físico do membro inferior direito, apresenta perda de sensibilidade em região anterior da\ncoxa, perda de força muscular do quadríceps, hiporreflexia patelar e sinal de Laségue positivo.\n\nLevando em consideração a história e o exame físico, o disco intervertebral responsável pela\ncompressão da raiz nervosa se localizaria entre quais vértebras?","options":{"A":"Entre L2 e L3.","B":"Entre L3 e L4.","C":"Entre L4 e L5.","D":"Entre L5 e S1.","E":"Entre S1 e S2."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-264003","number":"264003","sourceNumber":"264003","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A epicondilite lateral de cotovelo é uma causa comum de dor em indivíduos de ambos\nos sexos, principalmente entre 40 e 60 anos de\nidade. O diagnóstico é clínico na maioria dos casos.\nNo exame físico, o paciente deverá referir dor ao realizar a seguinte manobra:","options":{"A":"flexão do punho contrarresistência.","B":"flexão passiva do punho.","C":"extensão do punho contrarresistência.","D":"pronação do antebraço contrarresistência.","E":"supinação passiva do antebraço."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-266124","number":"266124","sourceNumber":"266124","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As avaliações ambulatoriais dos ligamentos de membros inferiores são fundamentais\npara as definições dos diferentes quadros\nálgicos. Na figura abaixo, relacione as manobras\nnumeradas com os possíveis achados: ( ) Sinal da gaveta anterior positivo sugestivo da laceração\nou frouxidão do ligamento cruzado anterior. ( ) Dor ou hiato na linha articular lateral sugerindo\nlaceração parcial ou completa do ligamento colateral lateral, (estresse em varo). ( ) Dor ou hiato\nna\nlinha articular medial sugerindo laceração parcial ou completa do ligamento colateral medial\n(estresse em valgo). ( ) Movimento anterógrado significativo da tíbia, sugerindo laceração do\nligamento cruzado anterior. (BICKLEY, LS. BATES ? Propedêutica médica essencial. Avaliação\nClínica. Anamnese e Exame Físico. Sistema Músculo esquelético. Guanabara Koogan. 7a Edição\n2015.)","options":{"A":"2, 3, 4, 1","B":"3, 4, 2, 1","C":"1, 4, 2, 3","D":"3, 2, 1, 4","E":"Nenhuma das alternativas acima está correta"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/266124.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-265483","number":"265483","sourceNumber":"265483","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Nas lesões do manguito rotador qual o tendão mais frequentemente comprometido?","options":{"A":"Subescapular.","B":"Redondo menor.","C":"Bíceps braquial.","D":"Supra espinhoso.","E":"Infra espinhoso."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-284073","number":"284073","sourceNumber":"284073","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A coluna vertebral é de extrema importância nos seres vertebrados, tem a função de\ndar sustentação ao corpo e de proteção da medula espinal. Sobre a constituição da coluna\nvertebral assinale a alternativa correta:","options":{"A":"Possui 05 vértebras cervicais, 12 vértebras torácicas, 07 vértebras lombares e 03 vértebras\nsacrais.","B":"Possui 07 vértebras cervicais, 14 vértebras torácicas, 08 vértebras lombares e 04 vértebras\nsacrais.","C":"Possui 07 vértebras cervicais, 12 vértebras torácicas, 05 vértebras lombares e 05 vértebras\nsacrais.","D":"Possui 05 vértebras cervicais, 12 vértebras torácicas, 05 vértebras lombares e 05 vértebras\nsacrais."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-284074","number":"284074","sourceNumber":"284074","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Ainda sobre seus conhecimentos a respeito da coluna vertebral, marque a alternativa\ncorreta:","options":{"A":"A primeira vértebra cervical é denominada atlas.","B":"A primeira vértebra torácica é denominada áxis.","C":"A primeira vértebra lombar é denominada ampla.","D":"A primeira vértebra sacral é denominada áxon."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-284075","number":"284075","sourceNumber":"284075","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O músculo glúteo é formado por 03 camadas. Marque a alternativa que possui a\nnomenclatura correta destes músculos.","options":{"A":"Médio, mínimo e máximo.","B":"Externo, interno e médio.","C":"Menor, intermédio e maior.","D":"Pequeno, médio e grande."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-269616","number":"269616","sourceNumber":"269616","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 6 anos apresenta dor nas pernas (região pré-tibial) há 1 ano,\nprincipalmente no fim do dia, após atividades\nfísicas mais intensas. Em diversas ocasiões\napresentou despertar noturno devido às dores. A mãe, em geral, fazia massagem e, após 20\nminutos, o paciente voltava a dormir. Levando em consideração os dados apresentados, qual é o\ndiagnóstico mais provável?","options":{"A":"Osteoma osteoide.","B":"Síndrome de amplificação dolorosa.","C":"Dor musculoesquelética benigna da infância.","D":"Artrite idiopática juvenil.","E":"Púrpura de Henoch-Schönlein."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-284077","number":"284077","sourceNumber":"284077","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Qual a definição do termo pseudartrose de uma fratura?","options":{"A":"Retardo na consolidação de uma fratura.","B":"Ausência de progressão do processo de consolidação de uma fratura.","C":"Falsa articulação congênita em um indivíduo.","D":"Perda do alinhamento durante a consolidação de uma fratura."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-284081","number":"284081","sourceNumber":"284081","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O deslocamento das extremidades de um osso do seu sítio de articulação é definido\npor qual termo médico?","options":{"A":"Contusão.","B":"Fratura.","C":"Luxação.","D":"Fissura."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-261199","number":"261199","sourceNumber":"261199","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação ao exame físico da Displasia do Desenvolvimento do Quadril (DDQ),\nassinale a alternativa CORRETA:","options":{"A":"A manobra de Ortolani detecta o deslizamento posterior do quadril para fora do acetábulo, e a\nmanobra de Barlow detecta o deslizamento posterior do quadril para dentro do acetábulo.","B":"O sinal de Galeazzi é positivo se quando o quadril de um paciente que está de pé sustentado\npor somente uma perna cai para o lado da perna\nlevantada. A fraqueza é presente no lado da\nperna em contato com o chão.","C":"O sinal de Trendelenburg mostra a diferença na altura dos joelhos quando a criança está em\npronação, quadris fletidos, joelhos dobrados e pés sobre a mesa examinadora.","D":"A manobra de Barlow positiva demonstra que o quadril está reduzido, mas é deslocável,\nenquanto a manobra de Ortolani positiva\ndemonstra que o quadril está deslocado, mas é redutível."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-250999","number":"250999","sourceNumber":"250999","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As fraturas de fêmur são cada vez mais frequentes e estão relacionadas ao\nenvelhecimento populacional e à osteoporose. Sobre\nas fraturas de fêmur nos idosos, assinale a\nalternativa INCORRETA:","options":{"A":"As fraturas do colo do fêmur são comuns após os 70 anos e mais incidentes no sexo feminino.","B":"As fraturas do colo do fêmur são mais comuns que as fraturas intertrocantéricas (ou\ntranstrocantéricas).","C":"As fraturas transtrocantéricas não tratadas raramente podem evoluir com necrose e\npseudoartrose.","D":"O tratamento da fratura intertrocantérica (ou transtrocantérica) é eminentemente cirúrgico,\nestando o tratamento conservador restrito apenas\na pacientes com risco cirúrgico elevadíssimo\ne/ou em estágio terminal."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-241989","number":"241989","sourceNumber":"241989","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Entre as doenças ortopédicas atendidas em redes públicas de saúde a ?Escoliose\nIdiopática do Adolescente? tem prevalência no\nmundo de 1 a 13% em diferentes contextos. A esse\nrespeito é incorreto afirmar:","options":{"A":"Por definição tem mais de 10º no plano coronal;","B":"É a apresentação mais comum de escoliose;","C":"A rotação axial da vértebra apical é responsável pela deformidade da caixa torácica;","D":"O sinal de Adams permite o diagnóstico inicial;","E":"O tratamento conservador com colete de Milwaukee pode reverter deformidades abaixo de 25º."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-238948","number":"238948","sourceNumber":"238948","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menina, 3 anos é levada pelos pais à UPA (unidade de pronto atendimento), com dor\nno braço esquerdo, após ter sido segurada\npela mão esquerda para não sair correndo. A criança\nestá chorando e mantém o braço ao lado do corpo com a palma da mão virada para trás. Ela se\nrecusa a levantar o braço acima da cintura e não usa a mão deste lado para pegar objetos. Indique,\nrespectivamente, o diagnóstico mais provável e o tratamento indicado.","options":{"A":"Pronação dolorosa, redução.","B":"Fratura em galho verde, imobilização.","C":"Fratura do epicôndilo, imobilização.","D":"Sinovite do cotovelo, analgesia."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-238949","number":"238949","sourceNumber":"238949","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente, 16 anos, masculino, sem comorbidades, treinou futebol intensamente\ndurante 90 minutos, sem história de traumas\nou queixas durante a atividade. Após três horas,\nrelatou o início de dor na região anterolateral da perna esquerda, sem sinais flogísticos\nassociados,\ne exame neurovascular sem alterações. Foi indicado o uso de analgésicos e gelo local. Como a dor\npersistia no dia seguinte, ele procurou novamente atendimento médico, quando foi identificado\ninício de déficit motor em território do nervo fibular comum e parestesia em dorso do pé, que estava\nedemaciado, com diminuição de sensibilidade e perfusão capilar diminuída. Os pulsos tibial\nposterior e pedioso estavam palpáveis e diminuídos. Frente ao quadro clínico apresentado indique\na hipótese diagnóstica e o tratamento indicado.","options":{"A":"Contratura isquêmica de Vollkmann -fasciotomia.","B":"Síndrome Compartimental- fibulectomia.","C":"Síndrome Compartimental -fasciotomia.","D":"Contratura isquêmica de Vollkmann- fibulectomia."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-230446","number":"230446","sourceNumber":"230446","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 55 anos de idade, diabético, queixa-se de dor na região do ombro\ndireito há 3 meses. Não consegue mais realizar atividades domésticas, como passar roupas ou\ntrocar uma lâmpada no teto. A dor é contínua, inclusive durante a noite. O médico suspeita de\ncapsulite adesiva do ombro. Quanto ao achado no exame físico mais característico nesta doença,\nassinale a alternativa correta.","options":{"A":"Atrofia da musculatura do supraespinhoso e infraespinhoso.","B":"Atrofia da musculatura escapular, com elevação da mesma.","C":"Diminuição da amplitude de movimento somente ativo.","D":"Diminuição da amplitude de movimento somente passivo.","E":"Diminuição da amplitude de movimento passivo e ativo."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-231250","number":"231250","sourceNumber":"231250","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Marcos, 40 anos, se apresenta no pronto-socorro relatando ter tido uma dor no\ncalcanhar direito quando corria no campo,\ndurante jogo de futebol. Não houve contato direto com\nnenhum oponente. A história pregressa revelou que ele já vinha sentindo dor crônica nessa região.\nO médico examinou e, entre outros sinais, constatou que havia flexão ativa do tornozelo, mas não\nhavia flexão à expressão do músculo tríceps sural. Sobre isso, é possível afirmar que","options":{"A":"está descartada a lesão de tendão de Aquiles, haja vista existir flexão ativa do tornozelo.","B":"provavelmente houve uma fratura de calcâneo espontânea, tendo em vista a dor crônica no\ncalcâneo.","C":"a presença de flexão ativa não descarta lesão do tendão calcâneo (tendão de Aquiles).","D":"a rotura do tendão tibial posterior é o diagnóstico provável.","E":"a conduta mais indicada é solicitar uma ressonância magnética, a fim de diagnosticar lesão na\narticulação subtalar."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-231251","number":"231251","sourceNumber":"231251","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No joelho, o teste de Lachman positivo é patognomônico de lesão de","options":{"A":"ligamento cruzado posterior.","B":"ligamento cruzado anterior.","C":"menisco medial.","D":"menisco lateral.","E":"ligamento colateral medial."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-231252","number":"231252","sourceNumber":"231252","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Lucas, 11 anos, apresenta-se numa Unidade de Pronto Atendimento com queixa de dor\nno joelho direito há 2 dias. O médico\nexamina os membros inferiores e constata que não há\nlimitação ou dor ao exame dos joelhos, mas há limitação das rotações do quadril direito. Solicita\numa radiografia e constata que, ao traçar uma linha tangenciando a borda superior do colo do\nfêmur direito, não há o cruzamento da epífise femoral. A esse respeito, é CORRETO afirmar que","options":{"A":"o diagnóstico provável é o deslizamento da epífise femoral proximal.","B":"a conduta apropriada é solicitar uma ressonância magnética dos quadris, pois o exame\nradiográfico não é suficiente para diagnosticar essa lesão.","C":"a doença de Legg Perthes, que significa uma tumoração benigna no colo do fêmur, é o\ndiagnóstico principal a se pensar.","D":"o médico deve liberar a criança com medicamentos e encaminhar o mais rápido possível para\ntreinos de propriocepção e saltos, para favorecer a recuperação.","E":"deve-se indicar gesso inguinopédico para cicatrização de possível lesão no colo do fêmur."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-239176","number":"239176","sourceNumber":"239176","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher, 58 anos, sofreu queda da própria altura ao escorregar no piso molhado. Refere\nque já apresentava dor na coxa há 1 mês. A\nradiografia realizada no pronto-socorro mostra fratura\nde traço transverso, 2 cm abaixo do pequeno trocânter. Quais exames devem ser pedidos para o\nplanejamento cirúrgico?","options":{"A":"Cintilografia óssea, Pet Scan e Ressonância magnética.","B":"Hemograma, glicemia e dosagem de albumina.","C":"Eletroforese de proteínas, dosagem de hormônio paratireoideano (PTH) e palpação da mama.","D":"Função renal, função hepática e densitometria óssea."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-239183","number":"239183","sourceNumber":"239183","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Recém-nascido apresentou, no exame de 6 horas, sinal de Ortolani positivo para o\nquadril direito. À ultrassonografia do quadril\ndireito verificou-se, segundo método de Graaf, ângulo ?\nde 50 graus e ângulo ? de 59 graus. O tratamento recomendado é:","options":{"A":"Cruento, com osteotomiaperiacetabular.","B":"Incruento, com aparelho gessado.","C":"Incruento, com redução fechada e aparelho gessado.","D":"Incruento, com aparelho dinâmico do tipo Pavlik."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-239184","number":"239184","sourceNumber":"239184","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menina com dois anos de idade, com queixa de dor e perda de força no membro\nsuperior direito há uma hora. Mãe refere que a\ncriança ia cair e ela a segurou pelo antebraço. Ao\nexame, o antebraço se encontra em extensão e pronado. A conduta recomendada é redução:","options":{"A":"Cruenta no centro cirúrgico e fixação com fios de Kirschner.","B":"Incruenta no pronto-socorro e tala axilopalmar.","C":"Incruenta no centro cirúrgico e fixação com fios de Kirschner.","D":"Incruenta no pronto-socorro e orientações aos pais."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-217873","number":"217873","sourceNumber":"217873","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No diagnósticos da osteomielite hematógena aguda e da artrite séptica, o meio mais\nfidedigno no diagnóstico definitivo da infecção é?","options":{"A":"Hemograma completo + pcr + vhs.","B":"Ultrassonografia.","C":"Radiografia.","D":"Punção aspirativa da articulação."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-202555","number":"202555","sourceNumber":"202555","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No estudo do manguito rotador, frequentemente acometido por lesões que determinam\ndor no ombro, análises microangiográficas\nrevelam uma área hipovascular (zona crítica de\nCodman) que se localiza","options":{"A":"Na região subacromial proximal.","B":"Na região da inserção do infraespinal na pequena tuberosidade.","C":"A 3 cm proximal à inserção do supraespinal na grande tuberosidade.","D":"Imediatamente proximal à inserção do supraespinal na grande tuberosidade.","E":"Na região 2 cm proximal à inserção do infraespinal na pequena tuberosidade."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-173059","number":"173059","sourceNumber":"173059","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Lactente, 40 dias de vida, nascido de parto cesárea por apresentação pélvica,\napresenta tumoração indolor, de consistência\nendurecida, no trajeto do músculo\nesternocleidomastóideo e rotação da cabeça para o lado afetado. Em relação a esse caso, assinale\na alternativa que apresenta, corretamente, a principal hipótese diagnóstica.","options":{"A":"Duplicidade esofágica.","B":"Cisto neuroentérico.","C":"Torcicolo congênito.","D":"Adenomegalia cervical.","E":"Cisto de tireoglosso."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-178439","number":"178439","sourceNumber":"178439","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A coluna vertebral é composta por quatro regiões: cervical; dorsal; lombar e sacro\ncoccígea, cada qual, respectivamente, tem uma curva fisiológica que são:","options":{"A":"Cifose, lordose, cifose e lordose.","B":"Lordose, lordose, cifose e lordose.","C":"Cifose, cifose, lordose e cifose.","D":"Lordose, cifose, cifose e lordose.","E":"Lordose, cifose, lordose e cifose."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-178445","number":"178445","sourceNumber":"178445","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A fratura de radio distal é uma da sfraturas mais frequentes no adulto e de acordo com\nisto, assinale a única alternativa correta:","options":{"A":"As fraturas são classificadas de acordo com o acometimento exclusivamente do rádio e não leva\nem consideração a ulna","B":"As fraturas de rádio são comuns, não sendo complexas e portanto, com baixo índice de\ncomplicações","C":"As fraturas podem ser fixadas internamente com placa e parafusos ou através de pinagem","D":"Os fixadores externos não são indicados para as fraturas de terço distal de radio","E":"A distrofia simpático reflexa (Sudeck) não deve ser tratada durante a fase de imobilização com\ngesso."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-178449","number":"178449","sourceNumber":"178449","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As fraturas expostas são consideradas emergências dentro da Ortopedia e\nTraumatologia. Assinale a única alternativa correta abaixo:","options":{"A":"Na classificação de Gustillo-Anderson, leva-se em consideração a lesão de partes moles para o\ntipo de abordagem cirúrgica","B":"Nas fraturas expostas grau II de Gustillo-Anderson não se deve fazer a fixação interna devido às\nlesões de partes moles","C":"A antibioticoterapia somente será instituída após o resultado da cultura e antibiograma, pelo\nrisco de aumento de resistência bacteriana","D":"Devido a alta possibilidade de infecção, deve ser instituído antibioticoterapia de amplo espectro\nem toas as fraturas expostas","E":"A haste intramedular é totalmente contraindicada nas fraturas expostas"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183361","number":"183361","sourceNumber":"183361","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As complicações imediatas das fraturas acetabulares são, EXCETO:","options":{"A":"infecção","B":"lesão nervosa","C":"tromboembolismo","D":"pseudo-artrose"},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183379","number":"183379","sourceNumber":"183379","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na fratura de Bennett, a base do metacarpo é puxada dorsalmente e radialmente pelo:","options":{"A":"Abdutor longo do polegar","B":"Flexor curto do polegar","C":"Adutor do polegar","D":"Oponente do polegar"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-183434","number":"183434","sourceNumber":"183434","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um adolescente, com 14 anos de idade, é trazido à consulta médica em Unidade\nBásica de Saúde com queixa de dor de\nintensidade leve na virilha esquerda, iniciada há duas\nsemanas, com piora progressiva. O paciente relata que a dor irradia pela face interna da coxa até o\njoelho, e que agora apresenta dificuldade para caminhar. Nega febre ou traumatismo local. O\nexame físico evidencia: peso = 68 kg, altura = 1,62 m. Não é evidenciado edema, calor ou rubor no\nlocal. Verifica-se limitação da mobilidade da articulação coxofemoral esquerda em decúbito dorsal.\nNesse caso, a conduta indicada é:","options":{"A":"solicitar hemograma, fator reumatoide e pesquisa de anticorpos antinucleares.","B":"encaminhar o paciente com urgência para avaliação de ortopedista/traumotologista.","C":"prescrever analgésico ou anti-inflamatório via oral e solicitar retorno do paciente em 48 horas.","D":"solicitar ultrassonografia da articulação coxofemoral esquerda e retorno do paciente em 24\nhoras."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-173134","number":"173134","sourceNumber":"173134","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente informa que há 4 meses apresenta dormência em região hipotenar e em\ndedos da face medial de mão. O músculo I\ninterósseo dorsal da mão está hipotrofiado e há redução\nda força na adução de punho. A oponência está preservada. Considerando a descrição do\nacometimento, assinale a alternativa correta.","options":{"A":"O quadro é compatível com lesão do nervo mediano no punho.","B":"O quadro é compatível com lesão do nervo ulnar no cotovelo.","C":"O quadro é compatível com lesão do nervo mediano no cotovelo.","D":"O quadro é compatível com lesão do nervo radial no cotovelo.","E":"O quadro é compatível com lesão do nervo ulnar no punho."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-173846","number":"173846","sourceNumber":"173846","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança do sexo masculino, 06 anos de idade, é trazida à emergência pelos pais que\nrelatam o menor ter caído da árvore com o cotovelo estendido. A radiografia do cotovelo mostra\numa fratura supracondiliana umeral sem contatoentre os fragmentos ósseos. Assinale a alternativa\nCORRETA.","options":{"A":"A respeito desse tipo de fratura, pode-se dizer que, quando ocorre paralisia nervosa, o nervo\nmais frequentemente acometido é o nervo ulnar.","B":"Na radiografia do cotovelo de uma criança de 06 anos de idade, espera-se visualizar os centros\nde ossificação secundárias da troclea e do\nolecrano.","C":"Se a fratura do tipo relatado, apresentasse contato entre os fragmentos na radiografia, seria\nmaior a probabilidade de lesão nervosa e vascular.","D":"O tipo de desvio mais comum da fratura relatada é o desvio anterior do fragmento distal, visível\nna incidência lateral(perfil) da radiografia.","E":"No caso de diminuição do pulso da artéria radial, porém com a palma da mão e dos dedos\nrósea, a conduta imediata deverá ser a\nredução e a fixação da fratura."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-179014","number":"179014","sourceNumber":"179014","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 14 anos com história de trauma em membro inferior direito há 4 meses.\nHá 30 dias dor lancinante e aumento de\nvolume em terço distal de coxa D ( próximo ao joelho).\n\nNega febre. Ao exame, aumento de volume e discreta hiperemia local. RX da lesão apresenta\nimagem ?em raio de sol?, com elevação do periósteo (triângulo de Codman). Diagnóstico do\npaciente em questão: (Tratado de Pediatria SBP, 2ª Ed., pág:1817)","options":{"A":"Osteossarcoma","B":"Osteomielite","C":"Sarcoma de Ewing","D":"Fratura patológica","E":"Cisto de Baker"},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-153144","number":"153144","sourceNumber":"153144","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"\"Quando um osso apresenta colapso através de uma área enfraquecida por uma\ndoença preexistente, a lesão recebe o nome de\nfratura patológica.\" Sobre as fraturas patológicas, é\nCORRETO afirmar que:","options":{"A":"As causas podem incluir tumores primários do osso, lesões metastáticas, infecção e doenças\nmetabólicas.","B":"Os termos fratura por enfraquecimento ou \"por insuficiência\" não são sinônimos de fraturas\npatológicas.","C":"As fraturas patológicas normalmente decorrem de traumas de alta energia que atigem a\nestrutura óssea.","D":"Paciente com densitometria óssea com indicativo de osteoporose tem menor risco para fratura\npatológica.","E":"A fratura de rádio distal sem cominuição em um paciente com osteoporose não é considerada\npatológica."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-159841","number":"159841","sourceNumber":"159841","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Anasem 2016 - Uma criança, ao sofrer queda de skate, apoiou os membros superiores\npara absorção do impacto. Após avaliação médica,\nconstatou-se fratura-luxação no terço proximal\nda ulna direita. No caso descrito, há maior risco de lesão no nervo.","options":{"A":"Radial.","B":"Mediano.","C":"Musculocutâneo.","D":"Interósseo posterior."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-153963","number":"153963","sourceNumber":"153963","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Das alternativas abaixo, assinale a CORRETA com relação a epidemiologia das\nfraturas:","options":{"A":"A fratura de Colles ocorre no adulto jovem devido a exposição profissional","B":"A fratura de clavícula ocorre mais frequentemente em seu terço proximal","C":"A fratura de escaloide ocorre com mais frequência no idoso","D":"A fratura de calcâneio ocorre maus frequentemente em mulheres","E":"A fratura em galho verde ocorre nas crianças de baixa idade"},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-153966","number":"153966","sourceNumber":"153966","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Das afirmações abaixo, assinale a única alternativa CORRETA:","options":{"A":"A luxação escapulo umeral posterior é a mais frequente em ocorrência dentre as luxações de\nombro","B":"O sinal da tecla de piano está presente nas luxações escapulo-umerais.","C":"O sinal da dragona positivo é indicativo de luxação escapulo-umeral","D":"A manobra de apreensão está negativa imediatamente após a luxação de ombro","E":"A luxação voluntária realizada pelo pacinte é uma indicação absoluta de correção cirurgica"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150024","number":"150024","sourceNumber":"150024","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No compartimento medial do joelho, o ligamento colateral medial, ou colateral tibial, se\ndestaca. Ele é uma das principais estruturas lesadas. O seu mecanismo de lesão mais comum é:","options":{"A":"Hiperextensão do joelho.","B":"Trauma direto.","C":"rotação interna do joelho.","D":"Estresse em valgo.","E":"Trauma com a tíbia em extensão."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-150032","number":"150032","sourceNumber":"150032","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No teste semiológico do joelho, a manobra de McMurrey é executada com o paciente\nem decúbito ventral, quadril fletido a 40 graus\ne joelho flexionado. O examinador coloca uma das\nmãos sobre a linha articular do joelho e, ao mesmo tempo, segura o pé com a outra mão. Quando o\npé e a tíbia são rodados externamente (lateralmente), a estrutura que está sendo testada é o:","options":{"A":"Ligamento cruzado anterior.","B":"Ligamento colateral medial.","C":"Ligamento colateral lateral.","D":"Menisco lateral.","E":"Menisco medial."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-153709","number":"153709","sourceNumber":"153709","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O ligamento talofibular anterior localiza-se na região:","options":{"A":"Lateral do tornozelo.","B":"Medial do pé.","C":"Dorso-medial do pé.","D":"Posterior do tornozelo.","E":"Entre a tíbia e a fíbula, na região anterior."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-153696","number":"153696","sourceNumber":"153696","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A classificação de SALTER-HARRIS que compromete a metáfise, atravessando a fise e\na epífise, até a articulação, corresponde ao\ntipo:","options":{"A":"I.","B":"II.","C":"III.","D":"IV.","E":"V."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-153225","number":"153225","sourceNumber":"153225","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A displasia do desenvolvimento do quadril é uma doença de grande espectro de\napresentação, devendo ser avaliada no primeiro exame físico do recém-nascido. É muito\nimportante que se realizem, ainda na maternidade, as amplamente conhecidas manobras que\ntestam a instabilidade, devendo ser rotineiramente pesquisadas em todos os recém-nascidos. A\netiologia é desconhecida; no entanto, vários fatores de risco pré e pós-natais podem estar\nimplicados nessa doença. Entre eles, podemos citar:","options":{"A":"Polidrâmnio.","B":"Multigestação.","C":"Apresentação transversa.","D":"Sexo masculino.","E":"Hiperelasticidade ligamentar."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-149458","number":"149458","sourceNumber":"149458","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Sobre a Síndrome do Túnel do Tarso, considere as afirmativas a seguir. I. O nervo\nacometido é o nervo tibial posterior em\nregião maleolar medial. Há dor local, dormência e\nqueimação em região plantar.; II. O nervo acometido é o nervo tibial anterior no tornozelo. Há dor\nlocal, dormência e queimação em face anterior do tornozelo e dorso do pé.; III. É a mononeuropatia\nmais comum nos membros inferiores.; IV. Na avaliação semiológica, é possível evocar o sinal de\nTinel. Assinale a alternativa correta.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-126215","number":"126215","sourceNumber":"126215","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Das estruturas da região medial do joelho, o ligamento colateral medial, também\nchamado de colateral tibial, é a estrutura ligamentar dominante. Sua origem é:","options":{"A":"No tubérculo dos adutores.","B":"No polo inferior da patela.","C":"No sulco do poplíteo.","D":"No epicôndilo medial.","E":"Na fóvea interóssea."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-126222","number":"126222","sourceNumber":"126222","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O ligamento cruzado anterior é uma lesão traumática comum do joelho. O teste\nsemiológico de Lachman é uma das opções para o\nseu diagnóstico. Ele deve ser realizado com o\npaciente:","options":{"A":"em pé, com o joelho em rotação externa.","B":"em decúbito dorsal, com o joelho em 30 graus de flexão.","C":"em decúbito lateral, com o joelho em extensão.","D":"em decúbito ventral, com o joelho há 90 graus de flexão.","E":"em posição pudica, com o joelho na posição de conforto para o paciente."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-131037","number":"131037","sourceNumber":"131037","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Baseando no aspecto anatômico e fisiológico do osso, assinale a alternativa correta:","options":{"A":"Os ossos imaturos não possuem a cartilagem de crescimento formando as fises ou placas de\ncrescimento.","B":"As placas de crescimento possuem uma estrutura simples, sem estratificação de camadas.","C":"A zona de calcificação óssea é a mais próxima da zona de repouso ou de reserva.","D":"O crescimento ósseo ocorre somente por hipertrofia das células, não necessitando orientação\nem colunas.","E":"As placas de crescimento orientam o crescimento logintudinal do osso."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-131010","number":"131010","sourceNumber":"131010","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As fraturas de clavícula são comuns em jovens, principalmente naqueles que participam\nde atividades esportivas. Assinale a alternativa\ncorreta:","options":{"A":"80 a 85% das fraturas ocorrem na diáfise média da clavícula devido às forças compressivas\ntípicas, aplicadas ao ombro.","B":"As fraturas de terço médio tem pior prognóstico na maioria dos casos.","C":"A pseudartrose de clavícula nas fraturas de seu terço médio são muito frequentes.","D":"O tratamento conservador nas fraturas do terço médio tem resultado satisfatório na maioria dos\ncasos.","E":"Nunca se indica o tratamento cirúrgico nas fraturas de clavícula, em seus diversos segmentos."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-131077","number":"131077","sourceNumber":"131077","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O politraumatizado deve ser avaliado no setor de emergência do hospital e estabilizado\nde acordo com o protocolo ATLS. Assinale a\nalternativa que indica o atendimento preconizado nos\ncasos de fratura expostas:","options":{"A":"As radiografias são obtidas somente dentro do centro cirúrgico, pois a priorização da abordagem\ncirúrgica deve ser imediata.","B":"As fraturas expostas tipo I de Gustilo-Anderson são as que apresentam moderado dano\ntecidual, com lesões de pele acima de 10 cm.","C":"As fraturas expostas do tipo III de Gustilo-Anderson podem exigir desbridamento amplo e\nnecessidade de cobertura cutânea.","D":"As fraturas expostas do tipo I Gustilo-Anderson sempre necessitam fixação externa imediata.","E":"As fraturas expostas do tipo II de Gustilo-Anderson apresentam menor grau de contaminação\ndentro da classificação."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-130360","number":"130360","sourceNumber":"130360","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Mulher de 34 anos, violinista da orquestra sinfônica, apresenta, há três meses, dor no\nmembro superior esquerdo, localizada na face interna do braço e irradiada até a mão. Notou que,\nhá três semanas, durante uma turnê de inverno, apresentou alterações na coloração nos dedos da\nmão esquerda, que tornaram-se pálidos, cianóticos e avermelhados. O diagnóstico mais compatível\né:","options":{"A":"Síndrome do desfiladeiro cervicotorácico, com compressão de C5 e C6.","B":"Síndrome do desfiladeiro cervicotorácico, com compressão de C8 e T1.","C":"Síndrome do desfiladeiro cervicotorácico, com compressão de C6 e C7.","D":"Síndrome do desfiladeiro cervicotorácico, com compressão pelo músculo axilopeitoral.","E":"Síndrome da arcada de Langer, com compressão da artéria subclávia."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-130379","number":"130379","sourceNumber":"130379","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O músculo do manguito rotador que realiza rotação interna do ombro é o:","options":{"A":"Redondo menor.","B":"Redondo maior.","C":"Supraespinhoso.","D":"Subescapular.","E":"Infraespinhoso."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-126394","number":"126394","sourceNumber":"126394","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 58 anos, empregado em uma madeireira há 06 meses, procura Unidade de\nSaúde com queixa de dor ao mobilizar o\nbraço direito. Refere importante limitação de suas\natividades, com dificuldade para elevar o braço, porém, sem perda de força do membro acometido.\nAo exame físico, dor no teste de Apley e nas manobras de avaliação de síndrome do impacto (Neer\ne Hawkins), amplitude de movimentos preservada à mobilização passiva e força preservada no\nteste contra a resistência. Com os dados de história e exame físico, o médico suspeita tratar-se de\num caso de:","options":{"A":"Capsulite adesiva.","B":"Luxação da articulação acromioclavicular.","C":"Tendinopatia do manguito rotador.","D":"Osteoartrite da articulação acromioclavicular.","E":"Ruptura de estruturas do manguito rotator."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-128901","number":"128901","sourceNumber":"128901","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Escolar de seis anos, sexo masculino, é levado a consulta devido a quadro de\nclaudicação. Mãe relata que seu filho\napresentou episódio de resfriado há 10 dias e que não notou\nnenhuma outra anormalidade. Exame físico: afebril, bom estado geral, dor e limitação de\nmovimentos do quadril direito. A hipótese diagnóstica mais provável é","options":{"A":"Doença de Legg-Calvé-Perthes.","B":"Artrite reumatoide juvenil.","C":"Epifisiólise do quadril.","D":"Sinovite transitória.","E":"Artrite séptica."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-102779","number":"102779","sourceNumber":"102779","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"O osteossarcoma clássico é o tumor maligno de alto grau intramedular primário no qual\ncélulas neoplásicas produzem osteóide mesmo que em pequenas quantidades. Sobre o\nOsteossarcoma é correto afirmar:","options":{"A":"O Osteossarcoma é uma neoplasia de alto grau de agressividade e ocorre mais frequentemente\nna primeira década de vida.","B":"Acomete o esqueleto axial e apresenta pior prognóstico quando ocorre na região metafisária de\nossos longos.","C":"O quadro clínico é caracterizado por uma massa palpável e indolor de crescimento rápido no\nlocal de acometimento.","D":"O triângulo de Codmann é uma imagem formada pelo levantamento periosteal abrupto\ninterrompido pelo crescimento rápido do tumor.","E":"O tratamento do osteossarcoma clássico consiste, nesta ordem, em cirurgia, quimioterapia\nadjuvante e radioterapia."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-102794","number":"102794","sourceNumber":"102794","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Fratura exposta refere-se a um amplo espectro de lesões desde a perfuração da pele\nem uma fratura oblíqua longa até esmagamento\ndo membro com uma fratura segmentar. Sobre as\nfratura expostas é correto afirmar:","options":{"A":"No atendimento pré-hospitalar de uma fratura exposta está contra indicado o fechamento da\nferida com curativo estéril até avaliação especializada.","B":"Para o tratamento das fraturas expostas puntiformes está indicado o uso de antibioticoterapia\nem esquema tríplice.","C":"O Staphilococcus Epidermidis é o principal germe causador de infecção primária e secundária\nnas fraturas expostas.","D":"A irrigação com soro fisiológico de uma fratura exposta deve ser evitada devido ao risco de\nembolia gordurosa.","E":"A contaminação bacteriana é o fator diferencial mais claro e importante e o que também\ndetermina a definição de fratura exposta."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-101439","number":"101439","sourceNumber":"101439","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente do sexo masculino, 25 anos de idade, sofreu queda com a mão espalmada\ndurante jogo de futebol (Figura 1).\nRadiografia do seu punho na incidência anteroposterior foi\nrealizada no pronto-socorro (Figura 2). (VER IMAGENS). Com base nessas informações, assinale a\nalternativa correta.","options":{"A":"A incidência radiográfica ideal deve ser realizada com desvio ulnar do punho.","B":"Dor na tabaqueira anatômica e pistonagem positiva sugerem tenossinovite.","C":"O diagnóstico da fratura é precoce e as complicações são pouco frequentes.","D":"Quando ocorre no 1/3 distal, necrose asséptica e pseudoartrose são esperadas.","E":"Ressonância magnética é rotineira para avaliar a vascularização desse osso."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/101439.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-101372","number":"101372","sourceNumber":"101372","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Observe as figuras a seguir. Fraturas do 1/3 distal do rádio em crianças são frequentes.\nConsiderando a classificação de Salter-Harris (Figura 1) e a radiografia do punho nas incidências\nanteroposterior e perfil (Figura 2), assinale a alternativa correta. (VER IMAGENS)","options":{"A":"Nos tipos I, II e V (Figura 1), o tratamento, em geral, é conservador.","B":"Fixação com parafuso transfisário é a escolha para o tipo III (Figura 1).","C":"No tipo IV (Figura 1), a formação de barra óssea é pouco frequente.","D":"O tipo V (Figura 1) é diagnosticado precocemente por radiografia.","E":"A Figura 2 ilustra caso que necessita tratamento cirúrgico."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":["question_bank/media/medcurso/medcurso-ortopedia-ort-unico/101372.png"],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-101116","number":"101116","sourceNumber":"101116","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 45 anos, mecânico, apresenta quadro de 3 meses de evolução de\ndor em face posterior de antebraço direito,\nque aumenta com esforços e movimentos de pronação e\nsupinação. Ao exame, a sensibilidade é normal, mas o paciente apresenta dificuldade para\nextensão dos dedos. O quadro descrito é compatível com qual dos diagnósticos abaixo?","options":{"A":"Síndrome do túnel ulnar.","B":"Síndrome do túnel do carpo.","C":"Síndrome do músculo pronador.","D":"Compressão externa do nervo interósseo anterior.","E":"Síndrome do músculo supinador."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-101120","number":"101120","sourceNumber":"101120","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"No diagnóstico das lesões ósseas, um fator importante é sua localização no osso. Qual\ndas alternativas abaixo apresenta lesões que, caracteristicamente, se localizam na epífise de ossos\nlongos?","options":{"A":"Osteoma osteoide e cisto ósseo simples.","B":"Condroblastoma e tumor de células gigantes.","C":"Fibroma não ossificante e osteocondroma.","D":"Cisto ósseo aneurismático e osteoma.","E":"Tumor de células gigantes e cisto ósseo simples."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-101087","number":"101087","sourceNumber":"101087","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação aos hemangiomas vertebrais, é correto afirmar que:","options":{"A":"são tumores raros.","B":"são tumores malignos.","C":"são frequentemente sintomáticos.","D":"são radiossensíveis.","E":"são tratados preferencialmente com quimioterápicos."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-102820","number":"102820","sourceNumber":"102820","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 44 anos, masculino, trabalhador da construção civil, comparece em\nconsulta na Unidade de Saúde com quadro de\ndor em ombro direito há mais de 01 ano com piora\nnos últimos meses associada à perda de força, após intensificação de carga de trabalho. Nega\ntrauma no local da dor. Ao exame físico, apresenta região subacromial dolorosa, dor no teste de\nApley, amplitude preservada à mobilização passiva, notável redução de força e dor nas manobras\nde avaliação de síndrome do impacto (Neer e Hawkins). De acordo com a sintomatologia do\npaciente e o exame físico, o médico suspeita de:","options":{"A":"Ruptura de estruturas do manguito rotador.","B":"Tendinopatia do manguito rotador.","C":"Osteoartrite da articulação glenoumeral.","D":"Tendinite da cabeça longa do bíceps.","E":"Ruptura de tendões do bíceps."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-103463","number":"103463","sourceNumber":"103463","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Adolescente de 14 anos de idade, praticante regular de esporte, apresentou quadro de\ndor e saliência na tuberosidade anterior da tíbia após atividade física. Qual é o diagnóstico mais\nprovável?","options":{"A":"Cisto de Baker.","B":"Osteomielite hematogênica aguda.","C":"Doença de Osgood-Schlatter.","D":"Rotura de ligamento cruzado anterior.","E":"Artrite séptica."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-103571","number":"103571","sourceNumber":"103571","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente vítima de colisão entre moto e automóvel dá entrada na sala de emergência\ntrazido pelo serviço de emergência com história\nde TCE leve e contusão em joelho direito. Ele\napresenta laceração no joelho direito, sangramento local e ausência de pulso na artéria pediosa\ndireita. A radiografia de joelho evidencia uma fratura condilar femoral. Neste caso, a lesão\nvascular\nmais provável é:","options":{"A":"lesão da artéria tibial anterior.","B":"lesão da artéria femoral supercial.","C":"lesão da artéria poplítea direita.","D":"lesão da artéria fibular.","E":"lesão da artéria femoral profunda."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-103537","number":"103537","sourceNumber":"103537","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 5 anos deu entrada no pronto-socorro com o membro superior\naparentemente paralisado (pseudoparalisia) após ter\nsido puxada pela mão. A radiografia de\nantebraço e cotovelo não evidencia alterações. Neste caso, o diagnóstico mais provável é:","options":{"A":"fratura de escafoide.","B":"subluxacão da cabeça do rádio.","C":"luxação escapuloumeral.","D":"fratura de Monteggia.","E":"fratura do piramidal."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-80531","number":"80531","sourceNumber":"80531","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"\"Fratura é uma ruptura na arquitetura normal do osso. Nas lesões pediátricas, as\nfraturas podem incluir uma lesão localizada na\nplaca cartilaginosa de crescimento ou uma lesão\natravés desta placa que pode não ser evidente radiologicamente\". Sobre os tipos de fratura é\ncorreto afirmar:","options":{"A":"As fraturas agudas apresentam bordas arredondadas e escleróticas devido ao hematoma que se\norganiza.","B":"As fraturas que atingem a cartilagem de crescimento são chamadas de articulares.","C":"As fraturas transversas e oblíquas ocorrem quando um momento de arqueamento é aplicado.","D":"As fraturas intra-articulares com desvio precisam de estabilidade e fixação relativa.","E":"As fraturas por estresse são causadas por forças de distração associadas a cisalhamento."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-80529","number":"80529","sourceNumber":"80529","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"\"A obtenção de uma história clínica detalhada é essencial em pacientes com lesões no\nsistema do músculo esquelético para facilitar o diagnóstico e tratamento precisos\". A respeito da\ncorrelação entre o mecanismo do trauma e as lesões comumente associadas, é correto afirmar:","options":{"A":"A queda de altura produz um trauma axial ocasionando frequentemente fratura de calcâneo,\npodendo esta ser bilateral.","B":"Paciente vítima de acidente de veículo automotivo com colisão de frente é comum encontrar\nfratura pélvica do tipo compressão lateral.","C":"Em paciente vítima de trauma direito em região anterior do joelho, com luxação posterior deste,\né comum encontrar lesão da artéria Genicular.","D":"Paciente vítima de trauma em abdução do braço com luxação anterior do ombro é comum\nencontrar lesão do nervo radial tipo neurotimese.","E":"Em paciente vítima de acidente com veículo automotivo com luxação posterior do quadril é\ncomum encontrar lesão do nervo femoral."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-80525","number":"80525","sourceNumber":"80525","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É essencial que o tratamento médico inicial faça uma completa avaliação e dê início\naos procedimentos de emergência, incluindo\nimobilizações e tratamento dos ferimentos. Sobre o\ntratamento das lesões musculoesqueléticas, é CORRETO afirmar que:","options":{"A":"Todos os curativos estéreis devem ser removidos para a realização das radiografias iniciais.","B":"As luxações devem ser reduzidas utilizando manobras contrárias à deformidade inicial.","C":"A tração com imobilização provisória deve ser evitada devido ao risco de síndrome\ncompartimental.","D":"As lesões do anel pélvico são ocultas e em sua maioria não estão associadas a outras lesões do\nsistema musculoesquelético.","E":"As articulações acima e abaixo da fratura de um osso longo devem ser radiografadas para um\nmaior controle pós-redução."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-77966","number":"77966","sourceNumber":"77966","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As manobras ou testes de Barlow e Ortolani são importantes para o diagnóstico da\nDisplasia de Desenvolvimento do Quadril (DDQ). Qual das afirmativas abaixo sobre essas\nmanobras ou testes é a correta?","options":{"A":"O teste de Ortolani detecta quadris instáveis (que se luxam), enquanto o de Barlow os quadris\nque apresentam displasia acetabular sem\ninstabilidade franca.","B":"Cerca de 60% dos quadris de recém-nascidos com teste de Barlow positivo se estabilizam\nnaturalmente na primeira semana de vida.","C":"A normalidade de ambas as manobras afasta totalmente o diagnóstico de DDQ.","D":"O teste de Ortolani deve ser realizado com o quadril em flexão de 90 graus e o joelho em\nextensão completa.","E":"O teste de Barlow é realizado com o quadril em extensão e forçando a adução do quadril para\ntentar a luxação superior da cabeça do fêmur."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-81811","number":"81811","sourceNumber":"81811","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente masculino, 50 anos, vítima de queda de nível (2 metros), dá entrada no\npronto-socorro com história de trauma direto em braço direito. Ao exame físico apresenta\ndificuldade de extensão do polegar direito e aumento de volume em terço distal de braço direito.\nSubmetido à radiografia de úmero que evidenciou fratura em espiral entre terço médio e distal de\número direito. De acordo com o caso acima assinale a principal hipótese diagnóstica e qual o\nmelhor tratamento para o paciente acima.","options":{"A":"Lesão de nervo radial e tratamento cirúrgico da fraura do úmero com exploração do nervo","B":"Lesão de nervo mediano e tratamento cirúrgico da fratura do úmero com exploração do nervo","C":"Lesão de nervo radial e tratamento conservador (apenas imobilização incruenta da fratura)","D":"Lesão do nervo ulnar e tratamento cirúrgico da fratura do úmero com exploração do nervo","E":"Lesão de nervo mediano e tratamento conservador (apenas imobilização incruenta da fratura)"},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-79498","number":"79498","sourceNumber":"79498","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente de 13 anos de idade, sexo masculino, queixa-se de dor em região anterior do\njoelho direito. Ele pratica handebol 3 vezes por semana. A radiografia do joelho mostra um ossículo\nna inserção do ligamento patelar junto à tuberosidade anterior da tíbia. A hipótese diagnóstica mais\nprovável é:","options":{"A":"Doença de Sever.","B":"Doença de Osgood-Schalatter.","C":"Dor do crescimento.","D":"Doença de Legg-Calvé-Perthes.","E":"Cisto de Baker."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-78848","number":"78848","sourceNumber":"78848","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Homem de 80 anos de idade, tabagista, com diagnóstico prévio de artrose, sofreu\nqueda da própria altura há 5 horas, impedindo\na sua deambulação. O exame físico revela\nencurtamento de 2 cm do membro inferior direito e postura em rotação externa do membro. O\ndiagnóstico e as respectivas condutas diagnóstica e terapêutica serão:","options":{"A":"Fratura transtrocanteriana, radiografia de quadril, prótese parcial de quadril.","B":"Fratura de colo de fêmur, tomografia de quadril, fixação com parafusos canulados.","C":"Fratura de colo de fêmur, radiografia de quadril, prótese total de quadril.","D":"Fratura de colo de fêmur, radigrafia de quadril, tração transesquelética e repouso no leito.","E":"Fratura de acetábulo, tomografia de pelve, tração transesquelética."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-79454","number":"79454","sourceNumber":"79454","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menina de 2 anos e 6 meses foi levada ao pronto atendimento com dor no braço direito\napós ter sido levantada pelos antebraços durante brincadeira (um adulto girou segurando-a pelas\nmãos). Estava com o antebraço fletido, apoiava a mão direita no abdome e não queria que\nninguém mexesse no membro afetado. O provável diagnóstico foi:","options":{"A":"Sinovite transitória do cotovelo.","B":"Hiperelasticidade articular.","C":"Fratura em ?galho verde?.","D":"Fratura de epicôndilo.","E":"Pronação dolorosa."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-62995","number":"62995","sourceNumber":"62995","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"É causa de fratura do colo femoral em idosos:","options":{"A":"Déficit cognitivo.","B":"Paciente institucionalizado.","C":"Comorbidades graves.","D":"Osteoporose.","E":"Nenhuma das alternativas anteriores está correta."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-58560","number":"58560","sourceNumber":"58560","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"As fraturas abertas representam emergências cirúrgicas porque a longo prazo põe em\nrisco o membro e, em casos de sepse sistêmica, são potencialmente fatais. Sobre as fraturas\nexpostas é correto afirmar:","options":{"A":"O uso de antibióticos e a profilaxia do tétano devem sem realizadas na sala de emergência para\nqualquer fratura aberta.","B":"Nos casos de suspeita de contaminação pelo solo, apenas lavar com iodopolvidine para evitar\ninfecção por Clostridium.","C":"Realizar ampliação dos ferimentos para desbridamente e lavagem seguida de fechamento para\nevitar infecção nosocomial.","D":"O tratamento com aparelho gessado é o preconizado pelo fato de não representar agressão aos\ntecidos moles.","E":"A irrigação abundante da ferida operatória com solução salina 0,9% causa embolia gordurosa e\ndeve ser evitada."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-71650","number":"71650","sourceNumber":"71650","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Criança com dois anos de idade, atendida no pronto-socorro com quadro de dor e\nperda de força no membro superior direito há\n1 hora. Mãe refere que a criança ia cair e ela a\nsegurou pelo antebraço. Ao exame, o antebraço se encontra em extensão e pronado. A conduta\nrecomendada é redução:","options":{"A":"Cruenta e fixação com placa.","B":"Incruenta no centro cirúrgico e fixação com fios de Kirschner.","C":"Cruenta no centro cirúrgico e fixação com fios de Kirschner.","D":"Incruenta no pronto-socorro e orientações aos pais."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-58769","number":"58769","sourceNumber":"58769","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menino, 10 anos de idade, apresenta queixa de 3 meses de dor em coxa e joelho\nesquerdo, queda do estado geral e perda de\npeso. Ao exame clínico, há aumento de volume\ndoloroso em terço distal de coxa, claudicação e limitação de mobilidade do joelho. Os exames de\nimagem mostram lesão lítica/permeativa metafiso-diafisária de fêmur, sem limites precisos, com\nreação periosteal, erosão de cortical e invasão de partes moles. A análise histológica de biópsia\ncirúrgica óssea mostra padrão uniforme de células pequenas, redondas, com núcleos arredondados\ne pouco estroma. Qual dos diagnósticos abaixo é o mais provável para essa situação?","options":{"A":"Sarcoma de Ewing.","B":"Osteomielite crônica.","C":"Tumor de células gigantes.","D":"Osteossarcoma.","E":"Condrossarcoma."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-58777","number":"58777","sourceNumber":"58777","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Paciente com 38 anos apresenta dor crônica em face posterior de antebraço direito,\ndiminuição de força de extensão dos dedos, mas sem alteração de sensibilidade. Sendo indicado\ntratamento cirúrgico, qual dos procedimentos abaixo seria o mais compatível com o quadro\napresentado?","options":{"A":"Liberação do túnel do carpo.","B":"Descompressão do túnel do supinador.","C":"Descompressão do nervo ulnar no cotovelo.","D":"Neurólise total do plexo braquial.","E":"Liberação do nervo mediano na inserção do bíceps."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-59117","number":"59117","sourceNumber":"59117","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Nos acidentes que envolvem as mãos, é frequente a ocorrência de fratura dos\nmetacarpianos. Sobre esse assunto, assinale a alternativa CORRETA.","options":{"A":"A maioria das fraturas dos metacarpianos é tratada conservadoramente.","B":"A tomografia computadorizada é o padrão-ouro para controle após redução.","C":"Desvio rotacional de até 10 graus pode ser aceito como resultado final.","D":"O terceiro metacarpiano é o que admite maior desvio angular.","E":"O quinto metacarpiano é o que mais comumente sofre fratura em sua cabeça."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-71633","number":"71633","sourceNumber":"71633","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Menino, 11 anos, portador de deficiência idiopática de hormônio de crescimento (GH),\nrepondo este hormônio há 8 meses. Refere dor em joelho esquerdo e leve claudicação, sem febre.\nExame físico: ausência de sinais flogísticos articulares, com dor à abdução do quadril esquerdo. A\nhipótese diagnóstica é:","options":{"A":"Doença de Legg-Calvé-Perthes.","B":"Doença de Osgood-Schlatter.","C":"Sinovite transitória do quadril.","D":"Epifisiolistese da cabeça do fêmur."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-61359","number":"61359","sourceNumber":"61359","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"A displasia do desenvolvimento do quadril, nova denominação para a antiga luxação\ncongênita de quadril, tem como melhor diagnóstico em recém-nascido o estudo de imagem:","options":{"A":"Radiografia de quadril em posição de rã.","B":"Tomografia de quadril.","C":"Cintilografia de quadril.","D":"Ultrassonografia de quadril.","E":"Nenhuma das alternativas."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-57160","number":"57160","sourceNumber":"57160","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Nas lesões traumáticas do anel pélvico:","options":{"A":"O fixador externo isoladamente é o tratamento definitivo para as instabilidades verticais.","B":"Nas lesões em alça de balde, o fixador externo não pode ser utilizado isoladamente para o\ntratamento desta lesão.","C":"O fixador externo só consegue estabilizar mecanicamente os casos de instabilidade rotacional\nquando existe integridade dos ligamentos sacroilíacos posteriores.","D":"O sinal de Destot indica lesão dos ligamentos sacroilíacos posteriores.","E":"A incidência radiográfica em outíet serve para identificar principalmente a instabilidade\nrotacional."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-57156","number":"57156","sourceNumber":"57156","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Em relação às lesões traumáticas do pé:","options":{"A":"A fratura-luxação de Lisfranc ocorre entre os ossos do tarso.","B":"Na classificação de Stephens e Sanders para artrose pós-traumática, o tipo III está associado à\ndeformidade em varo.","C":"A classificação de Sanders e Gregory para fraturas do calcâneo utiliza o corte sagital da\ntomografia.","D":"Na incidência de Broden, a perna é posicionada em rotação externa em quarenta graus com o\ntornozelo neutro.","E":"Nas flictenas hemorrágicas o índice de infecção é menor."},"answer":"B","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-44075","number":"44075","sourceNumber":"44075","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Acidentes envolvendo motociclistas caracterizam um sério problema de saúde pública\nnos centros urbanos do Brasil e produzem,\nentre outros traumas, fratura da diáfise da tíbia, a sede\nmais comum de fratura em ossos longos. Com relação à fratura da diáfise da tíbia, assinale a\nalternativa correta.","options":{"A":"A radiografia é o exame determinante para definir o tratamento e o prognóstico.","B":"As bactérias envolvidas em infecção originam-se nos contaminantes pré-hospitalares.","C":"Nas fraturas expostas, o tratamento precoce com antibióticos reduz a taxa de infecção.","D":"Perfusão e pulso periféricos são importantes para afastar síndrome compartimental.","E":"Quando expostas, o fechamento deve ser retardado para diminuir a taxa de infecção."},"answer":"D","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-57223","number":"57223","sourceNumber":"57223","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na via de acesso posterior à articulação sacroilíaca, o tracionamento inferior excessivo\ndo músculo glúteo máximo pode causar lesão dos:","options":{"A":"Artéria e nervo glúteos superiores.","B":"Artéria e nervo femorais.","C":"Artéria e nervo isquiáticos.","D":"Artéria e nervo laterais da coxa.","E":"Artéria e nervo glúteos interiores."},"answer":"E","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-46043","number":"46043","sourceNumber":"46043","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Considerando as lesões traumáticas do anel pélvico e acetábulo, assinale a alternativa\nCORRETA:","options":{"A":"Deve-se sempre aplicar um protocolo, como o ATLS, por exemplo, na avaliação inicial, devido ao\nrisco de lesões associadas (trauma de alta energia).","B":"Nas lesões do anel pélvico, antes de instituir-se um tratamento na emergência, deve-se sempre\naguardar os resultados de raios X e\ntomografias axiais computadorizadas em 3D.","C":"O tratamento com fixador externo é reservado aos casos de fraturas expostas apenas.","D":"As fraturas/luxações posteriores do acetábulo podem comprometer, mais frequentemente, o\nnervo femoral.","E":"As fraturas de pelve em ?livro aberto? não comprometem a estabilidade hemodinâmica do\npaciente, pois promovem um tamponamento sanguíneo imediato."},"answer":"A","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-43637","number":"43637","sourceNumber":"43637","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Um homem de 68 anos apresenta-se com queixa de dor em região de virilha direita há\n18 meses. Apresenta como comorbidade\nhipertensão arterial com um controle razoável. A dor é\npior com as caminhadas e ao subir escadas e melhora com o repouso. Não há dor noturna ou\nrigidez matinal, embora os primeiros passos da manhã ou quando o paciente se levanta de uma\ncadeira sejam mais difíceis. No exame físico, as manobras de FABER (ou FABERE),\nTrendelenburg e Thomas são positivas à direita. Com relação a esse caso, é INCORRETO afirmar:","options":{"A":"Os achados da radiografia simples da articulação acometida incluem diminuição assimétrica do\nespaço articular, esclerose óssea e formação de\nosteófitos.","B":"No manejo não farmacológico dessa condição, diminuir a sobrecarga da estrutura acometida\ncom uma bengala, fortalecer a musculatura ao\nredor dessa estrutura e evitar impacto são medidas\nimportantes.","C":"A medicação de escolha no manejo analgésico desse paciente é o paracetamol.","D":"Exames importantes na avaliação desse paciente incluem provas de atividade inflamatória e o\nHLA-B27.","E":"O resultado do tratamento cirúrgico de eleição para esse problema é muito eficaz, com grande\nmelhora da dor e da função."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-ortopedia-ort-unico-46374","number":"46374","sourceNumber":"46374","collectionBlock":"medcurso:medcurso-ortopedia-ort-unico","collectionLabel":"Medcurso · ORT UNICO","documentBlock":"","area":"Ortopedia","specialty":"Ortopedia","topic":"ORT UNICO","subtopic":"","stem":"Na displasia do desenvolvimento do quadril, em crianças de até 6 meses de idade,\nindica-se como exame de imagem a:","options":{"A":"Ressonância magnética.","B":"Tomografia axial computadorizada.","C":"Ultrassonografia.","D":"Radiografia simples.","E":"Artrografia."},"answer":"C","source":"Ortopedia/ORT UNICO.txt","sourceLabel":"Medcurso · ORT UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Ortopedia","ORT UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
